    is_remote_resource_source,\n    require_remote_resource_source,\n)\nfrom openviking.server.user_config import (\n    effective_resource_add_target,\n    effective_skill_add_target,\n)\nfrom openviking.service.task_domain import TaskPatch\nfrom openviking.storage.acl import AclAction, AclSpec\nfrom openviking.storage.pathlock_transfer import PathLockGuard\nfrom openviking.storage.queuefs import QueueManager, get_queue_manager\nfrom openviking.storage.queuefs.add_resource_msg import AddResourcePhase\nfrom openviking.storage.viking_fs import LS_ALL_NODES, VikingFS\nfrom openviking.storage.vikingdb_manager import VikingDBManager\nfrom openviking.telemetry import get_current_telemetry, register_telemetry, unregister_telemetry\nfrom openviking.utils import is_git_repo_url, is_github_url, parse_code_hosting_url\nfrom openviking.utils.git_auth import (\n    GitHttpAuthConfig,\n    build_git_http_auth_env,\n    is_git_https_url,\n    parse_git_http_auth_config,\n    raise_git_auth_error,\n    reject_git_http_userinfo,\n)\nfrom openviking.utils.ingest_options import IngestOptions\nfrom openviking.utils.media_processor import _smart_stem\nfrom openviking.utils.network_guard import ensure_public_remote_target\nfrom openviking.utils.path_safety import normalize_storage_target_uri\nfrom openviking.utils.resource_processor import ResourceProcessor\nfrom openviking.utils.skill_processor import SkillProcessingPreparation, SkillProcessor\nfrom openviking_cli.exceptions import (\n    ConflictError,\n    DeadlineExceededError,\n    FailedPreconditionError,\n    InternalError,\n    InvalidArgumentError,\n    NotInitializedError,\n    OpenVikingError,\n)\nfrom openviking_cli.utils import get_logger\n\nif TYPE_CHECKING:\n    from openviking.connector.delegate import ConnectorDelegate\n    from openviking.parse.accessors.base import LocalResource\n    from openviking.resource.shared_source import SharedSource\n    from openviking.resource.staged_source import StagedSource\n    from openviking.resource.watch_manager import WatchManager, WatchTask\n    from openviking.resource.watch_scheduler import WatchScheduler\n    from openviking.service.resource_memory_link_service import ResourceMemoryLinkService\n\nlogger = get_logger(__name__)\n\n\n_ADD_RESOURCE_ARGS_RESERVED_FIELDS = frozenset(\n    {\n        \"path\",\n        \"ctx\",\n        \"to\",\n        \"to_is_directory\",\n        \"parent\",\n        \"reason\",\n        \"instruction\",\n        \"wait\",\n        \"timeout\",\n        \"build_index\",\n        \"summarize\",\n        \"processing_mode\",\n        \"watch_interval\",\n        \"is_active\",\n        \"skip_watch_management\",\n        \"allow_local_path_resolution\",\n        \"enforce_public_remote_targets\",\n        \"resource_lock\",\n        \"stage_callback\",\n        \"args\",\n        \"strict\",\n        \"source_name\",\n        \"ignore_dirs\",\n        \"include\",\n        \"exclude\",\n        \"directly_upload_media\",\n        \"preserve_structure\",\n        \"create_parent\",\n        \"telemetry\",\n        \"request_validator\",\n        \"understanding_response_id\",\n        \"understanding_file_id\",\n        \"parser_backend\",\n        \"resolved_extension\",\n        \"defer_post_processing\",\n        \"prepared_resource\",\n        \"tags\",\n        \"tag_mode\",\n        \"acl\",\n        \"internal_task\",\n        \"target_validator\",\n    }\n)\n_ADD_RESOURCE_TRANSIENT_ARGS = frozenset({\"tos_signature\", \"tos_access\"})\n_ADD_RESOURCE_TAG_MODES = frozenset({\"replace\", \"append\", \"clear\"})\n_DISPLAY_RESOURCE_CONFIG_FIELDS = frozenset({\"resource_name\", \"resource_tag\"})\n\n_INTERNAL_INGESTION_FIELDS = frozenset(\n    {\n        \"manage_watch\",\n        \"parser_args\",\n        \"resource_lock\",\n        \"route_source\",\n        \"skip_watch_management\",\n        \"stage_callback\",\n        \"to_is_directory\",\n        \"watch_auth_state\",\n        \"understanding_response_id\",\n        \"understanding_file_id\",\n        \"parser_backend\",\n        \"resolved_extension\",\n        \"prepared_resource\",\n        \"target_validator\",\n    }\n)\n\n\n@dataclass\nclass _ResourceSourceInfo:\n    source_name: Optional[str] = None\n    source_path: Optional[str] = None\n    source_format: Optional[str] = None\n    head_sha: Optional[str] = None\n\n\n@dataclass\nclass _NormalizedAddResourceArgs:\n    processor_kwargs: Dict[str, Any]\n    watch_auth_state: Optional[Dict[str, Any]] = None\n    parse_mode: ParseMode = ParseMode.DEFAULT\n\n\n@dataclass\nclass _SourcePlan:\n    path: str\n    source_identity: _ResourceSourceInfo\n    processor_args: Dict[str, Any]\n    task_auth: Dict[str, Any] = field(repr=False)\n    staged_source: Optional[\"StagedSource\"] = None\n    shared_source: Optional[\"SharedSource\"] = None\n    understanding_response_id: Optional[str] = None\n    understanding_file_id: Optional[str] = None\n    defer_unnamed_target: bool = False\n\n\ndef _normalized_resource_config(value: Any) -> Dict[str, str]:\n    if not isinstance(value, dict):\n        return {}\n    result: Dict[str, str] = {}\n    for key in _DISPLAY_RESOURCE_CONFIG_FIELDS:\n        item = value.get(key)\n        if isinstance(item, str) and item.strip():\n            result[key] = item.strip()\n    return result\n\n\nclass ResourceService:\n    \"\"\"Resource management service.\"\"\"\n\n    def __init__(\n        self,\n        vikingdb: Optional[VikingDBManager] = None,\n        viking_fs: Optional[VikingFS] = None,\n        resource_processor: Optional[ResourceProcessor] = None,\n        skill_processor: Optional[SkillProcessor] = None,\n        watch_scheduler: Optional[\"WatchScheduler\"] = None,\n        resource_memory_link_service: Optional[\"ResourceMemoryLinkService\"] = None,\n        runtime_config_manager: Optional[Any] = None,\n    ):\n        self._vikingdb = vikingdb\n        self._viking_fs = viking_fs\n        self._resource_processor = resource_processor\n        self._skill_processor = skill_processor\n        self._watch_scheduler = watch_scheduler\n        self._resource_memory_link_service = resource_memory_link_service\n        self._runtime_config_manager = runtime_config_manager\n        self._background_tasks: set[asyncio.Task[Any]] = set()\n        self._connector_delegate: Optional[\"ConnectorDelegate\"] = None\n        self.compile_versions: Optional[Any] = None\n\n    def set_dependencies(\n        self,\n        vikingdb: VikingDBManager,\n        viking_fs: VikingFS,\n        resource_processor: ResourceProcessor,\n        skill_processor: SkillProcessor,\n        watch_scheduler: Optional[\"WatchScheduler\"] = None,\n        resource_memory_link_service: Optional[\"ResourceMemoryLinkService\"] = None,\n        runtime_config_manager: Optional[Any] = None,\n    ) -> None:\n        \"\"\"Set dependencies (for deferred initialization).\"\"\"\n        self._vikingdb = vikingdb\n        self._viking_fs = viking_fs\n        self._resource_processor = resource_processor\n        self._skill_processor = skill_processor\n        self._watch_scheduler = watch_scheduler\n        self._resource_memory_link_service = resource_memory_link_service\n        self._runtime_config_manager = runtime_config_manager\n\n    def _get_watch_manager(self) -> Optional[\"WatchManager\"]:\n        if not self._watch_scheduler:\n            return None\n        return self._watch_scheduler.watch_manager\n\n    async def _ensure_resource_target_available(\n        self, uri: str, ctx: RequestContext, *, is_parent: bool = False\n    ) -> None:\n        \"\"\"Reject active Compile output destinations in this account before ingestion.\n\n        A parent only supplies a new child's location; an exact destination mirrors\n        its subtree and must also exclude Compile targets nested beneath it.\n        \"\"\"\n        if self.compile_versions is None or not uri:\n            return\n        uri = normalize_storage_target_uri(uri)\n        await self._viking_fs._ensure_access(uri, ctx, action=AclAction.WRITE)\n        target = await self.compile_versions.owning_target(ctx.account_id, uri)\n        if target is None and not is_parent:\n            targets = await self.compile_versions._targets_under(ctx.account_id, uri)\n            if targets:\n                target = targets[0]\n        if target is not None:\n            raise ConflictError(\n                \"Add-resource destination overlaps a Compile target.\",\n                resource=\"COMPILE_TARGET\",\n            )\n\n    async def _hold_watch_execution(self, task_id: str) -> bool:\n        \"\"\"Keep the scheduler from running *task_id* while its first round is in flight.\"\"\"\n        hold = getattr(self._watch_scheduler, \"hold_execution\", None)\n        if hold is None:\n            return True\n        return bool(await hold(task_id))\n\n    async def _release_watch_execution(self, task_id: str) -> None:\n        release = getattr(self._watch_scheduler, \"release_execution\", None)\n        if release is not None:\n            await release(task_id)\n\n    async def record_watch_execution(\n        self,\n        task_id: str,\n        *,\n        status: str,\n        execution_task_id: Optional[str] = None,\n        error: Optional[str] = None,\n        source_checkpoint: Optional[Dict[str, Any]] = None,\n    ) -> None:\n        \"\"\"Record a pre-created Watch's first round and release its scheduler hold.\"\"\"\n        sanitized_error = (\n            sanitize_public_http_error(code=\"WATCH_EXECUTION_FAILED\", message=error).message\n            if error\n            else None\n        )\n        try:\n            watch_manager = self._get_watch_manager()\n            if watch_manager is not None:\n                await watch_manager.record_execution(\n                    task_id,\n                    status=status,\n                    execution_task_id=execution_task_id,\n                    error=error,\n                )\n                if status == \"completed\" and source_checkpoint is not None:\n                    await watch_manager.update_source_checkpoint(\n                        task_id,\n                        source_checkpoint,\n                    )\n                logger.info(\n                    \"[ResourceService] Watch first round recorded: watch_task_id=%s status=%s \"\n                    \"execution_task_id=%s%s\",\n                    task_id,\n                    status,\n                    execution_task_id,\n                    f\" error={sanitized_error}\" if sanitized_error else \"\",\n                )\n        finally:\n            await self._release_watch_execution(task_id)\n\n    def _sanitize_watch_processor_kwargs(self, processor_kwargs: Dict[str, Any]) -> Dict[str, Any]:\n        sanitized: Dict[str, Any] = {}\n        for key, value in processor_kwargs.items():\n            if key in {\n                \"auth_config\",\n                \"lark_file\",\n                FEISHU_ACCESS_TOKEN_ARG,\n                FEISHU_REFRESH_TOKEN_ARG,\n                OAUTH_REF_ARG,\n                \"parser_backend\",\n                \"resolved_extension\",\n                \"understanding_response_id\",\n                \"understanding_file_id\",\n                \"temp_file_id\",\n                \"git_head_sha_hint\",\n            }:\n                continue\n            try:\n                json.dumps(value, ensure_ascii=False)\n            except TypeError:\n                continue\n            sanitized[key] = value\n        return sanitized\n\n    def _watch_processor_kwargs(\n        self,\n        processor_kwargs: Dict[str, Any],\n        tags: Optional[List[str]],\n        tag_mode: str,\n    ) -> Dict[str, Any]:\n        watch_kwargs = self._sanitize_watch_processor_kwargs(processor_kwargs)\n        if tags is not None or tag_mode == \"clear\":\n            if tags is not None:\n                watch_kwargs[\"tags\"] = tags\n            watch_kwargs[\"tag_mode\"] = tag_mode\n        return watch_kwargs\n\n    @staticmethod\n    def _infer_watch_source_type(path: str) -> Optional[str]:\n        if not path:\n            return None\n        from openviking.parse.accessors.feishu_accessor import FeishuAccessor\n\n        if FeishuAccessor._is_feishu_url(path):\n            return \"feishu\"\n        if is_git_repo_url(path):\n            return \"git\"\n        if is_remote_resource_source(path):\n            return \"url\"\n        return \"local\"\n\n    def _validate_add_resource_tag_policy(\n        self,\n        *,\n        tags: Optional[List[str]],\n        tag_mode: str,\n    ) -> None:\n        if (tags is not None or tag_mode == \"clear\") and tag_mode not in _ADD_RESOURCE_TAG_MODES:\n            raise InvalidArgumentError(f\"unsupported tag mode: {tag_mode}\")\n\n    @staticmethod\n    def _ensure_single_resource_target(\n        *,\n        to: Optional[str],\n        parent: Optional[str],\n    ) -> None:\n        if (to or \"\").strip() and (parent or \"\").strip():\n            raise InvalidArgumentError(\"Cannot specify both 'to' and 'parent' at the same time.\")\n\n    @staticmethod\n    def _initial_source_checkpoint(\n        meta: Any,\n        *,\n        instruction: str = \"\",\n    ) -> Optional[Dict[str, Any]]:\n        \"\"\"Build the watch source checkpoint from the imported revision meta.\n\n        The accessor records ``resolved_head_sha`` for the exact imported\n        revision: a resolved branch tip or the supplied commit-only pin. The\n        tracked branch or commit selection itself lives in processor_kwargs.\n        The instruction is included so changing it forces one refresh even\n        when the source revision is unchanged. Failed branch probes leave the\n        checkpoint unset (fail open).\n        \"\"\"\n        head_sha = meta.get(\"resolved_head_sha\") if isinstance(meta, dict) else None\n        if head_sha:\n            return {\n                \"kind\": \"git\",\n                \"head_sha\": head_sha,\n                \"instruction\": instruction,\n            }\n        return None\n\n    async def _manage_watch_if_needed(\n        self,\n        *,\n        watch_manager: Optional[\"WatchManager\"],\n        manage_watch: bool,\n        watch_interval: float,\n        to: str,\n        parent: str,\n        to_is_directory: bool,\n        root_uri: str,\n        path: str,\n        reason: str,\n        instruction: str,\n        build_index: bool,\n        summarize: bool,\n        processing_mode: ProcessingMode,\n        processor_kwargs: Dict[str, Any],\n        watch_auth_state: Optional[Dict[str, Any]],\n        ctx: RequestContext,\n        source_type: Optional[str] = None,\n        connector_states: Optional[Dict[str, Any]] = None,\n        is_active: Optional[bool] = None,\n        on_watch_ready: Optional[Callable[[str], None]] = None,\n    ) -> None:\n        if not watch_manager or not manage_watch:\n            return\n        telemetry = get_current_telemetry()\n        with telemetry.measure(\"resource.watch\"):\n            if watch_interval > 0:\n                watch_to = to\n                parent_uri = parent\n                if not watch_to:\n                    watch_to = root_uri\n                    parent_uri = None\n                if not watch_to:\n                    raise InvalidArgumentError(\n                        \"watch_interval > 0 requires a stable target URI. \"\n                        \"Pass 'to' explicitly, or add a resource type that returns root_uri.\"\n                    )\n                if processor_kwargs.get(\"temp_file_id\"):\n                    # An uploaded source is a static snapshot, so a watch task recorded\n                    # against it would re-process the frozen snapshot every interval.\n                    raise InvalidArgumentError(\n                        \"watch_interval > 0 is not supported for uploaded content: an \"\n                        \"upload is a static snapshot, so the watch would re-process \"\n                        \"stale content forever. Watch a URL / \"\n                        \"sitemap / RSS source instead, or re-add the resource when the \"\n                        \"source changes.\"\n                    )\n                try:\n                    sanitized = self._sanitize_watch_processor_kwargs(processor_kwargs)\n                    watch = await self._handle_watch_task_creation(\n                        path=path,\n                        to_uri=watch_to,\n                        to_is_directory=to_is_directory,\n                        parent_uri=parent_uri,\n                        reason=reason,\n                        instruction=instruction,\n                        watch_interval=watch_interval,\n                        build_index=build_index,\n                        summarize=summarize,\n                        processing_mode=processing_mode,\n                        processor_kwargs=sanitized,\n                        auth_state=watch_auth_state,\n                        connector_states=connector_states,\n                        source_type=source_type or self._infer_watch_source_type(path),\n                        ctx=ctx,\n                        is_active=is_active is not False,\n                    )\n                    if watch is not None and on_watch_ready is not None:\n                        on_watch_ready(watch.task_id)\n                except ConflictError:\n                    raise\n                except Exception as e:\n                    logger.warning(\n                        f\"[ResourceService] Failed to create watch task for {watch_to}: {e}\"\n                    )\n            elif to:\n                try:\n                    await self._handle_watch_task_cancellation(to_uri=to, ctx=ctx)\n                except ConflictError:\n                    raise\n                except Exception as e:\n                    logger.warning(f\"[ResourceService] Failed to cancel watch task for {to}: {e}\")\n\n    async def _normalize_add_resource_args(\n        self,\n        args: Optional[Dict[str, Any]],\n        *,\n        watch_interval: float,\n        ctx: RequestContext,\n        allowed_reserved_fields: Optional[set[str]] = None,\n    ) -> _NormalizedAddResourceArgs:\n        if args is None:\n            return _NormalizedAddResourceArgs({})\n        if not isinstance(args, dict):\n            raise InvalidArgumentError(\"args must be an object.\")\n        if not args:\n            return _NormalizedAddResourceArgs({})\n\n        reserved_fields = _ADD_RESOURCE_ARGS_RESERVED_FIELDS - (allowed_reserved_fields or set())\n        reserved = sorted(set(args).intersection(reserved_fields))\n        if reserved:\n            raise InvalidArgumentError(\n                \"args cannot contain core add_resource fields: \" + \", \".join(reserved)\n            )\n\n        normalized = dict(args)\n        validate_feishu_auth_args(normalized)\n        raw_parse_mode = normalized.pop(\"parse_mode\", ParseMode.DEFAULT)\n        try:\n            parse_mode = normalize_parse_mode(raw_parse_mode)\n        except InvalidArgumentError as exc:\n            raise InvalidArgumentError(str(exc).replace(\"parse_mode\", \"args.parse_mode\")) from exc\n        token = normalized.get(FEISHU_ACCESS_TOKEN_ARG)\n        refresh_token = normalized.pop(FEISHU_REFRESH_TOKEN_ARG, None)\n        app_id = normalized.pop(FEISHU_APP_ID_ARG, None)\n        app_secret = normalized.pop(FEISHU_APP_SECRET_ARG, None)\n        has_app_credentials = app_id is not None or app_secret is not None\n        watch_auth_state = None\n        if token is not None:\n            if not isinstance(token, str) or not token.strip():\n                raise InvalidArgumentError(\"args.feishu_access_token must be a non-empty string.\")\n            token = token.strip()\n            normalized[FEISHU_ACCESS_TOKEN_ARG] = token\n            if watch_interval > 0:\n                if not isinstance(refresh_token, str) or not refresh_token.strip():\n                    raise InvalidArgumentError(\n                        \"args.feishu_refresh_token must be a non-empty string when \"\n                        \"args.feishu_access_token is used with watch_interval > 0.\"\n                    )\n                if self._runtime_config_manager is None:\n                    raise RuntimeError(\"Runtime config manager is not initialized\")\n                from openviking.config.feishu import get_effective_feishu_config\n\n                feishu_config = await get_effective_feishu_config(\n                    self._runtime_config_manager,\n                    ctx.account_id,\n                )\n                app_credentials = self._load_feishu_credentials_for_watch(\n                    app_id, app_secret, feishu_config\n                )\n                watch_auth_state = create_feishu_auth_state(\n                    token,\n                    refresh_token.strip(),\n                    app_credentials,\n                    persist_app_secret=app_id is not None or app_secret is not None,\n                )\n            elif refresh_token is not None:\n                raise InvalidArgumentError(\n                    \"args.feishu_refresh_token is only supported with \"\n                    \"args.feishu_access_token and watch_interval > 0.\"\n                )\n            elif has_app_credentials:\n                raise InvalidArgumentError(\n                    \"args.feishu_app_id and args.feishu_app_secret are only supported with \"\n                    \"args.feishu_access_token and watch_interval > 0.\"\n                )\n        elif refresh_token is not None:\n            raise InvalidArgumentError(\n                \"args.feishu_refresh_token requires args.feishu_access_token.\"\n            )\n        elif has_app_credentials:\n            raise InvalidArgumentError(\n                \"args.feishu_app_id and args.feishu_app_secret require \"\n                \"args.feishu_access_token and watch_interval > 0.\"\n            )\n\n        return _NormalizedAddResourceArgs(normalized, watch_auth_state, parse_mode)\n\n    def _load_feishu_credentials_for_watch(\n        self,\n        app_id: Any,\n        app_secret: Any,\n        config,\n    ) -> FeishuAppCredentials:\n        supplied = app_id is not None or app_secret is not None\n        if supplied and (\n            not isinstance(app_id, str)\n            or not app_id.strip()\n            or not isinstance(app_secret, str)\n            or not app_secret.strip()\n        ):\n            raise InvalidArgumentError(\n                \"args.feishu_app_id and args.feishu_app_secret must be non-empty strings \"\n                \"and provided together.\"\n            )\n        try:\n            credentials = load_feishu_app_credentials(\n                config=config,\n                app_id=app_id.strip() if supplied else None,\n                app_secret=app_secret.strip() if supplied else None,\n            )\n        except Exception as exc:\n            raise InvalidArgumentError(\n                \"Feishu user-token watch requires FEISHU_APP_ID and \"\n                \"FEISHU_APP_SECRET, or feishu.app_id and feishu.app_secret in ov.conf.\"\n            ) from exc\n        # A user refresh token is bound to the Feishu application that issued\n        # it. Persist the effective app identity even when the caller used the\n        # account default, so a later account-config change cannot pair an old\n        # refresh token with a different app.\n        return credentials\n\n    def _ensure_initialized(self) -> None:\n        \"\"\"Ensure all dependencies are initialized.\"\"\"\n        if not self._resource_processor:\n            raise NotInitializedError(\"ResourceProcessor\")\n        if not self._skill_processor:\n            raise NotInitializedError(\"SkillProcessor\")\n        if not self._viking_fs:\n            raise NotInitializedError(\"VikingFS\")\n\n    async def _lock_to_handoff_payload(self, lock_ref: Any) -> Optional[Dict[str, Any]]:\n        \"\"\"Convert either a native pathlock ref or legacy lease into a handoff payload.\"\"\"\n        if lock_ref is None:\n            return None\n        async_agfs = getattr(self._viking_fs, \"_async_agfs\", None)\n        if async_agfs is not None:\n            return await PathLockGuard(async_agfs, lock_ref).to_handoff()\n        to_handoff = getattr(lock_ref, \"to_handoff\", None)\n        if callable(to_handoff):\n            handoff = to_handoff()\n            return handoff.to_dict() if hasattr(handoff, \"to_dict\") else handoff\n        return lock_ref if isinstance(lock_ref, dict) else None\n\n    async def _handoff_lock_ref(self, lock_ref: Any) -> None:\n        \"\"\"Transfer ownership for either a native pathlock ref or legacy lease.\"\"\"\n        if lock_ref is None:\n            return\n        async_agfs = getattr(self._viking_fs, \"_async_agfs\", None)\n        if async_agfs is not None:\n            await async_agfs.pathlock_handoff(lock_ref)\n            return\n        handoff = getattr(lock_ref, \"handoff\", None)\n        if callable(handoff):\n            result = handoff()\n            if inspect.isawaitable(result):\n                await result\n\n    async def _adopt_lock_ref(self, handoff_ref: Any) -> Any:\n        \"\"\"Recover ownership from a handoff after enqueue fails.\"\"\"\n        async_agfs = getattr(self._viking_fs, \"_async_agfs\", None)\n        if async_agfs is not None:\n            return await async_agfs.pathlock_adopt(handoff_ref)\n        adopt = getattr(handoff_ref, \"adopt\", None)\n        if callable(adopt):\n            result = adopt()\n            return await result if inspect.isawaitable(result) else result\n        raise RuntimeError(\"Lock handoff cannot be adopted\")\n\n    async def _release_lock_ref(self, lock_ref: Any) -> None:\n        \"\"\"Release either a native pathlock ref or legacy lease.\"\"\"\n        if lock_ref is None:\n            return\n        async_agfs = getattr(self._viking_fs, \"_async_agfs\", None)\n        if async_agfs is not None:\n            await async_agfs.pathlock_release(lock_ref)\n            return\n        close = getattr(lock_ref, \"close\", None)\n        if callable(close):\n            result = close()\n            if inspect.isawaitable(result):\n                await result\n\n    async def _cleanup_reserved_target_if_empty(\n        self,\n        *,\n        root_uri: str,\n        ctx: RequestContext,\n        resource_lock: Dict[str, Any],\n    ) -> bool:\n        \"\"\"Remove a newly reserved target only while it is still empty.\"\"\"\n        ctx = replace(ctx, bypass_acl=True)\n        try:\n            if not await self._viking_fs.exists(root_uri, ctx=ctx):\n                return True\n            stat = await self._viking_fs.stat(root_uri, ctx=ctx, skip_count=True)\n            if not isinstance(stat, dict) or not stat.get(\"isDir\"):\n                return False\n            entries = await self._viking_fs.ls(\n                root_uri,\n                show_all_hidden=True,\n                node_limit=LS_ALL_NODES,\n                ctx=ctx,\n            )\n            if any(entry.get(\"name\") not in {None, \"\", \".\", \"..\"} for entry in entries):\n                return False\n            await self._viking_fs.rm(\n                root_uri,\n                recursive=True,\n                ctx=ctx,\n                lease_ref=resource_lock,\n            )\n            return True\n        except Exception as exc:\n            logger.warning(\n                \"[ResourceService] Failed to clean empty reserved target %s: %s\",\n                root_uri,\n                exc,\n            )\n            return False\n\n    async def close_background_tasks(self) -> None:\n        \"\"\"Cancel in-flight connector monitoring tasks during service shutdown.\"\"\"\n        if not self._background_tasks:\n            return\n        tasks = list(self._background_tasks)\n        for task in tasks:\n            task.cancel()\n        await asyncio.gather(*tasks, return_exceptions=True)\n        self._background_tasks.clear()\n\n    def _unregister_telemetry_after_task(\n        self,\n        task_id: str,\n        telemetry_id: str,\n        *,\n        account_id: str,\n        user_id: str,\n    ) -> None:\n        async def wait_and_unregister() -> None:\n            from openviking.service.task_tracker import get_task_tracker\n\n            try:\n                await get_task_tracker().wait(\n                    task_id,\n                    account_id=account_id,\n                    user_id=user_id,\n                )\n            finally:\n                unregister_telemetry(telemetry_id)\n\n        background = asyncio.create_task(wait_and_unregister())\n        self._background_tasks.add(background)\n        background.add_done_callback(self._background_tasks.discard)\n\n    async def _enqueue_add_resource_job(\n        self,\n        msg: Any,\n        *,\n        queue_name: str,\n        resource_lock: Optional[Dict[str, Any]] = None,\n        task_auth: Optional[Dict[str, Any]] = None,\n        on_enqueued: Optional[Callable[[], None]] = None,\n        on_failed_with_lock: Optional[Callable[[Dict[str, Any]], Awaitable[None]]] = None,\n    ) -> Any:\n        \"\"\"Persist a job and fully own the passed lock until handoff or release completes.\"\"\"\n        from openviking.service.task_tracker import get_task_tracker\n        from openviking.service.task_work_index import bind_task_context\n        from openviking.storage.queuefs import get_queue_manager\n\n        tracker = get_task_tracker()\n        task = None\n        enqueued = False\n        lock_ops = getattr(self._viking_fs, \"_async_agfs\", None) or SimpleNamespace(\n            pathlock_handoff=self._handoff_lock_ref,\n            pathlock_adopt=self._adopt_lock_ref,\n            pathlock_release=self._release_lock_ref,\n        )\n        lock_guard = PathLockGuard(lock_ops, resource_lock)\n        try:\n            task = await tracker.create(\n                \"add_resource\",\n                resource_id=None if msg.defer_target_resolution else msg.root_uri,\n                account_id=msg.account_id,\n                user_id=msg.user_id,\n                task_id=msg.task_id,\n                meta=(\n                    {\"internal\": True} if msg.internal_task else {\"source_path\": msg.source_path}\n                ),\n                auth=task_auth,\n            )\n            task_account_id = getattr(task, \"account_id\", msg.account_id)\n            task_user_id = getattr(task, \"user_id\", msg.user_id)\n\n            async def dispatch() -> str:\n                nonlocal enqueued\n                with bind_task_context(task.task_id, task_account_id, task_user_id):\n                    result = await get_queue_manager().enqueue(queue_name, msg.to_dict())\n                enqueued = True\n                if on_enqueued is not None:\n                    on_enqueued()\n                return result\n\n            if resource_lock is not None:\n                await lock_guard.handoff_and_dispatch(msg.lock_handoff, dispatch)\n            else:\n                await dispatch()\n            await tracker.patch_task(\n                task.task_id,\n                TaskPatch(stage=\"queued\"),\n                account_id=msg.account_id,\n                user_id=msg.user_id,\n            )\n        except BaseException:\n            if lock_guard.lease is not None:\n                try:\n                    if on_failed_with_lock is not None:\n                        await on_failed_with_lock(lock_guard.lease)\n                finally:\n                    await lock_guard.close()\n            if task is not None and not enqueued:\n                await tracker.fail(\n                    task.task_id,\n                    \"Failed to enqueue resource processing\",\n                    account_id=msg.account_id,\n                    user_id=msg.user_id,\n                )\n            raise\n\n        return task\n\n    async def execute_add_resource_job(\n        self,\n        msg: Any,\n        *,\n        ctx: RequestContext,\n        resource_lock: Optional[Dict[str, Any]],\n        stage_callback: Callable[[str], Any],\n        task_auth: Optional[Dict[str, Any]] = None,\n    ) -> Dict[str, Any]:\n        \"\"\"Execute one durable add-resource job inside its QueueFS consumer.\"\"\"\n        if msg.job_phase is AddResourcePhase.SOURCE:\n            from openviking.resource.staged_source import StagedSource, materialize_source\n\n            target_uri = msg.root_uri\n            parent_uri = None\n            queued_args = dict(msg.args)\n            legacy_backend = normalize_parser_backend(queued_args.pop(\"parser_backend\", None))\n            feishu_prepared = queued_args.pop(\"_feishu_prepared_source\", False)\n            parser_backend = legacy_backend or (\n                ParserBackend.UNDERSTANDING\n                if msg.understanding_response_id is not None\n                or msg.understanding_file_id is not None\n                else None\n                if feishu_prepared\n                else ParserBackend.INTERNAL\n            )\n            internal_kwargs: Dict[str, Any] = {\"parser_backend\": parser_backend}\n            if \"resolved_extension\" in queued_args:\n                internal_kwargs[\"resolved_extension\"] = queued_args.pop(\"resolved_extension\")\n            normalized_args = await self._normalize_add_resource_args(\n                queued_args,\n                ctx=ctx,\n                watch_interval=msg.watch_interval,\n            )\n            internal_kwargs.update(normalized_args.processor_kwargs)\n            if msg.strict:\n                internal_kwargs[\"strict\"] = True\n            if msg.ignore_dirs is not None:\n                internal_kwargs[\"ignore_dirs\"] = msg.ignore_dirs\n            if msg.include is not None:\n                internal_kwargs[\"include\"] = msg.include\n            if msg.exclude is not None:\n                internal_kwargs[\"exclude\"] = msg.exclude\n            if not msg.directly_upload_media:\n                internal_kwargs[\"directly_upload_media\"] = False\n            if msg.preserve_structure is not None:\n                internal_kwargs[\"preserve_structure\"] = msg.preserve_structure\n            if msg.create_parent:\n                internal_kwargs[\"create_parent\"] = True\n            if msg.source_name is not None:\n                internal_kwargs[\"source_name\"] = msg.source_name\n            if msg.git_head_sha_hint:\n                # One-shot SHA resolved by the add_resource preflight; lets\n                # the accessor download an immutable revision without a second\n                # ls-remote. Transient: never persisted into watch kwargs.\n                internal_kwargs[\"git_head_sha_hint\"] = msg.git_head_sha_hint\n            if feishu_prepared:\n                from openviking.service.task_tracker import get_task_tracker\n\n                tracker = get_task_tracker()\n                task = await tracker.get(msg.task_id, ctx.account_id, ctx.user.user_id)\n                saved = dict(task.meta.get(\"feishu_responses\", {})) if task else {}\n\n                async def save_response(entry: str, response_id: str) -> None:\n                    await tracker.patch_task(\n                        msg.task_id,\n                        TaskPatch(meta={\"feishu_responses\": {entry: response_id}}),\n                        account_id=ctx.account_id,\n                        user_id=ctx.user.user_id,\n                    )\n                    saved[entry] = response_id\n\n                internal_kwargs[\"_feishu_checkpoint\"] = (saved, save_response)\n            prepared_resource = None\n            if msg.staged_source is not None:\n                with get_current_telemetry().measure(\"resource.source_prepare\"):\n                    prepared_resource = await materialize_source(\n                        StagedSource.from_dict(msg.staged_source),\n                        viking_fs=self._viking_fs,\n                        ctx=ctx,\n                    )\n            elif msg.shared_source is not None:\n                from openviking.resource.shared_source import (\n                    SharedSource,\n                    materialize_shared_source,\n                )\n\n                with get_current_telemetry().measure(\"resource.source_prepare\"):\n                    prepared_resource = await materialize_shared_source(\n                        SharedSource.from_dict(msg.shared_source),\n                        viking_fs=self._viking_fs,\n                        ctx=ctx,\n                    )\n            if msg.defer_target_resolution:\n                from openviking_cli.utils.uri import VikingURI\n\n                target_uri = None\n                parent_uri = VikingURI(msg.root_uri).parent.uri\n            if msg.understanding_response_id is not None:\n                from openviking.parse.understanding_api import PREPARED_RESPONSE_ID_ARG\n\n                internal_kwargs[PREPARED_RESPONSE_ID_ARG] = msg.understanding_response_id\n            if msg.understanding_file_id is not None:\n                from openviking.parse.understanding_api import PREPARED_FILE_ID_ARG\n\n                internal_kwargs[PREPARED_FILE_ID_ARG] = msg.understanding_file_id\n            try:\n                async with feishu_auth_scope(\n                    self._connector,\n                    path=msg.path,\n                    ctx=ctx,\n                    args=internal_kwargs,\n                    state=task_auth,\n                    prepared=(\n                        msg.understanding_response_id is not None\n                        or msg.understanding_file_id is not None\n                    ),\n                ) as auth_state:\n                    auth_kwargs, watch_auth_state = self._restore_source_task_auth(\n                        msg, auth_state or {}\n                    )\n                    internal_kwargs.update(auth_kwargs)\n                    result = await self._execute_resource_ingestion(\n                        path=msg.path,\n                        ctx=ctx,\n                        to=target_uri,\n                        parent=parent_uri,\n                        to_is_directory=msg.to_is_directory,\n                        reason=msg.reason,\n                        instruction=msg.instruction,\n                        defer_post_processing=False,\n                        build_index=msg.build_index,\n                        summarize=msg.summarize,\n                        processing_mode=msg.processing_mode,\n                        parse_mode=msg.parse_mode,\n                        watch_interval=msg.watch_interval,\n                        is_active=msg.is_active,\n                        manage_watch=not msg.skip_watch_management,\n                        acl=msg.acl,\n                        tags=msg.tags,\n                        tag_mode=msg.tag_mode,\n                        allow_local_path_resolution=msg.allow_local_path_resolution,\n                        enforce_public_remote_targets=msg.enforce_public_remote_targets,\n                        resource_lock=resource_lock,\n                        stage_callback=stage_callback,\n                        watch_auth_state=watch_auth_state,\n                        prepared_resource=prepared_resource,\n                        internal_task=msg.internal_task,\n                        on_watch_ready=lambda task_id: setattr(msg, \"watch_task_id\", task_id),\n                        **internal_kwargs,\n                    )\n            except BaseException:\n                if msg.cleanup_empty_target_on_failure and resource_lock is not None:\n                    await self._cleanup_reserved_target_if_empty(\n                        root_uri=msg.root_uri,\n                        ctx=ctx,\n                        resource_lock=resource_lock,\n                    )\n                raise\n            if (\n                result.get(\"status\") == \"error\"\n                and msg.cleanup_empty_target_on_failure\n                and resource_lock is not None\n            ):\n                await self._cleanup_reserved_target_if_empty(\n                    root_uri=msg.root_uri,\n                    ctx=ctx,\n                    resource_lock=resource_lock,\n                )\n            if msg.staged_source is not None or msg.shared_source is not None:\n                result[\"source_path\"] = msg.source_path\n            stage_result = stage_callback(\"processing_queue\")\n            if inspect.isawaitable(stage_result):\n                await stage_result\n            return result\n\n        stage_result = stage_callback(\"processing_queue\")\n        if inspect.isawaitable(stage_result):\n            await stage_result\n        return await self._resource_processor.finish_prepared_resource(\n            msg.prepared,\n            ctx=ctx,\n            resource_lock=resource_lock,\n            summarize=msg.summarize,\n            build_index=msg.build_index,\n            processing_mode=msg.processing_mode,\n            ingest_options=IngestOptions.from_search_tags(msg.tags, mode=msg.tag_mode),\n        )\n\n    def _restore_source_task_auth(\n        self,\n        msg: Any,\n        task_auth: Dict[str, Any],\n    ) -> tuple[Dict[str, Any], Optional[Dict[str, Any]]]:\n        \"\"\"Restore provider-specific request inputs from task-owned auth state.\"\"\"\n        if not task_auth:\n            return {}, None\n        creating_watch = msg.watch_interval > 0 and not msg.skip_watch_management\n        if is_external_feishu_auth(task_auth):\n            return {}, task_auth if msg.watch_interval > 0 else None\n        if is_git_http_auth_state(task_auth):\n            auth_config = git_http_auth_config_from_state(task_auth, msg.path)\n            watch_auth_state = dict(task_auth) if creating_watch else None\n            return {\"auth_config\": auth_config}, watch_auth_state\n        if is_feishu_auth_state(task_auth):\n            token = task_auth.get(\"access_token\")\n            if not isinstance(token, str) or not token.strip():\n                raise InvalidArgumentError(\"Stored Feishu task credentials are invalid.\")\n            if creating_watch:\n                refresh_token = task_auth.get(\"refresh_token\")\n                if not isinstance(refresh_token, str) or not refresh_token.strip():\n                    raise InvalidArgumentError(\n                        \"Stored Feishu watch credentials are missing a refresh token.\"\n                    )\n                watch_auth_state = dict(task_auth)\n                watch_auth_state.pop(\"domain\", None)\n                watch_auth_state.pop(\"request_timeout\", None)\n            else:\n                watch_auth_state = None\n            auth_kwargs = (\n                {FEISHU_ACCESS_TOKEN_ARG: token.strip()}\n                if msg.understanding_response_id is None and msg.understanding_file_id is None\n                else {}\n            )\n            return auth_kwargs, watch_auth_state\n        raise InvalidArgumentError(\"Unsupported task authentication provider.\")\n\n    async def reacquire_add_resource_job_lock(\n        self,\n        root_uri: str,\n        ctx: RequestContext,\n    ) -> Dict[str, Any]:\n        \"\"\"Acquire a fresh lock when a recovered job's old handoff was released.\"\"\"\n        if not self._resource_processor or not self._viking_fs:\n            raise NotInitializedError(\"ResourceProcessor\")\n\n        dst_path = self._viking_fs._uri_to_path(root_uri, ctx=ctx)\n        return await self._viking_fs._async_agfs.pathlock_acquire_tree(\n            dst_path,\n            timeout_secs=0.0,\n        )\n\n    async def _prepare_standard_source_plan(\n        self,\n        *,\n        path: str,\n        ctx: RequestContext,\n        mode: ParseMode,\n        allow_local_path_resolution: bool,\n        processor_kwargs: Dict[str, Any],\n        watch_auth_state: Optional[Dict[str, Any]],\n        shared_source: Optional[\"SharedSource\"] = None,\n    ) -> Optional[_SourcePlan]:\n        \"\"\"Freeze one durable standard-pipeline source before it crosses QueueFS.\"\"\"\n        from openviking.parse.accessors.feishu_accessor import FeishuAccessor\n        from openviking.resource.staged_source import stage_source\n\n        source_name = processor_kwargs.get(\"source_name\")\n        # A shared upload is already durable; reference it directly instead of\n        # downloading + re-staging a second copy. Its identity comes from the\n        # validated upload meta, so no accessor preflight is needed.\n        if shared_source is not None:\n            queued_args = {\n                key: value\n                for key, value in processor_kwargs.items()\n                if key not in _ADD_RESOURCE_ARGS_RESERVED_FIELDS | _ADD_RESOURCE_TRANSIENT_ARGS\n            }\n            queued_args = self._sanitize_watch_processor_kwargs(queued_args)\n            resolved_name = source_name or shared_source.original_filename or None\n            source_format = (\n                Path(shared_source.original_filename).suffix.lower().lstrip(\".\") or \"file\"\n            )\n            return _SourcePlan(\n                path=path,\n                source_identity=_ResourceSourceInfo(\n                    source_name=resolved_name,\n                    source_path=shared_source.original_filename or path,\n                    source_format=source_format,\n                ),\n                processor_args=queued_args,\n                task_auth={},\n                shared_source=shared_source,\n            )\n\n        git_source = is_git_repo_url(path)\n        feishu_source = FeishuAccessor._is_feishu_url(path)\n        remote_source = is_remote_resource_source(path)\n        local_source = False\n        if allow_local_path_resolution and len(path) <= 1024 and \"\\n\" not in path:\n            with contextlib.suppress(OSError, ValueError):\n                local_source = Path(path).exists()\n        if not (git_source or feishu_source or remote_source or local_source):\n            return None\n\n        queued_args = {\n            key: value\n            for key, value in processor_kwargs.items()\n            if key not in _ADD_RESOURCE_ARGS_RESERVED_FIELDS | _ADD_RESOURCE_TRANSIENT_ARGS\n        }\n        queued_args = self._sanitize_watch_processor_kwargs(queued_args)\n        task_auth: Dict[str, Any] = {}\n        staged_source = None\n        understanding_response_id = None\n        understanding_file_id = None\n        defer_unnamed_target = False\n\n        if git_source:\n            reject_git_http_userinfo(path)\n            from openviking.connector.routing import credential_arg_names\n\n            credential_args = credential_arg_names(\"git\", processor_kwargs)\n            if credential_args:\n                raise InvalidArgumentError(\"Native Git credentials must use args.auth_config.\")\n            request_git_auth = parse_git_http_auth_config(processor_kwargs.get(\"auth_config\"), path)\n            if request_git_auth is not None:\n                task_auth = create_git_http_auth_state(request_git_auth, path)\n            preflight_git_auth = request_git_auth\n            if preflight_git_auth is None and is_git_https_url(path) and is_github_url(path):\n                github_token = await self._resource_processor.github_token_for(path, ctx)\n                if github_token:\n                    preflight_git_auth = GitHttpAuthConfig(\n                        username=\"oauth2\",\n                        token=github_token,\n                    )\n            source_info = await self._preflight_git_source(\n                path,\n                auth_config=preflight_git_auth,\n                branch=processor_kwargs.get(\"branch\") or processor_kwargs.get(\"ref\"),\n                commit=processor_kwargs.get(\"commit\"),\n            )\n            source_name = source_name or source_info.source_name\n            source_info.source_name = source_name\n        elif feishu_source:\n            from openviking.parse.feishu_import import recursive_wiki\n\n            recursive = FeishuAccessor._parse_feishu_url(path)[0] == \"wiki\" and recursive_wiki(\n                processor_kwargs\n            )\n            token = processor_kwargs.get(FEISHU_ACCESS_TOKEN_ARG)\n            if isinstance(token, str) and token.strip():\n                task_auth = dict(\n                    watch_auth_state\n                    or {\n                        \"provider\": FEISHU_AUTH_PROVIDER,\n                        \"access_token\": token.strip(),\n                    }\n                )\n                task_auth.pop(\"domain\", None)\n                task_auth.pop(\"request_timeout\", None)\n            if self._runtime_config_manager is None:\n                raise RuntimeError(\"Runtime config manager is not initialized\")\n            from openviking.config.feishu import get_effective_feishu_config\n\n            feishu_config = await get_effective_feishu_config(\n                self._runtime_config_manager,\n                ctx.account_id,\n            )\n            feishu_kwargs = dict(processor_kwargs)\n            feishu_kwargs[\"feishu_config\"] = feishu_config\n            preflight = await FeishuAccessor().preflight_source(\n                path,\n                feishu_access_token=token.strip() if isinstance(token, str) else None,\n                feishu_config=feishu_config,\n                **({\"feishu_recursive\": True} if recursive else {}),\n            )\n            source_name = source_name or preflight.source_name\n            source_info = _ResourceSourceInfo(\n                source_name=source_name,\n                source_path=path,\n                source_format=preflight.source_format,\n            )\n            defer_unnamed_target = True\n            direct_understanding = bool(\n                mode is ParseMode.DEFAULT\n                and self._resource_processor.should_use_understanding_directly(\n                    path,\n                    **feishu_kwargs,\n                )\n            )\n            if direct_understanding:\n                understanding_response_id = await self._resource_processor.submit_understanding(\n                    path,\n                    **feishu_kwargs,\n                )\n                if watch_auth_state is None:\n                    task_auth = {}\n            else:\n                source_type, _ = FeishuAccessor._parse_feishu_url(path)\n                if source_type in {\"folder\", \"file\"} or recursive:\n                    if processor_kwargs.get(\"lark_file\") is not None:\n                        raise InvalidArgumentError(\n                            \"Feishu sources requiring preparation use args.feishu_access_token \"\n                            \"or configured Feishu application credentials; args.lark_file \"\n                            \"is only supported for direct single-document Understanding imports.\"\n                        )\n                    # These sources choose a content backend after source preparation.\n                    queued_args[\"parser_backend\"] = processor_kwargs.get(\"parser_backend\")\n                    queued_args[\"_feishu_prepared_source\"] = True\n        else:\n            prepared = await self._resource_processor.prepare_durable_source(\n                path,\n                ctx,\n                snapshot_required=local_source\n                or bool(\n                    processor_kwargs.get(\"tos_signature\") or processor_kwargs.get(\"tos_access\")\n                ),\n                parse_mode=mode,\n                allow_local_path_resolution=allow_local_path_resolution,\n                **processor_kwargs,\n            )\n            if prepared is None:\n                parsed_path = Path(urlparse(path).path)\n                source_name = source_name or parsed_path.name or None\n                source_info = _ResourceSourceInfo(\n                    source_name=source_name,\n                    source_path=path,\n                    source_format=parsed_path.suffix.lower().lstrip(\".\") or \"file\",\n                )\n            else:\n                try:\n                    resolved_extension, source_info = self._prepared_source_info(\n                        prepared,\n                        path,\n                        source_name,\n                        use_path_name=local_source,\n                    )\n                    if resolved_extension:\n                        queued_args[\"resolved_extension\"] = resolved_extension\n                    if (\n                        mode is ParseMode.DEFAULT\n                        and self._resource_processor.should_use_understanding_api(prepared)\n                    ):\n                        if processor_kwargs.get(\"temp_file_id\"):\n                            understanding_file_id = (\n                                await self._resource_processor.upload_understanding_file(prepared)\n                            )\n                        else:\n                            understanding_response_id = (\n                                await self._resource_processor.submit_understanding(\n                                    prepared,\n                                    **processor_kwargs,\n                                )\n                            )\n                    else:\n                        staged_source = await stage_source(\n                            prepared,\n                            viking_fs=self._viking_fs,\n                            ctx=ctx,\n                        )\n                finally:\n                    prepared.cleanup()\n\n        return _SourcePlan(\n            path=path,\n            source_identity=source_info,\n            processor_args=queued_args,\n            task_auth=task_auth,\n            staged_source=staged_source,\n            understanding_response_id=understanding_response_id,\n            understanding_file_id=understanding_file_id,\n            defer_unnamed_target=defer_unnamed_target,\n        )\n\n    @staticmethod\n    def _prepared_source_info(\n        resource: \"LocalResource\",\n        path: str,\n        source_name: Optional[str],\n        *,\n        use_path_name: bool = False,\n    ) -> tuple[str, _ResourceSourceInfo]:\n        resolved_extension = str(\n            resource.meta.get(\"resolved_extension\")\n            or resource.meta.get(\"extension\")\n            or resource.path.suffix\n            or \"\"\n        )\n        resolved_name = (\n            source_name\n            or resource.meta.get(\"original_filename\")\n            or resource.meta.get(\"resolved_name\")\n        )\n        if not resolved_name and use_path_name:\n            resolved_name = resource.path.name\n        source_format = \"directory\" if resource.path.is_dir() else resolved_extension.lstrip(\".\")\n        if not source_format:\n            source_format = \"file\"\n        if resolved_extension.lower().lstrip(\".\") == MPEG_TS_EXTENSION_ALIAS:\n            source_format = \"video\"\n        return (\n            resolved_extension,\n            _ResourceSourceInfo(\n                source_name=resolved_name,\n                source_path=resource.original_source or path,\n                source_format=source_format,\n            ),\n        )\n\n    async def _enqueue_source_plan(\n        self,\n        plan: _SourcePlan,\n        *,\n        ctx: RequestContext,\n        to: str,\n        parent: str,\n        create_parent: bool,\n        reason: str,\n        instruction: str,\n        build_index: bool,\n        summarize: bool,\n        processing_mode: ProcessingMode,\n        mode: ParseMode,\n        watch_interval: float,\n        manage_watch: bool,\n        tags: Optional[List[str]],\n        tag_mode: str,\n        acl: AclSpec | None,\n        to_is_directory: Optional[bool],\n        allow_local_path_resolution: bool,\n        enforce_public_remote_targets: bool,\n        processor_kwargs: Dict[str, Any],\n        internal_task: bool,\n        is_active: Optional[bool] = None,\n    ) -> Dict[str, Any]:\n        from openviking.storage.queuefs.add_resource_msg import AddResourceMsg\n\n        planned_to_is_directory = to_is_directory if to_is_directory is not None else bool(to)\n        target_to_is_exact = bool(to and not is_content_root_uri(to, kind=\"resource\"))\n        defer_candidate_resolution = bool(\n            (plan.defer_unnamed_target and plan.source_identity.source_name is None and not to)\n            or (mode is ParseMode.NO_SPLIT and not target_to_is_exact)\n        )\n        root_uri = \"\"\n        resource_lock = None\n        defer_target_resolution = False\n        staged_enqueued = False\n        try:\n            (\n                root_uri,\n                resource_lock,\n                defer_target_resolution,\n                cleanup_empty_target_on_failure,\n            ) = await self._plan_source_job_target(\n                path=plan.path,\n                ctx=ctx,\n                to=to,\n                parent=parent,\n                create_parent=create_parent,\n                source_info=plan.source_identity,\n                defer_candidate_resolution=defer_candidate_resolution,\n                to_is_directory=planned_to_is_directory,\n            )\n            lock_handoff = await self._lock_to_handoff_payload(resource_lock)\n            message_path = plan.path\n            if processor_kwargs.get(\"temp_file_id\") and plan.understanding_file_id is not None:\n                message_path = (\n                    plan.source_identity.source_name\n                    or plan.source_identity.source_path\n                    or \"uploaded-file\"\n                )\n            msg = AddResourceMsg(\n                task_id=str(uuid4()),\n                job_phase=AddResourcePhase.SOURCE,\n                path=message_path,\n                source_path=(plan.source_identity.source_name or \"\")\n                if processor_kwargs.get(\"temp_file_id\")\n                else plan.source_identity.source_path or plan.path,\n                root_uri=root_uri,\n                staged_source=(\n                    plan.staged_source.to_dict() if plan.staged_source is not None else None\n                ),\n                shared_source=(\n                    plan.shared_source.to_dict() if plan.shared_source is not None else None\n                ),\n                telemetry_id=get_current_telemetry().telemetry_id or None,\n                account_id=ctx.account_id,\n                user_id=ctx.user.user_id,\n                group_ids=list(ctx.group_ids),\n                role=str(ctx.role),\n                actor_peer_id=ctx.actor_peer_id,\n                bypass_acl=ctx.bypass_acl,\n                lock_handoff=lock_handoff,\n                reason=reason,\n                instruction=instruction,\n                build_index=build_index,\n                summarize=summarize,\n                processing_mode=processing_mode,\n                parse_mode=mode.value,\n                watch_interval=watch_interval,\n                is_active=is_active,\n                acl=acl.model_dump(mode=\"json\", exclude_none=True) if acl is not None else None,\n                skip_watch_management=not manage_watch,\n                tags=tags,\n                tag_mode=tag_mode,\n                allow_local_path_resolution=(\n                    True\n                    if (plan.staged_source is not None or plan.shared_source is not None)\n                    else allow_local_path_resolution\n                ),\n                enforce_public_remote_targets=(\n                    enforce_public_remote_targets\n                    and plan.staged_source is None\n                    and plan.shared_source is None\n                ),\n                strict=bool(processor_kwargs.get(\"strict\", False)),\n                ignore_dirs=processor_kwargs.get(\"ignore_dirs\"),\n                include=processor_kwargs.get(\"include\"),\n                exclude=processor_kwargs.get(\"exclude\"),\n                directly_upload_media=bool(processor_kwargs.get(\"directly_upload_media\", True)),\n                preserve_structure=processor_kwargs.get(\"preserve_structure\"),\n                create_parent=create_parent,\n                source_name=plan.source_identity.source_name,\n                to_is_directory=planned_to_is_directory,\n                args=plan.processor_args,\n                git_head_sha_hint=plan.source_identity.head_sha,\n                defer_target_resolution=defer_target_resolution,\n                cleanup_empty_target_on_failure=cleanup_empty_target_on_failure,\n                understanding_response_id=plan.understanding_response_id,\n                understanding_file_id=plan.understanding_file_id,\n                internal_task=internal_task,\n            )\n\n            def transfer_staged_source() -> None:\n                nonlocal staged_enqueued\n                staged_enqueued = True\n\n            queue_name = (\n                QueueManager.EXTERNAL_PARSE\n                if plan.understanding_response_id is not None\n                or plan.understanding_file_id is not None\n                else QueueManager.ADD_RESOURCE\n            )\n            enqueue_lock = resource_lock\n            resource_lock = None\n\n            async def cleanup_enqueue_failure(lock: Dict[str, Any]) -> None:\n                if cleanup_empty_target_on_failure:\n                    await self._cleanup_reserved_target_if_empty(\n                        root_uri=root_uri,\n                        ctx=ctx,\n                        resource_lock=lock,\n                    )\n\n            task = await self._enqueue_add_resource_job(\n                msg,\n                queue_name=queue_name,\n                resource_lock=enqueue_lock,\n                task_auth=plan.task_auth,\n                on_enqueued=(transfer_staged_source if plan.staged_source is not None else None),\n                on_failed_with_lock=cleanup_enqueue_failure,\n            )\n        except BaseException:\n            if resource_lock is not None:\n                await self._release_lock_ref(resource_lock)\n            if plan.staged_source is not None and not staged_enqueued:\n                await self._viking_fs.delete_temp(plan.staged_source.temp_uri, ctx=ctx)\n            raise\n\n        response = {\"status\": \"success\", \"task_id\": task.task_id, \"source_path\": msg.source_path}\n        if not defer_target_resolution:\n            response[\"root_uri\"] = root_uri\n        return response\n\n    async def _plan_source_job_target(\n        self,\n        *,\n        path: str,\n        ctx: RequestContext,\n        to: str,\n        parent: str,\n        create_parent: bool,\n        source_info: _ResourceSourceInfo,\n        defer_candidate_resolution: bool,\n        to_is_directory: bool,\n    ) -> tuple[str, Optional[Dict[str, Any]], bool, bool]:\n        \"\"\"Resolve the target and track ownership of a newly reserved empty path.\"\"\"\n        if not self._resource_processor or not self._viking_fs:\n            raise NotInitializedError(\"ResourceProcessor\")\n\n        doc_name = self._target_doc_name(path, source_info)\n        source_path = source_info.source_path or source_info.source_name or path\n        root_uri, candidate_uri = await self._resource_processor.tree_builder.resolve_target_uri(\n            ctx=ctx,\n            doc_name=doc_name,\n            scope=\"resources\",\n            to_uri=to,\n            parent_uri=parent,\n            source_path=source_path,\n            source_format=source_info.source_format,\n            create_parent=create_parent,\n        )\n        if candidate_uri and defer_candidate_resolution:\n            await self._ensure_resource_target_available(\n                candidate_uri.rpartition(\"/\")[0], ctx, is_parent=True\n            )\n            await self._resource_processor.ensure_candidate_parent_write_access(\n                candidate_uri=candidate_uri,\n                ctx=ctx,\n            )\n            return root_uri, None, True, False\n        if candidate_uri:\n            root_uri, resource_lock = await self._resource_processor.reserve_unique_candidate(\n                candidate_uri=candidate_uri,\n                ctx=ctx,\n                target_validator=self._ensure_resource_target_available,\n            )\n            return root_uri, resource_lock, False, True\n\n        await self._ensure_resource_target_available(root_uri, ctx)\n        await self._viking_fs._ensure_access(root_uri, ctx, action=AclAction.WRITE)\n        # A tree lock may materialize an empty directory marker, so ownership\n        # must be recorded immediately before acquiring it. The zero-timeout\n        # lock still rejects compliant concurrent writers, and cleanup rechecks\n        # that the target is empty before deleting it.\n        target_preexisting = await self._viking_fs.exists(root_uri, ctx=ctx)\n        if to_is_directory and target_preexisting:\n            target_stat = await self._viking_fs.stat(root_uri, ctx=ctx, skip_count=True)\n            if not target_stat.get(\"isDir\"):\n                raise FailedPreconditionError(\n                    \"Target URI already exists as a file and cannot be used as a \"\n                    f\"resource directory: {root_uri}. Choose another URI, use \"\n                    \"'parent' to add a new resource under a directory, or use \"\n                    \"content/write to update the existing file.\",\n                    details={\"resource\": root_uri, \"type\": \"file\"},\n                )\n        dst_path = self._viking_fs._uri_to_path(root_uri, ctx=ctx)\n        resource_lock = await self._viking_fs._async_agfs.pathlock_acquire_tree(\n            dst_path,\n            timeout_secs=0.0,\n        )\n        try:\n            await self._viking_fs._ensure_access(root_uri, ctx, action=AclAction.WRITE)\n        except BaseException:\n            await self._release_lock_ref(resource_lock)\n            raise\n        return root_uri, resource_lock, False, not target_preexisting\n\n    @staticmethod\n    def _target_doc_name(\n        path: str,\n        source_info: _ResourceSourceInfo,\n    ) -> str:\n        if source_info.source_name:\n            return _smart_stem(source_info.source_name)\n        if source_info.source_format == \"repository\":\n            parsed = parse_code_hosting_url(path)\n            if parsed:\n                return parsed.rsplit(\"/\", 1)[-1]\n        return _smart_stem(Path(path).name or \"resource\")\n\n    async def _preflight_git_source(\n        self,\n        source: str,\n        *,\n        auth_config: Optional[GitHttpAuthConfig] = None,\n        branch: Optional[str] = None,\n        commit: Optional[str] = None,\n    ) -> _ResourceSourceInfo:\n        # Normalize browser/tree URLs to the clone URL and resolve the tracked\n        # ref with the same logic the accessor/watch probe uses.\n        from openviking.parse.accessors.git_accessor import GitAccessor\n\n        repo_url, tracked_branch, tracked_commit = GitAccessor._resolve_probe_target(\n            source, branch=branch, commit=commit\n        ) or (source, branch, commit)\n\n        # Target the exact tracked ref so the advertised SHA can be reused by\n        # the accessor as an immutable download hint. A pinned commit cannot be\n        # proven reachable by ls-remote, so HEAD only verifies repository\n        # access there; the fetch/checkout validates the exact SHA.\n        if tracked_commit:\n            ref = \"HEAD\"\n            ls_remote_args = [\"git\", \"ls-remote\", repo_url, \"HEAD\"]\n        elif tracked_branch:\n            ref = (\n                tracked_branch\n                if tracked_branch.startswith(\"refs/\")\n                else f\"refs/heads/{tracked_branch}\"\n            )\n            ls_remote_args = [\"git\", \"ls-remote\", \"--heads\", repo_url, ref]\n        else:\n            ref = \"HEAD\"\n            ls_remote_args = [\"git\", \"ls-remote\", repo_url, \"HEAD\"]\n\n        proc = None\n        try:\n            env = build_git_http_auth_env(auth_config, repo_url) if auth_config is not None else None\n            env = overlay_parser_subprocess_env(\n                ParserNetworkContext(ParserNetworkOperation.GIT_COMMAND, repo_url),\n                env,\n            )\n            proc = await asyncio.create_subprocess_exec(\n                *ls_remote_args,\n                env=env,\n                stdout=asyncio.subprocess.PIPE,\n                stderr=asyncio.subprocess.PIPE,\n                start_new_session=os.name == \"posix\",\n            )\n            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=10.0)\n        except BaseException as exc:\n            if proc is not None:\n                with contextlib.suppress(ProcessLookupError):\n                    if os.name == \"posix\":\n                        os.killpg(proc.pid, signal.SIGKILL)\n                    else:\n                        proc.kill()\n                with contextlib.suppress(Exception):\n                    await asyncio.wait_for(asyncio.shield(proc.communicate()), timeout=1.0)\n            if isinstance(exc, asyncio.TimeoutError):\n                raise InvalidArgumentError(\n                    \"Cannot access Git repository; the preflight timed out after 10s.\"\n                ) from exc\n            if isinstance(exc, Exception):\n                raise InvalidArgumentError(\n                    \"Cannot access Git repository during preflight.\"\n                ) from exc\n            raise\n\n        if proc.returncode != 0:\n            raise_git_auth_error(stderr)\n            raise InvalidArgumentError(\"Cannot access Git repository; git ls-remote failed.\")\n        # Best-effort SHA extraction only: an empty repository or a ref the\n        # server does not advertise still exits 0 and must pass preflight. In\n        # that case the hint stays unset and the clone path performs the\n        # definitive ref/error classification.\n        head_sha = None\n        if not tracked_commit:\n            head_sha = GitAccessor._parse_ls_remote_ref(\n                stdout.decode(errors=\"replace\"), ref\n            )\n        repo_name = parse_code_hosting_url(source)\n        return _ResourceSourceInfo(\n            source_name=repo_name.rsplit(\"/\", 1)[-1] if repo_name else None,\n            source_path=source,\n            source_format=\"repository\",\n            head_sha=head_sha,\n        )\n\n    async def add_resource(\n        self,\n        path: str,\n        ctx: RequestContext,\n        to: Optional[str] = None,\n        parent: Optional[str] = None,\n        reason: str = \"\",\n        instruction: str = \"\",\n        wait: bool = False,\n        build_index: bool = True,\n        summarize: bool = False,\n        processing_mode: ProcessingMode = DEFAULT_PROCESSING_MODE,\n        watch_interval: float = 0,\n        is_active: Optional[bool] = None,\n        tags: Optional[List[str]] = None,\n        tag_mode: str = \"replace\",\n        allow_local_path_resolution: bool = True,\n        enforce_public_remote_targets: bool = False,\n        add_type: Optional[str] = None,\n        internal_task: bool = False,\n        args: Optional[Dict[str, Any]] = None,\n        connector_auth_config: Optional[Dict[str, Any]] = None,\n        shared_source: Optional[\"SharedSource\"] = None,\n        acl: AclSpec | dict[str, Any] | None = None,\n        **kwargs,\n    ) -> Dict[str, Any]:\n        \"\"\"Accept and route a new resource-add request.\"\"\"\n        internal_fields = sorted(set(kwargs).intersection(_INTERNAL_INGESTION_FIELDS))\n        if internal_fields:\n            raise InvalidArgumentError(\n                \"add_resource does not accept internal execution fields: \"\n                + \", \".join(internal_fields)\n            )\n        if isinstance(add_type, str):\n            add_type = add_type.strip() or None\n        return await self._submit_resource_ingestion(\n            path=path,\n            ctx=ctx,\n            add_type=add_type,\n            to=to,\n            parent=parent,\n            reason=reason,\n            instruction=instruction,\n            wait=wait,\n            build_index=build_index,\n            summarize=summarize,\n            processing_mode=processing_mode,\n            watch_interval=watch_interval,\n            is_active=is_active,\n            acl=acl,\n            manage_watch=True,\n            tags=tags,\n            tag_mode=tag_mode,\n            allow_local_path_resolution=allow_local_path_resolution,\n            enforce_public_remote_targets=enforce_public_remote_targets,\n            internal_task=internal_task,\n            args=args,\n            connector_auth_config=connector_auth_config,\n            shared_source=shared_source,\n            **kwargs,\n        )\n\n    async def refresh_resource(\n        self,\n        path: str,\n        ctx: RequestContext,\n        to: Optional[str] = None,\n        to_is_directory: Optional[bool] = None,\n        parent: Optional[str] = None,\n        reason: str = \"\",\n        instruction: str = \"\",\n        build_index: bool = True,\n        summarize: bool = False,\n        processing_mode: ProcessingMode = DEFAULT_PROCESSING_MODE,\n        watch_interval: float = 0,\n        allow_local_path_resolution: bool = True,\n        enforce_public_remote_targets: bool = False,\n        add_type: Optional[str] = None,\n        args: Optional[Dict[str, Any]] = None,\n        connector_states: Optional[Dict[str, Any]] = None,\n        connector_auth_config: Optional[Dict[str, Any]] = None,\n        **kwargs,\n    ) -> Dict[str, Any]:\n        \"\"\"Submit a scheduled refresh without changing its watch task.\"\"\"\n        return await self._submit_resource_ingestion(\n            path=path,\n            ctx=ctx,\n            to=to,\n            to_is_directory=to_is_directory,\n            parent=parent,\n            reason=reason,\n            instruction=instruction,\n            wait=False,\n            build_index=build_index,\n            summarize=summarize,\n            processing_mode=processing_mode,\n            watch_interval=watch_interval,\n            manage_watch=False,\n            allow_local_path_resolution=allow_local_path_resolution,\n            enforce_public_remote_targets=enforce_public_remote_targets,\n            add_type=add_type,\n            args=args,\n            connector_states=connector_states,\n            connector_auth_config=connector_auth_config,\n            **kwargs,\n        )\n\n    async def _submit_resource_ingestion(\n        self,\n        path: str,\n        ctx: RequestContext,\n        add_type: Optional[str] = None,\n        to: Optional[str] = None,\n        to_is_directory: Optional[bool] = None,\n        parent: Optional[str] = None,\n        reason: str = \"\",\n        instruction: str = \"\",\n        wait: bool = False,\n        build_index: bool = True,\n        summarize: bool = False,\n        processing_mode: ProcessingMode = DEFAULT_PROCESSING_MODE,\n        watch_interval: float = 0,\n        is_active: Optional[bool] = None,\n        manage_watch: bool = True,\n        tags: Optional[List[str]] = None,\n        tag_mode: str = \"replace\",\n        parse_mode: ParseMode | str | None = None,\n        allow_local_path_resolution: bool = True,\n        enforce_public_remote_targets: bool = False,\n        internal_task: bool = False,\n        args: Optional[Dict[str, Any]] = None,\n        connector_states: Optional[Dict[str, Any]] = None,\n        connector_auth_config: Optional[Dict[str, Any]] = None,\n        shared_source: Optional[\"SharedSource\"] = None,\n        acl: AclSpec | dict[str, Any] | None = None,\n        **kwargs,\n    ) -> Dict[str, Any]:\n        \"\"\"Validate and route one resource ingestion request.\n\n        Watch ownership:\n            Native Watches require an unoccupied resolved target and keep it while\n            paused. Connector Watches may share targets only with other Connector\n            Watches; repeating a source and target creates another independent task.\n            Re-importing never updates or resumes an existing Watch: use\n            PATCH /api/v1/watches/{task_id}, or delete it before creating a replacement.\n            URI lookup is ambiguous when multiple accessible Watches share a target;\n            address those tasks by task_id. Connector Watches are visible before the\n            initial import and held by the scheduler until it records its result.\n\n        Args:\n            path: Resource path (local file or URL)\n            add_type: Explicitly declared Connector source type. Routes the\n                request to the Connector integration without probing the path;\n                the type must be enabled in connector.allowed_add_types. A\n                declared request never degrades to the standard pipeline and\n                requires an exact ``to`` target.\n            to: Exact final URI including the leaf name (e.g.,\n                \"viking://resources/my_resource\"). Written verbatim; an existing\n                target is synced to match the new source, so visible entries it does\n                not contain are deleted. Required when ``add_type`` is set.\n            parent: Existing directory to store the resource under; the leaf name\n                comes from the source. Never overwrites — a collision reserves the\n                next free name (\"name_1\", \"name_2\", ...) and returns a warning.\n                Mutually exclusive with ``to`` and not supported when ``add_type``\n                is set. Leaving both empty derives the directory and the name from\n                the source and handles collisions like ``parent``.\n            reason: Reason for adding the resource\n            instruction: Processing instruction for semantic extraction\n            wait: Whether to wait for semantic extraction and vectorization to complete\n            build_index: Whether to build vector index immediately (default: True)\n            summarize: Whether to generate summary (default: False)\n            processing_mode: Post-ingest processing mode for semantic/vector work\n            watch_interval: Interval in minutes (default: 0). Positive values create\n                a new Watch subject to target ownership rules, using explicit ``to``\n                or the imported ``root_uri``. Nonpositive values create no Watch:\n                native imports with explicit ``to`` pause a single accessible Watch\n                (ConflictError if ambiguous); Connector imports leave Watches untouched.\n            is_active: When false, the Connector, native Feishu, or native Git Watch is created paused.\n                Requires watch_interval > 0 and an explicit to or parent target.\n            enforce_public_remote_targets: When True, reject non-public remote hosts and\n                validate each outbound HTTP request URL during fetch.\n            args: Parser/accessor-specific options forwarded to the processing chain.\n            **kwargs: Extra options forwarded to the parser chain\n\n        Returns:\n            Processing result containing 'root_uri' and other metadata\n\n        Raises:\n            ConflictError: Incompatible target occupancy or ambiguous cancellation by URI\n            InvalidArgumentError: If the URI scope is not 'resources'\n        \"\"\"\n        self._ensure_initialized()\n        has_target = bool((to or \"\").strip() or (parent or \"\").strip())\n        if is_active is False and (watch_interval <= 0 or not has_target):\n            raise InvalidArgumentError(\n                \"is_active=false requires watch_interval > 0 and either 'to' or 'parent'.\"\n            )\n        processing_mode = normalize_processing_mode(processing_mode)\n        self._validate_add_resource_tag_policy(tags=tags, tag_mode=tag_mode)\n        from openviking.connector.delegate import (\n            CONNECTOR_DISPLAY_RESOURCE_CONFIG_ARG,\n            ConnectorDelegate,\n        )\n\n        allowed_reserved_fields = ConnectorDelegate.supported_args(path, add_type).intersection(\n            _ADD_RESOURCE_ARGS_RESERVED_FIELDS\n        )\n        normalized_args = await self._normalize_add_resource_args(\n            args,\n            ctx=ctx,\n            watch_interval=watch_interval,\n            allowed_reserved_fields=allowed_reserved_fields,\n        )\n        mode = (\n            normalize_parse_mode(parse_mode)\n            if parse_mode is not None\n            else normalized_args.parse_mode\n        )\n        duplicated_fields = sorted(\n            field\n            for field in allowed_reserved_fields\n            if field in normalized_args.processor_kwargs and kwargs.get(field) is not None\n        )\n        if duplicated_fields:\n            raise InvalidArgumentError(\n                f\"{', '.join(duplicated_fields)} cannot be provided both as a top-level \"\n                \"field and in args.\"\n            )\n        kwargs.update(normalized_args.processor_kwargs)\n        tos_signature = kwargs.get(\"tos_signature\")\n        tos_access = kwargs.get(\"tos_access\")\n        if tos_signature is not None or tos_access is not None:\n            if not path.startswith((\"http://\", \"https://\")):\n                raise InvalidArgumentError(\n                    \"tos_signature and tos_access are only supported for HTTP(S) resource URLs.\"\n                )\n            if tos_signature is not None and tos_access is not None:\n                raise InvalidArgumentError(\"tos_signature and tos_access cannot both be provided.\")\n            for field, value in ((\"tos_signature\", tos_signature), (\"tos_access\", tos_access)):\n                if value is not None:\n                    if not isinstance(value, str) or not value.strip():\n                        raise InvalidArgumentError(f\"args.{field} must be a non-empty string.\")\n                    kwargs[field] = value.strip()\n        git_repo_source = is_git_repo_url(path)\n        if git_repo_source:\n            reject_git_http_userinfo(path)\n        if watch_interval > 0 and kwargs.get(\"temp_file_id\"):\n            # Fail fast: a watch on a static upload snapshot can never observe the\n            # live source.\n            raise InvalidArgumentError(\n                \"watch_interval > 0 is not supported for uploaded content: an \"\n                \"upload is a static snapshot, so the watch would re-process \"\n                \"stale content forever. Watch a URL / \"\n                \"sitemap / RSS source instead, or re-add the resource when the \"\n                \"source changes.\"\n            )\n        if not to and not parent:\n            from openviking.server.dependencies import get_server_config\n\n            default_parent = await effective_resource_add_target(\n                viking_fs=self._viking_fs,\n                ctx=ctx,\n                server_config=get_server_config(),\n            )\n            if default_parent:\n                parent = default_parent\n                kwargs[\"create_parent\"] = True\n\n        self._ensure_single_resource_target(to=to, parent=parent)\n        target_to = to or \"\"\n        target_parent = parent or \"\"\n        await self._ensure_resource_target_available(\n            target_to, ctx, is_parent=is_content_root_uri(target_to, kind=\"resource\")\n        )\n        await self._ensure_resource_target_available(target_parent, ctx, is_parent=True)\n        target_create_parent = bool(kwargs.get(\"create_parent\", False))\n        if acl is not None:\n            acl = AclSpec.model_validate(acl)\n\n        connector = self._connector\n        delegate_to_connector = connector.should_delegate(\n            path,\n            ctx=ctx,\n            declared_add_type=add_type,\n            to=to,\n            parent=parent,\n            wait=wait,\n            instruction=instruction,\n            build_index=build_index,\n            summarize=summarize,\n            processing_mode=processing_mode,\n            parse_mode=mode,\n            watch_interval=watch_interval,\n            connector_args=normalized_args.processor_kwargs,\n            kwargs=kwargs,\n        )\n        if not delegate_to_connector and connector_auth_config:\n            # A managed credential reference only resolves inside Connector\n            # delegation; never drop it and silently degrade to an unauthorized\n            # standard-pipeline import.\n            from openviking.connector.auth import extract_credential_reference\n\n            if extract_credential_reference(connector_auth_config) is not None:\n                raise InvalidArgumentError(\n                    \"connector_auth_config requires a Connector import; the source or \"\n                    \"parameters did not route to the Connector integration.\"\n                )\n        if delegate_to_connector:\n            resolved = connector.resolve_add_type(path, add_type)\n            if resolved is None:  # pragma: no cover - should_delegate already resolved it\n                raise InvalidArgumentError(f\"'{path}' does not match any Connector source type.\")\n            acl_update = (\n                await self._viking_fs.prepare_acl_update(target_to, acl, ctx)\n                if acl is not None\n                else None\n            )\n            watch_manager = self._get_watch_manager()\n            watch_auth_state = None\n            create_watch = bool(watch_manager and manage_watch and watch_interval > 0)\n            if create_watch:\n                connector_watch_auth_args = dict(normalized_args.processor_kwargs)\n                connector_watch_auth_args.pop(CONNECTOR_DISPLAY_RESOURCE_CONFIG_ARG, None)\n                watch_auth_state = await connector.create_watch_auth_state(\n                    api_key=ctx.api_key or \"\",\n                    account_id=ctx.account_id,\n                    add_type=resolved[0],\n                    path=path,\n                    connector_args=connector_watch_auth_args,\n                    connector_auth_config=connector_auth_config,\n                )\n            connector_watch_processor_kwargs = self._watch_processor_kwargs(\n                {\n                    key: value\n                    for key, value in kwargs.items()\n                    if key not in normalized_args.processor_kwargs\n                },\n                tags,\n                tag_mode,\n            )\n            resource_config = _normalized_resource_config(\n                normalized_args.processor_kwargs.get(CONNECTOR_DISPLAY_RESOURCE_CONFIG_ARG)\n            )\n            if resource_config:\n                connector_watch_processor_kwargs[CONNECTOR_DISPLAY_RESOURCE_CONFIG_ARG] = (\n                    resource_config\n                )\n            on_success: Optional[Callable[[Optional[Dict[str, Any]]], Awaitable[None]]] = None\n            on_complete: Optional[\n                Callable[[str, Optional[str], Optional[str]], Awaitable[None]]\n            ] = None\n            if create_watch:\n                # The Watch exists before the import runs so it is visible at once.\n                # A scheduler hold keeps the first round from overlapping with a\n                # scheduled run; record_watch_execution releases it at the end.\n                watch = await self._handle_watch_task_creation(\n                    path=path,\n                    to_uri=target_to,\n                    to_is_directory=to_is_directory,\n                    parent_uri=target_parent,\n                    reason=reason,\n                    instruction=instruction,\n                    watch_interval=watch_interval,\n                    build_index=build_index,\n                    summarize=summarize,\n                    processing_mode=processing_mode,\n                    processor_kwargs=connector_watch_processor_kwargs,\n                    auth_state=watch_auth_state,\n                    connector_states=None,\n                    source_type=resolved[0],\n                    ctx=ctx,\n                    is_active=is_active is not False,\n                    hold_execution=True,\n                )\n                if watch is None:\n                    raise InternalError(\"Failed to create Connector watch task.\")\n                watch_task_id = watch.task_id\n                logger.info(\n                    \"[ResourceService] Connector watch ready before import: watch_task_id=%s \"\n                    \"to=%s add_type=%s is_active=%s\",\n                    watch_task_id,\n                    target_to,\n                    resolved[0],\n                    watch.is_active,\n                )\n\n                async def record_first_run(\n                    status: str,\n                    execution_task_id: Optional[str],\n                    error: Optional[str],\n                ) -> None:\n                    try:\n                        await self.record_watch_execution(\n                            watch_task_id,\n                            status=status,\n                            execution_task_id=execution_task_id,\n                            error=error,\n                        )\n                    except Exception:\n                        logger.exception(\n                            \"[ResourceService] Failed to record Connector watch result\"\n                        )\n\n                async def store_connector_states(\n                    new_connector_states: Optional[Dict[str, Any]] = None,\n                ) -> None:\n                    if new_connector_states is not None:\n                        await watch_manager.update_connector_states(\n                            watch_task_id,\n                            new_connector_states,\n                        )\n\n                on_complete = record_first_run\n                on_success = store_connector_states\n            if acl_update is not None:\n                watch_on_success = on_success\n\n                async def apply_connector_acl(new_states=None):\n                    await self._viking_fs.set_acl(\n                        acl_update.uri,\n                        acl_update.acl.entries,\n                        ctx=ctx,\n                        acl_mode=acl_update.acl.acl_mode,\n                    )\n                    if watch_on_success is not None:\n                        await watch_on_success(new_states)\n\n                on_success = apply_connector_acl\n            try:\n                result = await connector.submit(\n                    path=path,\n                    ctx=ctx,\n                    declared_add_type=add_type,\n                    to=target_to,\n                    reason=reason,\n                    connector_args=normalized_args.processor_kwargs,\n                    connector_auth_config=connector_auth_config,\n                    tags=tags,\n                    tag_mode=tag_mode,\n                    wait_for_completion=not manage_watch and watch_interval > 0,\n                    connector_states=connector_states,\n                    on_success=on_success,\n                    on_complete=on_complete,\n                    **kwargs,\n                )\n            except asyncio.CancelledError:\n                if on_complete is not None:\n                    await on_complete(\n                        \"failed\",\n                        None,\n                        \"connector task submission cancelled\",\n                    )\n                raise\n            except Exception as exc:\n                if on_complete is not None:\n                    await on_complete(\"failed\", None, str(exc))\n                raise\n            # A one-off Connector import (watch_interval <= 0) leaves any watch on the\n            # target alone: many imports share one folder, so the native\n            # \"watch_interval=0 cancels the watch\" rule would pause it as a side\n            # effect. Connector watches are paused or deleted only via the watches API.\n            if create_watch:\n                result[\"watch_id\"] = watch_task_id\n            return result\n\n        from openviking.parse.accessors.feishu_accessor import FeishuAccessor\n\n        if is_active is False and not (\n            FeishuAccessor._is_feishu_url(path) or is_git_repo_url(path)\n        ):\n            raise InvalidArgumentError(\n                \"is_active=false is only supported for Connector, native Feishu, or native Git imports.\"\n            )\n        if enforce_public_remote_targets and is_remote_resource_source(path):\n            path = require_remote_resource_source(path)\n            kwargs.setdefault(\"request_validator\", ensure_public_remote_target)\n\n        async with feishu_auth_scope(\n            connector, path=path, ctx=ctx, args=kwargs, state=normalized_args.watch_auth_state\n        ) as watch_auth_state:\n            normalized_args.watch_auth_state = watch_auth_state\n            source_plan = await self._prepare_standard_source_plan(\n                path=path,\n                ctx=ctx,\n                mode=mode,\n                allow_local_path_resolution=allow_local_path_resolution,\n                processor_kwargs=kwargs,\n                watch_auth_state=normalized_args.watch_auth_state,\n                shared_source=shared_source,\n            )\n        if source_plan is not None:\n            result = await self._enqueue_source_plan(\n                source_plan,\n                ctx=ctx,\n                to=target_to,\n                parent=target_parent,\n                create_parent=target_create_parent,\n                reason=reason,\n                instruction=instruction,\n                build_index=build_index,\n                summarize=summarize,\n                processing_mode=processing_mode,\n                mode=mode,\n                watch_interval=watch_interval,\n                manage_watch=manage_watch,\n                tags=tags,\n                tag_mode=tag_mode,\n                acl=acl,\n                to_is_directory=to_is_directory,\n                allow_local_path_resolution=allow_local_path_resolution,\n                enforce_public_remote_targets=enforce_public_remote_targets,\n                processor_kwargs=kwargs,\n                internal_task=internal_task,\n                is_active=is_active,\n            )\n        else:\n            result = await self._execute_resource_ingestion(\n                path=path,\n                ctx=ctx,\n                to=target_to,\n                to_is_directory=to_is_directory,\n                parent=target_parent,\n                reason=reason,\n                instruction=instruction,\n                defer_post_processing=True,\n                build_index=build_index,\n                summarize=summarize,\n                processing_mode=processing_mode,\n                parse_mode=mode,\n                watch_interval=watch_interval,\n                is_active=is_active,\n                manage_watch=manage_watch,\n                tags=tags,\n                tag_mode=tag_mode,\n                allow_local_path_resolution=allow_local_path_resolution,\n                enforce_public_remote_targets=enforce_public_remote_targets,\n                watch_auth_state=normalized_args.watch_auth_state,\n                internal_task=internal_task,\n                acl=acl,\n                **kwargs,\n            )\n        get_current_telemetry().set(\"resource.flags.wait\", wait)\n        if not wait:\n            return result\n        if result.get(\"status\") == \"error\":\n            return result\n        from openviking.service.task_tracker import TaskStatus, get_task_tracker\n\n        task_id = result[\"task_id\"]\n        task = await get_task_tracker().wait(\n            task_id,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n        )\n\n        if task.status == TaskStatus.COMPLETED:\n            completed = dict(task.result)\n            completed.pop(\"task_id\", None)\n            return completed\n        if task.status == TaskStatus.CANCELLED:\n            return {\"status\": \"cancelled\"}\n        failure: Dict[str, Any] = {\n            \"status\": \"error\",\n            \"errors\": [task.error],\n        }\n        if isinstance(task.result, dict):\n            code = task.result.get(\"code\")\n            if isinstance(code, str) and code:\n                failure[\"code\"] = code\n            details = task.result.get(\"details\")\n            if isinstance(details, dict):\n                failure[\"details\"] = details\n        return failure\n\n    async def _execute_resource_ingestion(\n        self,\n        path: str,\n        ctx: RequestContext,\n        defer_post_processing: bool,\n        to: Optional[str] = None,\n        to_is_directory: Optional[bool] = None,\n        parent: Optional[str] = None,\n        reason: str = \"\",\n        instruction: str = \"\",\n        build_index: bool = True,\n        summarize: bool = False,\n        processing_mode: ProcessingMode = DEFAULT_PROCESSING_MODE,\n        parse_mode: ParseMode | str = ParseMode.DEFAULT,\n        watch_interval: float = 0,\n        is_active: Optional[bool] = None,\n        manage_watch: bool = True,\n        tags: Optional[List[str]] = None,\n        tag_mode: str = \"replace\",\n        allow_local_path_resolution: bool = True,\n        enforce_public_remote_targets: bool = False,\n        watch_auth_state: Optional[Dict[str, Any]] = None,\n        resource_lock: Optional[Dict[str, Any]] = None,\n        stage_callback: Optional[Callable[[str], Any]] = None,\n        prepared_resource: Optional[\"LocalResource\"] = None,\n        internal_task: bool = False,\n        on_watch_ready: Optional[Callable[[str], None]] = None,\n        acl: AclSpec | dict[str, Any] | None = None,\n        **kwargs,\n    ) -> Dict[str, Any]:\n        \"\"\"Execute an already-routed resource ingestion.\"\"\"\n        self._ensure_initialized()\n        mode = normalize_parse_mode(parse_mode)\n        if mode is ParseMode.NO_SPLIT:\n            kwargs[\"parse_mode\"] = mode.value\n        telemetry = get_current_telemetry()\n        telemetry_id = telemetry.telemetry_id\n        register_telemetry(telemetry)\n        job_enqueued = False\n        deferred_lock: Optional[Dict[str, Any]] = None\n        watch_manager = self._get_watch_manager()\n        watch_enabled = bool(watch_manager and manage_watch and watch_interval > 0)\n\n        telemetry.set(\"resource.flags.build_index\", build_index)\n        telemetry.set(\"resource.flags.summarize\", summarize)\n        telemetry.set(\"resource.flags.watch_enabled\", watch_enabled)\n\n        try:\n            self._ensure_single_resource_target(to=to, parent=parent)\n            target_to = to or \"\"\n            target_parent = parent or \"\"\n            await self._ensure_resource_target_available(\n                target_to, ctx, is_parent=is_content_root_uri(target_to, kind=\"resource\")\n            )\n            await self._ensure_resource_target_available(target_parent, ctx, is_parent=True)\n            if to_is_directory is None:\n                to_is_directory = bool(target_to)\n            watch_to_is_directory = to_is_directory\n            if enforce_public_remote_targets and is_remote_resource_source(path):\n                path = require_remote_resource_source(path)\n                kwargs.setdefault(\"request_validator\", ensure_public_remote_target)\n            if resource_lock is not None:\n                kwargs[\"resource_lock\"] = resource_lock\n\n            result = await self._resource_processor.process_resource(\n                path=path,\n                ctx=ctx,\n                reason=reason,\n                instruction=instruction,\n                scope=\"resources\",\n                to=target_to,\n                parent=target_parent,\n                to_is_directory=to_is_directory,\n                build_index=build_index,\n                summarize=summarize,\n                processing_mode=processing_mode,\n                stage_callback=stage_callback,\n                allow_local_path_resolution=allow_local_path_resolution,\n                prepared_resource=prepared_resource,\n                target_validator=self._ensure_resource_target_available,\n                defer_post_processing=True,\n                tags=tags,\n                tag_mode=tag_mode,\n                acl=acl,\n                **kwargs,\n            )\n            prepared_resource = None\n\n            if result.get(\"status\") == \"error\":\n                return result\n            prepared = result.pop(\"_post_process\", None)\n            deferred_lock = result.pop(\"_resource_lock\", None)\n            if (\n                not to_is_directory\n                and isinstance(prepared, dict)\n                and isinstance(prepared.get(\"root_is_file\"), bool)\n            ):\n                watch_to_is_directory = not prepared[\"root_is_file\"]\n            if not isinstance(prepared, dict):\n                raise InternalError(\"Deferred resource processing payload is missing\")\n            await self._manage_watch_if_needed(\n                watch_manager=watch_manager,\n                manage_watch=manage_watch,\n                watch_interval=watch_interval,\n                is_active=is_active,\n                to=target_to,\n                parent=target_parent,\n                to_is_directory=watch_to_is_directory,\n                root_uri=str(result.get(\"root_uri\") or \"\"),\n                path=path,\n                reason=reason,\n                instruction=instruction,\n                build_index=build_index,\n                summarize=summarize,\n                processing_mode=processing_mode,\n                processor_kwargs=self._watch_processor_kwargs(kwargs, tags, tag_mode),\n                watch_auth_state=watch_auth_state,\n                ctx=ctx,\n                on_watch_ready=on_watch_ready,\n            )\n            if defer_post_processing:\n                from openviking.storage.queuefs.add_resource_msg import AddResourceMsg\n\n                root_uri = result.get(\"root_uri\", \"\")\n                lock_handoff = await self._lock_to_handoff_payload(deferred_lock)\n                msg = AddResourceMsg(\n                    task_id=str(uuid4()),\n                    job_phase=AddResourcePhase.POST_PROCESS,\n                    root_uri=root_uri,\n                    prepared=prepared,\n                    source_path=str(\n                        (kwargs.get(\"source_name\") or \"\")\n                        if kwargs.get(\"temp_file_id\")\n                        else result.get(\"source_path\") or \"\"\n                    ),\n                    telemetry_id=telemetry_id or None,\n                    account_id=ctx.account_id,\n                    user_id=ctx.user.user_id,\n                    group_ids=list(ctx.group_ids),\n                    role=str(ctx.role),\n                    actor_peer_id=ctx.actor_peer_id,\n                    bypass_acl=ctx.bypass_acl,\n                    lock_handoff=lock_handoff,\n                    reason=reason,\n                    instruction=instruction,\n                    build_index=build_index,\n                    summarize=summarize,\n                    processing_mode=processing_mode,\n                    strict=bool(kwargs.get(\"strict\", False)),\n                    ignore_dirs=kwargs.get(\"ignore_dirs\"),\n                    include=kwargs.get(\"include\"),\n                    exclude=kwargs.get(\"exclude\"),\n                    directly_upload_media=bool(kwargs.get(\"directly_upload_media\", True)),\n                    preserve_structure=kwargs.get(\"preserve_structure\"),\n                    create_parent=bool(kwargs.get(\"create_parent\", False)),\n                    allow_local_path_resolution=allow_local_path_resolution,\n                    enforce_public_remote_targets=enforce_public_remote_targets,\n                    source_name=kwargs.get(\"source_name\"),\n                    skip_watch_management=True,\n                    tags=tags,\n                    tag_mode=tag_mode,\n                    internal_task=internal_task,\n                )\n                enqueue_lock = deferred_lock\n                deferred_lock = None\n                task = await self._enqueue_add_resource_job(\n                    msg,\n                    queue_name=QueueManager.ADD_RESOURCE,\n                    resource_lock=enqueue_lock,\n                )\n                result[\"task_id\"] = task.task_id\n                job_enqueued = True\n            else:\n                processing_lock = deferred_lock\n                deferred_lock = None\n                post_result = await self._resource_processor.finish_prepared_resource(\n                    prepared,\n                    ctx=ctx,\n                    resource_lock=processing_lock,\n                    summarize=summarize,\n                    build_index=build_index,\n                    processing_mode=processing_mode,\n                    ingest_options=IngestOptions.from_search_tags(tags, mode=tag_mode),\n                )\n                if post_result.get(\"warnings\"):\n                    result.setdefault(\"warnings\", []).extend(post_result[\"warnings\"])\n            return result\n        except Exception as exc:\n            telemetry.set_error(\n                \"resource_service.add_resource\",\n                type(exc).__name__,\n                str(exc),\n            )\n            raise\n        finally:\n            if prepared_resource is not None:\n                prepared_resource.cleanup()\n            if not telemetry_id or (defer_post_processing and not job_enqueued):\n                unregister_telemetry(telemetry_id)\n            if deferred_lock is not None:\n                await self._release_lock_ref(deferred_lock)\n\n    async def _link_resource_reason_memory(\n        self,\n        *,\n        result: Dict[str, Any],\n        ctx: RequestContext,\n        reason: str,\n        source_name: Optional[str],\n    ) -> None:\n        if not self._resource_memory_link_service:\n            return\n        if not (reason or \"\").strip():\n            return\n        root_uri = result.get(\"root_uri\")\n        if not root_uri:\n            return\n        try:\n            link_result = await self._resource_memory_link_service.on_resource_added(\n                ctx=ctx,\n                resource_uri=root_uri,\n                reason=reason,\n                source_name=source_name,\n            )\n            result[\"memory_linking\"] = link_result\n        except Exception as exc:\n            logger.warning(\"[ResourceService] Failed to link resource reason memory: %s\", exc)\n            result.setdefault(\"warnings\", []).append(f\"Memory linking failed: {exc}\")\n\n    @staticmethod\n    def _raise_queue_status_errors(status: Dict[str, Any]) -> None:\n        failed = {\n            name: group\n            for name, group in status.items()\n            if isinstance(group, dict)\n            and (int(group.get(\"error_count\", 0) or 0) > 0 or bool(group.get(\"errors\")))\n        }\n        if failed:\n            raise InternalError(f\"queue processing failed: {failed}\")\n\n    # ── Connector routing ──\n\n    @property\n    def _connector(self) -> \"ConnectorDelegate\":\n        \"\"\"Connector delegation (lazy: viking_fs may be injected after init).\"\"\"\n        if self._connector_delegate is None:\n            from openviking.connector.delegate import ConnectorDelegate\n\n            self._connector_delegate = ConnectorDelegate(\n                viking_fs=self._viking_fs,\n                background_tasks=self._background_tasks,\n                link_reason_memory=self._link_resource_reason_memory,\n            )\n        return self._connector_delegate\n\n    async def _handle_watch_task_creation(\n        self,\n        path: str,\n        to_uri: str,\n        to_is_directory: bool,\n        parent_uri: Optional[str],\n        reason: str,\n        instruction: str,\n        watch_interval: float,\n        build_index: bool,\n        summarize: bool,\n        processing_mode: ProcessingMode,\n        processor_kwargs: Dict[str, Any],\n        auth_state: Optional[Dict[str, Any]],\n        connector_states: Optional[Dict[str, Any]],\n        source_type: Optional[str],\n        ctx: RequestContext,\n        is_active: bool = True,\n        hold_execution: bool = False,\n    ) -> Optional[\"WatchTask\"]:\n        \"\"\"Create the watch task for the resolved target URI.\n\n        Native Watches require an unoccupied target; Connector Watches may share\n        only with other Connector Watches. Paused Watches retain ownership.\n        Callers using ``parent`` pass the root URI resolved after ingestion.\n\n        Raises:\n            ConflictError: If the target URI has an incompatible Watch\n        \"\"\"\n        watch_manager = self._get_watch_manager()\n        if not watch_manager:\n            return None\n\n        task = await watch_manager.create_task(\n            path=path,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            original_role=str(ctx.role),\n            source_type=source_type,\n            to_uri=to_uri,\n            to_is_directory=to_is_directory,\n            parent_uri=parent_uri,\n            reason=reason,\n            instruction=instruction,\n            watch_interval=watch_interval,\n            build_index=build_index,\n            summarize=summarize,\n            processing_mode=processing_mode,\n            processor_kwargs=processor_kwargs,\n            auth_state=auth_state,\n            connector_states=connector_states,\n            is_active=is_active,\n        )\n        if hold_execution:\n            # Brand-new task: the hold cannot be contended, it just parks the id\n            # until the caller's first round records its result.\n            await self._hold_watch_execution(task.task_id)\n        logger.info(f\"[ResourceService] Created watch task {task.task_id} for {to_uri}\")\n        return task\n\n    async def _handle_watch_task_cancellation(self, to_uri: str, ctx: RequestContext) -> None:\n        \"\"\"Handle cancellation of watch task.\n\n        Args:\n            to_uri: Target URI to cancel watch for\n            ctx: Request context with user identity\n        \"\"\"\n        watch_manager = self._get_watch_manager()\n        if not watch_manager:\n            return\n\n        existing_task = await watch_manager.get_task_by_uri(\n            to_uri=to_uri,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            role=str(ctx.role),\n        )\n        if existing_task:\n            await watch_manager.update_task(\n                task_id=existing_task.task_id,\n                account_id=ctx.account_id,\n                user_id=ctx.user.user_id,\n                role=str(ctx.role),\n                is_active=False,\n                invalidate_source_checkpoint=True,\n            )\n            logger.info(\n                f\"[ResourceService] Deactivated watch task {existing_task.task_id} for {to_uri}\"\n            )\n\n    async def add_skill(\n        self,\n        data: Any,\n        ctx: RequestContext,\n        wait: bool = False,\n        allow_local_path_resolution: bool = True,\n        source_path_hint: Optional[str] = None,\n        apply_privacy: bool = True,\n        privacy_change_reason: str = \"auto-extracted from add_skill\",\n        target_uri: Optional[str] = None,\n        source_metadata: Optional[Dict[str, Any]] = None,\n        task_id: Optional[str] = None,\n        owner_lease_ref: Optional[Dict[str, Any]] = None,\n    ) -> Dict[str, Any]:\n        \"\"\"Add skill to OpenViking.\n\n        Args:\n            data: Skill data (directory path, file path, string, or dict)\n            wait: Whether to wait for vectorization to complete\n            target_uri: Optional root URI override (e.g. ``viking://agent/skills``).\n\n        Returns:\n            Processing result\n        \"\"\"\n        self._ensure_initialized()\n        if not target_uri:\n            from openviking.server.dependencies import get_server_config\n\n            target_uri = await effective_skill_add_target(\n                viking_fs=self._viking_fs,\n                ctx=ctx,\n                server_config=get_server_config(),\n            )\n        from openviking.service.task_tracker import get_task_tracker\n        from openviking.service.task_tracker_concurrency import run_to_completion\n        from openviking.service.task_work_index import bind_task_context\n\n        task_tracker = get_task_tracker()\n        task = None\n        outcome_recorded = False\n        telemetry_id = get_current_telemetry().telemetry_id\n        telemetry_cleanup_scheduled = False\n\n        async def record_package(skill_uri: str, lease_ref: Any) -> None:\n            \"\"\"Record an ordinary Skill package operation under its content lease.\"\"\"\n            if (\n                self.compile_versions is not None\n                and owner_lease_ref is None\n                and (source_metadata or {}).get(\"source\") != \"compile\"\n                and (target := await self.compile_versions.owning_target(ctx.account_id, skill_uri))\n                and await self.compile_versions._write_meta(ctx.account_id, target)\n            ):\n                await self.compile_versions.record_operation(\n                    [skill_uri],\n                    ctx,\n                    \"agent_revise\",\n                    {},\n                    lambda: self.compile_versions.register_transfer(ctx),\n                )\n\n        try:\n            # Establish ownership before any queue work can start. Descendant\n            # semantic and embedding messages inherit this same cancellable task.\n            async def create_skill_task() -> None:\n                nonlocal task\n                task = await task_tracker.create(\n                    \"add_skill\",\n                    account_id=ctx.account_id,\n                    user_id=ctx.user.user_id,\n                    task_id=task_id,\n                )\n\n            # Keep the returned record before propagating cancellation, so a\n            # committed task can still be settled by the exception handler.\n            await run_to_completion(create_skill_task)\n            assert task is not None\n            await task_tracker.start(\n                task.task_id, account_id=ctx.account_id, user_id=ctx.user.user_id\n            )\n            running_work_id = await task_tracker.register_running_task(\n                task.task_id,\n                account_id=ctx.account_id,\n                user_id=ctx.user.user_id,\n            )\n            try:\n                with bind_task_context(\n                    task.task_id,\n                    ctx.account_id,\n                    ctx.user.user_id,\n                    work_id=running_work_id,\n                ):\n                    if isinstance(data, SkillProcessingPreparation):\n                        result = await self._skill_processor.process_prepared_skill(\n                            data,\n                            viking_fs=self._viking_fs,\n                            ctx=ctx,\n                            apply_privacy=apply_privacy,\n                            privacy_change_reason=privacy_change_reason,\n                            target_uri=target_uri,\n                            source_metadata=source_metadata,\n                            owner_lease_ref=owner_lease_ref,\n                            on_package_written=record_package,\n                        )\n                    else:\n                        result = await self._skill_processor.process_skill(\n                            data=data,\n                            viking_fs=self._viking_fs,\n                            ctx=ctx,\n                            allow_local_path_resolution=allow_local_path_resolution,\n                            source_path_hint=source_path_hint,\n                            apply_privacy=apply_privacy,\n                            privacy_change_reason=privacy_change_reason,\n                            target_uri=target_uri,\n                            source_metadata=source_metadata,\n                            owner_lease_ref=owner_lease_ref,\n                            on_package_written=record_package,\n                        )\n                if isinstance(result, dict) and \"root_uri\" not in result and result.get(\"uri\"):\n                    result[\"root_uri\"] = result[\"uri\"]\n\n                result[\"task_id\"] = task.task_id\n                if telemetry_id:\n                    self._unregister_telemetry_after_task(\n                        task.task_id,\n                        telemetry_id,\n                        account_id=ctx.account_id,\n                        user_id=ctx.user.user_id,\n                    )\n                    telemetry_cleanup_scheduled = True\n                await task_tracker.complete(\n                    task.task_id,\n                    result,\n                    account_id=ctx.account_id,\n                    user_id=ctx.user.user_id,\n                )\n                outcome_recorded = True\n            except BaseException as exc:\n                failure_message = str(exc) or \"Skill processing cancelled\"\n                await run_to_completion(\n                    lambda: task_tracker.fail(\n                        task.task_id,\n                        failure_message,\n                        account_id=ctx.account_id,\n                        user_id=ctx.user.user_id,\n                    )\n                )\n                outcome_recorded = True\n                raise\n            finally:\n                await task_tracker.unregister_running_task(task.task_id)\n            if wait:\n                wait_start = time.perf_counter()\n                try:\n                    completed = await task_tracker.wait(\n                        task.task_id,\n                        account_id=ctx.account_id,\n                        user_id=ctx.user.user_id,\n                        timeout=None,\n                    )\n                except (TimeoutError, asyncio.TimeoutError) as exc:\n                    get_current_telemetry().set_error(\n                        \"resource_service.wait_complete\",\n                        \"DEADLINE_EXCEEDED\",\n                        str(exc),\n                    )\n                    raise DeadlineExceededError(\"queue processing\", None) from exc\n                get_current_telemetry().set(\n                    \"queue.wait.duration_ms\",\n                    round((time.perf_counter() - wait_start) * 1000, 3),\n                )\n                status = await task_tracker.build_queue_status(\n                    task.task_id,\n                    account_id=ctx.account_id,\n                    user_id=ctx.user.user_id,\n                )\n                result[\"queue_status\"] = status\n                self._raise_queue_status_errors(status)\n                # Cancellation settles queue entries without counting errors.\n                if completed.status.value == \"cancelled\":\n                    raise OpenVikingError(\n                        \"Skill processing was cancelled\",\n                        code=\"PROCESSING_ERROR\",\n                        details={\"task_id\": task.task_id, \"status\": \"cancelled\"},\n                    )\n            return result\n        except BaseException as exc:\n            if task is not None and not outcome_recorded:\n                failure_message = str(exc) or \"Skill processing cancelled\"\n                await run_to_completion(\n                    lambda: task_tracker.fail(\n                        task.task_id,\n                        failure_message,\n                        account_id=ctx.account_id,\n                        user_id=ctx.user.user_id,\n                    )\n                )\n            raise\n        finally:\n            if not telemetry_cleanup_scheduled:\n                unregister_telemetry(telemetry_id)\n\n    async def cancel_skill_processing(self, task_id: str, ctx: RequestContext) -> None:\n        \"\"\"Stop one failed update's work before its caller restores the old package.\"\"\"\n        from openviking.service.task_tracker import get_task_tracker\n\n        tracker = get_task_tracker()\n        task = await tracker.cancel_skill_update_for_rollback(\n            task_id, account_id=ctx.account_id, user_id=ctx.user.user_id\n        )\n        if task is None:\n            return  # Synchronous preparation failed before the task was created.\n        # This includes queued work that must be discarded and active handlers\n        # that must finish their cancellation/write cleanup, not just task status.\n        while await tracker.has_work(\n            task_id,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n        ):\n            await asyncio.sleep(0.05)\n\n    async def build_index(\n        self, resource_uris: List[str], ctx: RequestContext, **kwargs\n    ) -> Dict[str, Any]:\n        \"\"\"Manually trigger index building.\n\n        Args:\n            resource_uris: List of resource URIs to index.\n            ctx: Request context.\n\n        Returns:\n            Processing result\n        \"\"\"\n        self._ensure_initialized()\n        return await self._resource_processor.build_index(resource_uris, ctx, **kwargs)\n\n    async def summarize(\n        self, resource_uris: List[str], ctx: RequestContext, **kwargs\n    ) -> Dict[str, Any]:\n        \"\"\"Manually trigger summarization.\n\n        Args:\n            resource_uris: List of resource URIs to summarize.\n            ctx: Request context.\n\n        Returns:\n            Processing result\n        \"\"\"\n        self._ensure_initialized()\n        return await self._resource_processor.summarize(resource_uris, ctx, **kwargs)\n\n    async def wait_processed(self) -> Dict[str, Any]:\n        \"\"\"Wait for all queued processing to complete.\n\n        Returns:\n            Queue status\n        \"\"\"\n        qm = get_queue_manager()\n        status = await qm.wait_complete()\n        return {\n            name: {\n                \"processed\": s.processed,\n                \"requeue_count\": getattr(s, \"requeue_count\", 0),\n                \"error_count\": s.error_count,\n                \"errors\": [{\"message\": e.message} for e in s.errors],\n            }\n            for name, s in status.items()\n        }\n"
    },
    {
      "path": "openviking/service/fs_service.py",
      "content": "# Copyright (c) 2026 Beijing Volcano Engine Technology Co., Ltd.\n# SPDX-License-Identifier: AGPL-3.0\n\"\"\"\nFile System Service for OpenViking.\n\nProvides file system operations: ls, mkdir, rm, mv, tree, stat, read, abstract, overview, grep, glob.\n\"\"\"\n\nimport asyncio\nfrom collections.abc import Coroutine\nfrom dataclasses import dataclass, replace\nfrom functools import partial\nfrom typing import TYPE_CHECKING, Any, Awaitable, Callable, Dict, List, Literal, Optional\n\nfrom openviking.core.context import ContextLevel\nfrom openviking.core.namespace import (\n    canonical_session_root,\n    classify_uri,\n    content_owner_context_for_uri,\n    context_type_for_uri,\n    is_session_uri,\n    uri_leaf_name,\n    uri_parts,\n)\nfrom openviking.core.namespace_policy import (\n    NamespaceProcessingMode,\n    namespace_policy_for_uri,\n)\nfrom openviking.privacy.sanitizer import PrivacySanitizer\nfrom openviking.privacy.service import UserPrivacyConfigService\nfrom openviking.privacy.session_restore import get_session_id_from_uri, restore_session_content\nfrom openviking.privacy.skill_restore import get_skill_name_from_uri, restore_skill_content\nfrom openviking.resource.uri_mutation_coordinator import UriMutationCoordinator\nfrom openviking.resource.watch_storage import is_watch_task_control_uri\nfrom openviking.server.error_mapping import is_not_found_error\nfrom openviking.server.identity import RequestContext\nfrom openviking.service.task_tracker import TaskStatus, get_task_tracker, run_tracked_operation\nfrom openviking.service.task_tracker_concurrency import run_to_completion\nfrom openviking.service.task_work_index import (\n    bind_task_context,\n    detach_task_context,\n    get_enqueued_work_ids,\n    get_task_context,\n)\nfrom openviking.session.memory.account_templates import (\n    validate_account_memory_template_transfer,\n)\nfrom openviking.session.memory.memory_updater import MemoryUpdater\nfrom openviking.session.memory.utils.content_visibility import visible_content\nfrom openviking.storage.abstract_overview import (\n    AbstractOverviewFormatError,\n    body_for_preview,\n    is_abstract_overview_uri,\n    mark_abstract_overview_pending,\n    plan_abstract_overview_refresh,\n    render_abstract_overview,\n)\nfrom openviking.storage.acl import AclAction, AclMode, AclSpec\nfrom openviking.storage.content_write import ContentWriteCoordinator\nfrom openviking.storage.errors import LockAcquisitionError, ResourceBusyError\nfrom openviking.storage.expr import And, Eq, In, Or\nfrom openviking.storage.internal_names import is_storage_internal_name\nfrom openviking.storage.pathlock_transfer import PathLockGuard\nfrom openviking.storage.queuefs import SemanticMsg, get_queue_manager\nfrom openviking.storage.queuefs.content_write_msg import ContentWriteMsg\nfrom openviking.storage.queuefs.semantic_msg import build_semantic_coalesce_key\nfrom openviking.storage.queuefs.semantic_ops.freshness_policy import FreshnessAction\nfrom openviking.storage.vector_ids import is_vector_record_id\nfrom openviking.storage.viking_fs import VikingFS\nfrom openviking.storage.vikingdb_manager import VikingDBManagerProxy\nfrom openviking.telemetry import get_current_telemetry\nfrom openviking.utils.embedding_utils import vectorize_directory_meta\nfrom openviking.utils.ingest_options import IngestOptions\nfrom openviking.utils.path_safety import validate_safe_viking_uri_path\nfrom openviking.utils.tags import normalize_search_tags\nfrom openviking_cli.exceptions import (\n    DeadlineExceededError,\n    InvalidArgumentError,\n    NotFoundError,\n    NotInitializedError,\n    OpenVikingError,\n    PermissionDeniedError,\n    ResourceExhaustedError,\n)\nfrom openviking_cli.utils import VikingURI, get_logger\nfrom openviking_cli.utils.config import get_openviking_config\n\nlogger = get_logger(__name__)\n\n# Compile waits for directory search visibility without rerunning generation.\n_COMPILE_DIRECTORY_TAG_TIMEOUT_SECONDS = 60.0\n_COMPILE_DIRECTORY_TAG_POLL_SECONDS = 3.0\n\n\n@dataclass\nclass ListingPage:\n    entries: List[Any]\n    has_more: bool\n\n\ndef _may_include_memory_content(uri: str) -> bool:\n    \"\"\"Return whether a public subtree read can contain memory files.\"\"\"\n    if is_session_uri(uri):\n        return False\n    classification = classify_uri(uri)\n    if classification.is_memory:\n        return True\n    if classification.content_index is not None:\n        return False\n    return not classification.parts or classification.scope in {\"user\", \"agent\"}\n\n\ndef _visible_grep_content(content: str, uri: str) -> str:\n    return visible_content(content, uri=uri)\n\n\nif TYPE_CHECKING:\n    from openviking.resource.watch_manager import WatchManager\n    from openviking.resource.watch_scheduler import WatchScheduler\n    from openviking.service.compile_targets import CompileLifecycle\n    from openviking.service.resource_memory_link_service import ResourceMemoryLinkService\n    from openviking.storage import VikingDBManager\n\n\nclass FSService:\n    \"\"\"File system operations service.\"\"\"\n\n    def __init__(\n        self,\n        viking_fs: Optional[VikingFS] = None,\n        vikingdb: Optional[\"VikingDBManager\"] = None,\n        privacy_config_service: Optional[UserPrivacyConfigService] = None,\n        resource_memory_link_service: Optional[\"ResourceMemoryLinkService\"] = None,\n        watch_scheduler: Optional[\"WatchScheduler\"] = None,\n        uri_mutation_coordinator: Optional[UriMutationCoordinator] = None,\n        privacy_sanitizer: Optional[PrivacySanitizer] = None,\n    ):\n        self._viking_fs = viking_fs\n        self._vikingdb = vikingdb\n        self._privacy_config_service = privacy_config_service\n        self._privacy_sanitizer = privacy_sanitizer or (\n            PrivacySanitizer(privacy_config_service) if privacy_config_service is not None else None\n        )\n        self._resource_memory_link_service = resource_memory_link_service\n        self._watch_scheduler = watch_scheduler\n        self._uri_mutation_coordinator = uri_mutation_coordinator or UriMutationCoordinator()\n        # Installed by OpenVikingService; records Compile output versions after writes.\n        self.compile_versions: Optional[Any] = None\n        # Installed by OpenVikingService; transfers exact-target Compile settings on mv.\n        self.compile_lifecycle: Optional[\"CompileLifecycle\"] = None\n\n    def set_dependencies(\n        self,\n        viking_fs: VikingFS,\n        vikingdb: Optional[\"VikingDBManager\"] = None,\n        privacy_config_service: Optional[UserPrivacyConfigService] = None,\n        resource_memory_link_service: Optional[\"ResourceMemoryLinkService\"] = None,\n        watch_scheduler: Optional[\"WatchScheduler\"] = None,\n        uri_mutation_coordinator: Optional[UriMutationCoordinator] = None,\n        privacy_sanitizer: Optional[PrivacySanitizer] = None,\n    ) -> None:\n        \"\"\"Set service dependencies (for deferred initialization).\"\"\"\n        self._viking_fs = viking_fs\n        self._vikingdb = vikingdb\n        self._privacy_config_service = privacy_config_service\n        self._privacy_sanitizer = privacy_sanitizer or (\n            PrivacySanitizer(privacy_config_service) if privacy_config_service is not None else None\n        )\n        self._resource_memory_link_service = resource_memory_link_service\n        self._watch_scheduler = watch_scheduler\n        if uri_mutation_coordinator is not None:\n            self._uri_mutation_coordinator = uri_mutation_coordinator\n\n    def _ensure_initialized(self) -> VikingFS:\n        \"\"\"Ensure VikingFS is initialized.\"\"\"\n        if not self._viking_fs:\n            raise NotInitializedError(\"VikingFS\")\n        return self._viking_fs\n\n    async def _resolve_uri(self, uri_or_id: str, ctx: RequestContext) -> str:\n        \"\"\"If ``uri_or_id`` is a 32-char hex vector record id, resolve it to the\n        corresponding Viking URI via the vector store. Otherwise return as-is.\n        Used so that service-layer helpers (classify_uri, get_skill_name_from_uri,\n        visible_content) always see a real URI, even when callers pass an id.\n        \"\"\"\n        if not is_vector_record_id(uri_or_id):\n            return uri_or_id\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.resolve_uri(uri_or_id, ctx=ctx)\n\n    def _get_watch_manager(self) -> Optional[\"WatchManager\"]:\n        if not self._watch_scheduler:\n            return None\n        return self._watch_scheduler.watch_manager\n\n    async def _attach_and_filter_tags(\n        self,\n        entries: List[Dict[str, Any]],\n        ctx: RequestContext,\n        tags: Optional[List[str]],\n        include_tags: bool,\n    ) -> List[Dict[str, Any]]:\n        normalized_tags = normalize_search_tags(tags, discard_invalid=True)\n        if not entries or (not normalized_tags and not include_tags):\n            return entries\n        tags_by_uri: Dict[str, List[str]] = {}\n        if self._vikingdb:\n            uris = list(\n                dict.fromkeys(str(entry.get(\"uri\") or \"\") for entry in entries if entry.get(\"uri\"))\n            )\n            if uris:\n                records = await VikingDBManagerProxy(self._vikingdb, ctx).filter(\n                    filter=And(\n                        [Or([Eq(\"uri\", item_uri) for item_uri in uris]), In(\"level\", [0, 1, 2])]\n                    ),\n                    limit=max(len(uris) * 3, 1),\n                    output_fields=[\"uri\", \"level\", \"search_tags\"],\n                )\n                records_by_uri: Dict[str, List[Dict[str, Any]]] = {}\n                for record in records:\n                    records_by_uri.setdefault(str(record.get(\"uri\") or \"\"), []).append(record)\n                for entry in entries:\n                    uri = str(entry.get(\"uri\") or \"\")\n                    levels = {0, 1} if entry.get(\"isDir\", False) else {2}\n                    found: List[str] = []\n                    for record in sorted(\n                        records_by_uri.get(uri, []), key=lambda item: item.get(\"level\", 99)\n                    ):\n                        if record.get(\"level\") in levels:\n                            for tag in normalize_search_tags(\n                                record.get(\"search_tags\"), discard_invalid=True\n                            ):\n                                if tag not in found:\n                                    found.append(tag)\n                    tags_by_uri[uri] = found\n        result_entries: List[Dict[str, Any]] = []\n        for entry in entries:\n            entry_tags = tags_by_uri.get(str(entry.get(\"uri\") or \"\"), [])\n            if normalized_tags and not set(normalized_tags).issubset(entry_tags):\n                continue\n            if include_tags:\n                entry = {**entry, \"tags\": entry_tags}\n            result_entries.append(entry)\n        return result_entries\n\n    async def _collect_tagged_page(\n        self,\n        fetch_page: Callable[[int, Optional[int]], Awaitable[List[Dict[str, Any]]]],\n        ctx: RequestContext,\n        tags: List[str],\n        include_tags: bool,\n        offset: int,\n        node_limit: int,\n    ) -> ListingPage:\n        \"\"\"Collect a visible page after tag filtering.\n\n        Args:\n            fetch_page: Loads one pre-tag page by offset and limit.\n            ctx: Request identity used for tag lookup.\n            tags: Required retrieval tags.\n            include_tags: Whether to retain tags in returned entries.\n            offset: Number of matched entries to skip.\n            node_limit: Maximum matched entries to return.\n\n        Returns:\n            The requested page and whether more matched entries are available.\n        \"\"\"\n        if node_limit <= 0:\n            entries = await fetch_page(0, None)\n            entries = await self._attach_and_filter_tags(entries, ctx, tags, include_tags)\n            return ListingPage(entries=entries[offset:], has_more=False)\n\n        batch_size = max(node_limit, 256)\n        probe_limit = node_limit + 1\n        source_offset = 0\n        remaining_offset = offset\n        result: List[Dict[str, Any]] = []\n        while len(result) < probe_limit:\n            entries = await fetch_page(source_offset, batch_size)\n            filtered = await self._attach_and_filter_tags(entries, ctx, tags, include_tags)\n            if remaining_offset >= len(filtered):\n                remaining_offset -= len(filtered)\n            else:\n                result.extend(\n                    filtered[remaining_offset : remaining_offset + probe_limit - len(result)]\n                )\n                remaining_offset = 0\n            if len(entries) < batch_size:\n                break\n            source_offset += len(entries)\n        return ListingPage(entries=result[:node_limit], has_more=len(result) > node_limit)\n\n    async def ls(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        recursive: bool = False,\n        simple: bool = False,\n        output: str = \"original\",\n        abs_limit: int = 256,\n        include_abstract: Optional[bool] = None,\n        include_overview: Optional[bool] = None,\n        overview_limit: int = 4000,\n        show_all_hidden: bool = False,\n        node_limit: int = 1000,\n        level_limit: int = 3,\n        sort_by: Optional[str] = None,\n        sort_order: str = \"asc\",\n        extra_fields: Optional[List[str]] = None,\n        tags: Optional[List[str]] = None,\n        include_tags: bool = False,\n        offset: int = 0,\n    ) -> ListingPage:\n        \"\"\"List directory contents.\n\n        Args:\n            uri: Viking URI\n            recursive: List all subdirectories recursively\n            simple: Return only relative path list\n            output: str = \"original\" or \"agent\"\n            abs_limit: Maximum returned abstract length\n            include_abstract: Include directory L0 abstracts; defaults to the output format\n            include_overview: Include directory L1 overviews\n            overview_limit: Maximum returned overview length\n            show_all_hidden: bool = False (list all hidden files, like -a)\n            node_limit: int = 1000 (maximum number of nodes to list)\n            sort_by: Optional sort field for non-recursive listings\n            sort_order: Sort direction, \"asc\" or \"desc\"\n            extra_fields: Optional extra fields to include (locked, id, count)\n        \"\"\"\n        viking_fs = self._ensure_initialized()\n        extra_fields = extra_fields or []\n        if namespace_policy_for_uri(uri).processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(uri, ctx)\n            unsupported_fields = {\"id\", \"count\", \"abstract\", \"overview\", \"tags\"}.intersection(\n                extra_fields\n            )\n            if tags or include_tags:\n                raise InvalidArgumentError(f\"tags are not supported for namespace: {uri}\")\n            if include_abstract is True or include_overview is True:\n                raise InvalidArgumentError(\n                    f\"semantic listing output is not supported for namespace: {uri}\"\n                )\n            if unsupported_fields:\n                raise InvalidArgumentError(\n                    f\"fields are not supported for namespace {uri}: \"\n                    + \", \".join(sorted(unsupported_fields))\n                )\n            include_abstract = False\n            include_overview = False\n        use_simple_paths = simple and not extra_fields\n\n        async def fetch_page(page_offset: int, page_limit: Optional[int]) -> List[Dict[str, Any]]:\n            \"\"\"Fetch and return one pre-tag page.\"\"\"\n            if recursive:\n                return await viking_fs.tree(\n                    uri,\n                    ctx=ctx,\n                    output=\"original\",\n                    abs_limit=abs_limit,\n                    include_abstract=None,\n                    include_overview=False,\n                    overview_limit=overview_limit,\n                    show_all_hidden=show_all_hidden,\n                    node_limit=page_limit,\n                    level_limit=level_limit,\n                    offset=page_offset,\n                    sort_by=sort_by,\n                    sort_order=sort_order,\n                    extra_fields=None,\n                )\n            return await viking_fs.ls(\n                uri,\n                ctx=ctx,\n                output=\"original\",\n                abs_limit=abs_limit,\n                include_abstract=None,\n                include_overview=False,\n                overview_limit=overview_limit,\n                show_all_hidden=show_all_hidden,\n                node_limit=page_limit,\n                offset=page_offset,\n                sort_by=sort_by,\n                sort_order=sort_order,\n                extra_fields=None,\n            )\n\n        if tags:\n            page = await self._collect_tagged_page(\n                fetch_page,\n                ctx,\n                tags,\n                False if use_simple_paths else include_tags or bool(tags) or \"tags\" in extra_fields,\n                offset,\n                node_limit,\n            )\n        else:\n            fetch_limit = node_limit + 1 if node_limit > 0 else node_limit\n            entries = await fetch_page(offset, fetch_limit)\n            entries = await self._attach_and_filter_tags(\n                entries, ctx, None, include_tags or \"tags\" in extra_fields\n            )\n            page = ListingPage(\n                entries=entries[:node_limit] if node_limit > 0 else entries,\n                has_more=node_limit > 0 and len(entries) > node_limit,\n            )\n        if use_simple_paths:\n            return ListingPage(\n                entries=[entry.get(\"uri\", \"\") for entry in page.entries],\n                has_more=page.has_more,\n            )\n        if (\n            output != \"original\"\n            or extra_fields\n            or include_abstract is True\n            or include_overview is True\n        ):\n            return ListingPage(\n                entries=await viking_fs._finalize_listing_entries(\n                    page.entries,\n                    output,\n                    abs_limit,\n                    extra_fields,\n                    recursive,\n                    ctx=ctx,\n                    include_abstract=include_abstract,\n                    include_overview=include_overview is True,\n                    overview_limit=overview_limit,\n                ),\n                has_more=page.has_more,\n            )\n        return page\n\n    @staticmethod\n    def _reject_storage_internal_target(uri: str) -> None:\n        \"\"\"Reject reserved names in targets and implicitly created parent directories.\"\"\"\n        if any(is_storage_internal_name(part) for part in uri_parts(uri)):\n            raise InvalidArgumentError(f\"cannot create storage internal name: {uri}\")\n\n    @staticmethod\n    def _reject_file_only_semantic_sidecar_target(uri: str) -> None:\n        if namespace_policy_for_uri(\n            uri\n        ).processing_mode is NamespaceProcessingMode.FILE_ONLY and is_abstract_overview_uri(uri):\n            raise InvalidArgumentError(f\"semantic sidecars are not supported for namespace: {uri}\")\n\n    async def mkdir(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        description: Optional[str] = None,\n        acl: AclSpec | Dict[str, Any] | None = None,\n    ) -> None:\n        \"\"\"Create directory.\"\"\"\n        viking_fs = self._ensure_initialized()\n        self._reject_storage_internal_target(uri)\n        directory_uri, abstract_uri = self._resolve_directory_uris(uri)\n        namespace_policy = namespace_policy_for_uri(directory_uri)\n        if namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(directory_uri, ctx, action=AclAction.WRITE)\n            if acl is not None and not namespace_policy.supports_acl:\n                raise InvalidArgumentError(f\"ACL is not supported for namespace: {directory_uri}\")\n            if description is not None:\n                raise InvalidArgumentError(\n                    f\"directory descriptions are not supported for namespace: {directory_uri}\"\n                )\n            async with self._uri_mutation_coordinator.mutation(ctx.account_id, [directory_uri]):\n                await viking_fs.mkdir(uri, ctx=ctx)\n                return\n\n        versions = self.compile_versions\n        managed = versions is not None and await versions.owning_target(\n            ctx.account_id, directory_uri\n        )\n\n        async def create():\n            async with self._uri_mutation_coordinator.mutation(ctx.account_id, [directory_uri]):\n                acl_update = (\n                    await viking_fs.prepare_acl_update(directory_uri, acl, ctx)\n                    if acl is not None\n                    else None\n                )\n                lease = None\n                if managed:\n                    await viking_fs._ensure_access(directory_uri, ctx, action=AclAction.WRITE)\n                    parent = VikingURI(directory_uri).parent.uri\n                    while not await viking_fs.exists(parent, ctx=ctx):\n                        parent = VikingURI(parent).parent.uri\n                    lease = await viking_fs._async_agfs.pathlock_acquire_tree(\n                        viking_fs._uri_to_path(parent, ctx=ctx)\n                    )\n                try:\n                    await viking_fs.mkdir(uri, ctx=ctx, **({\"lease_ref\": lease} if lease else {}))\n                    if not managed:\n                        lease = await viking_fs._async_agfs.pathlock_acquire_exact(\n                            viking_fs._uri_to_path(abstract_uri, ctx=ctx)\n                        )\n                    await initialize(acl_update, lease)\n                finally:\n                    if lease is not None:\n                        await viking_fs._async_agfs.pathlock_release(lease)\n\n        async def initialize(acl_update, lease):\n            abstract = self._normalize_directory_description(description)\n            if not abstract:\n                abstract = f\"# {uri_leaf_name(directory_uri)}\"\n\n            await viking_fs.write_file(\n                abstract_uri,\n                render_abstract_overview(\n                    ContextLevel.ABSTRACT,\n                    directory_uri,\n                    abstract,\n                    {\n                        \"generated_by\": {\n                            \"component\": \"FSService\",\n                            \"trigger\": \"mkdir\",\n                        },\n                        \"freshness\": {\n                            \"total_entries\": 0,\n                            \"sampled_entries\": 0,\n                            \"unsampled_entries\": 0,\n                            \"pending_child_changes\": 0,\n                        },\n                    },\n                ),\n                ctx=ctx,\n                lease_ref=lease,\n            )\n            await vectorize_directory_meta(\n                uri=directory_uri,\n                abstract=abstract,\n                overview=\"\",\n                context_type=context_type_for_uri(directory_uri),\n                ctx=ctx,\n                ingest_options=IngestOptions(acl_update=acl_update),\n                include_overview=False,\n            )\n\n        if managed:\n            await run_to_completion(\n                lambda: versions.record_operation([directory_uri], ctx, \"mkdir\", {}, create)\n            )\n        else:\n            await create()\n\n    @staticmethod\n    def _normalize_directory_description(description: Optional[str]) -> Optional[str]:\n        if description is None:\n            return None\n        abstract = description.strip()\n        return abstract or None\n\n    @staticmethod\n    def _resolve_directory_uris(uri: str) -> tuple[str, str]:\n        abstract_uri = VikingURI(uri).join(\".abstract.md\").uri\n        directory_uri = VikingURI(abstract_uri).parent.uri\n        return directory_uri, abstract_uri\n\n    async def rm(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        recursive: bool = False,\n        wait: bool = False,\n    ) -> Optional[Dict[str, Any]]:\n        async def execute() -> Optional[Dict[str, Any]]:\n            return await self._rm(\n                uri,\n                ctx,\n                recursive=recursive,\n                wait=wait,\n            )\n\n        result, _task_id = await run_tracked_operation(\n            \"fs_rm\",\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            operation=execute,\n            wait=wait,\n            resource_id=uri,\n        )\n        return result\n\n    async def _rm(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        recursive: bool = False,\n        wait: bool = False,\n    ) -> Optional[Dict[str, Any]]:\n        \"\"\"Remove content and refresh derived data without changing Compile metadata.\"\"\"\n        viking_fs = self._ensure_initialized()\n        await viking_fs._ensure_access(uri, ctx, action=AclAction.MANAGE)\n        delete_ctx = replace(ctx, bypass_acl=True)\n        namespace_policy = namespace_policy_for_uri(uri)\n        if namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            result = await viking_fs.rm(uri, recursive=recursive, ctx=delete_ctx, no_vector=True)\n            if isinstance(result, dict):\n                result[\"semantic_status\"] = \"skipped\"\n                result[\"vector_status\"] = \"skipped\"\n            return result\n\n        cleanup_result: Optional[Dict[str, Any]] = None\n        context_type = context_type_for_uri(uri)\n        refresh_parent_uri = self._semantic_refresh_parent_uri(uri, context_type)\n        memory_overview_uri = self._memory_overview_parent_uri(uri, context_type)\n        result = await viking_fs.rm(uri, recursive=recursive, ctx=delete_ctx)\n        await self._sync_watch_after_rm(uri, account_id=ctx.account_id, context_type=context_type)\n        # A refresh on a parent that no longer exists would lock its sidecar\n        # paths and thereby recreate the deleted directory. Nothing to\n        # summarize there; skip it.\n        if refresh_parent_uri and not await viking_fs.exists(refresh_parent_uri, ctx=ctx):\n            refresh_parent_uri = None\n        queue_status = None\n        refresh_action: Optional[FreshnessAction] = None\n        try:\n            if refresh_parent_uri:\n                refresh_action = await self._enqueue_delete_refresh(\n                    root_uri=refresh_parent_uri,\n                    deleted_uri=uri,\n                    context_type=context_type,\n                    ctx=ctx,\n                    force_refresh=wait,\n                )\n            if self._resource_memory_link_service and context_type == \"resource\":\n                cleanup_result = await self._resource_memory_link_service.before_resource_delete(\n                    ctx=ctx,\n                    resource_uri=uri,\n                    recursive=recursive,\n                )\n            if memory_overview_uri:\n                await MemoryUpdater.refresh_schema_overview(\n                    viking_fs=viking_fs,\n                    directory_uri=memory_overview_uri,\n                    ctx=ctx,\n                )\n            for cleanup_overview_uri in self._memory_overview_parent_uris_from_cleanup(\n                cleanup_result\n            ):\n                await MemoryUpdater.refresh_schema_overview(\n                    viking_fs=viking_fs,\n                    directory_uri=cleanup_overview_uri,\n                    ctx=ctx,\n                )\n            if refresh_parent_uri and wait and refresh_action is not FreshnessAction.MARK_PENDING:\n                queue_status = await self._wait_for_refresh()\n        finally:\n            pass\n        if cleanup_result is not None and isinstance(result, dict):\n            result[\"memory_cleanup\"] = cleanup_result\n        if refresh_parent_uri and isinstance(result, dict):\n            result[\"semantic_root_uri\"] = refresh_parent_uri\n            result[\"semantic_status\"] = (\n                \"deferred\"\n                if refresh_action is FreshnessAction.MARK_PENDING\n                else self._semantic_refresh_status(wait=wait, queue_status=queue_status)\n            )\n            if queue_status is not None:\n                result[\"queue_status\"] = queue_status\n        return result\n\n    @staticmethod\n    def _semantic_refresh_status(\n        *,\n        wait: bool,\n        queue_status: Optional[Dict[str, Any]],\n    ) -> str:\n        if not wait:\n            return \"queued\"\n        if not isinstance(queue_status, dict):\n            return \"complete\"\n        semantic = queue_status.get(\"Semantic\", {})\n        if not isinstance(semantic, dict):\n            return \"complete\"\n        try:\n            if int(semantic.get(\"error_count\", 0) or 0) > 0:\n                return \"failed\"\n        except (TypeError, ValueError):\n            if semantic.get(\"errors\"):\n                return \"failed\"\n        if semantic.get(\"errors\"):\n            return \"failed\"\n        return \"complete\"\n\n    @staticmethod\n    def _semantic_refresh_parent_uri(uri: str, context_type: str) -> Optional[str]:\n        if namespace_policy_for_uri(uri).processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            return None\n        if context_type not in {\"resource\", \"skill\"}:\n            return None\n        parent = VikingURI(uri).parent\n        if context_type == \"skill\":\n            if parent is None:\n                return None\n            classification = classify_uri(parent.uri)\n            if (\n                not classification.is_skill\n                or classification.is_skill_root\n                or classification.is_skill_namespace\n            ):\n                return None\n        return parent.uri if parent and parent.scope else None\n\n    @staticmethod\n    def _memory_overview_parent_uri(uri: str, context_type: str) -> Optional[str]:\n        if context_type != \"memory\":\n            return None\n        leaf = uri.rstrip(\"/\").rsplit(\"/\", 1)[-1]\n        if leaf in {\".abstract.md\", \".overview.md\", \".relations.json\"}:\n            return None\n        parent = VikingURI(uri).parent\n        if parent is None:\n            return None\n        if not MemoryUpdater.memory_type_from_uri(parent.uri):\n            return None\n        return parent.uri\n\n    @classmethod\n    def _memory_overview_parent_uris_from_cleanup(\n        cls,\n        cleanup_result: Optional[Dict[str, Any]],\n    ) -> List[str]:\n        if not isinstance(cleanup_result, dict):\n            return []\n\n        overview_uris: List[str] = []\n        for field in (\"memory_uris\", \"deleted_memory_uris\"):\n            values = cleanup_result.get(field)\n            if not isinstance(values, list):\n                continue\n            for memory_uri in values:\n                if not isinstance(memory_uri, str):\n                    continue\n                overview_uri = cls._memory_overview_parent_uri(\n                    memory_uri,\n                    context_type_for_uri(memory_uri),\n                )\n                if overview_uri:\n                    overview_uris.append(overview_uri)\n        return list(dict.fromkeys(overview_uris))\n\n    async def _enqueue_delete_refresh(\n        self,\n        *,\n        root_uri: str,\n        deleted_uri: str,\n        context_type: str,\n        ctx: RequestContext,\n        force_refresh: bool = False,\n    ) -> FreshnessAction:\n        semantic_config = get_openviking_config().semantic\n        decision = await plan_abstract_overview_refresh(\n            viking_fs=self._viking_fs,\n            dir_uri=root_uri,\n            changed_entries=1,\n            ctx=ctx,\n            overview_sample_limit=getattr(semantic_config, \"overview_sample_limit\", 32),\n            refresh_ratio=getattr(semantic_config, \"freshness_refresh_ratio\", 0.10),\n            force_refresh=force_refresh,\n        )\n        if decision.action is not FreshnessAction.REFRESH_NOW:\n            return decision.action\n        try:\n            queue_manager = get_queue_manager()\n        except RuntimeError as exc:\n            logger.warning(\"QueueManager not available, skipping delete refresh: %s\", exc)\n            return decision.action\n        semantic_queue = queue_manager.get_queue(queue_manager.SEMANTIC, allow_create=True)\n        telemetry_id = get_current_telemetry().telemetry_id\n        msg = SemanticMsg(\n            uri=root_uri,\n            context_type=context_type,\n            recursive=False,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            group_ids=ctx.group_ids,\n            peer_id=ctx.user.user_id,\n            role=str(ctx.role),\n            skip_vectorization=False,\n            telemetry_id=telemetry_id,\n            coalesce_key=build_semantic_coalesce_key(\n                context_type=context_type,\n                uri=root_uri,\n                account_id=ctx.account_id,\n                user_id=ctx.user.user_id,\n                peer_id=ctx.user.user_id,\n            ),\n            changes={\"deleted\": [deleted_uri]},\n            generation_trigger=\"content_delete\",\n        )\n        await semantic_queue.enqueue(msg)\n        return decision.action\n\n    async def _enqueue_copy_refresh(\n        self,\n        *,\n        root_uri: str,\n        source_uri: str,\n        copied_uri: str,\n        context_type: str,\n        ctx: RequestContext,\n        change_kind: Literal[\"added\", \"deleted\"] = \"added\",\n    ) -> str:\n        \"\"\"Queue a parent-only semantic refresh after a committed transfer.\"\"\"\n        await mark_abstract_overview_pending(\n            viking_fs=self._viking_fs,\n            dir_uri=root_uri,\n            changed_entries=1,\n            ctx=ctx,\n        )\n        try:\n            queue_manager = get_queue_manager()\n        except RuntimeError as exc:\n            logger.warning(\"QueueManager not available, skipping copy refresh: %s\", exc)\n            return \"skipped\"\n\n        semantic_queue = queue_manager.get_queue(queue_manager.SEMANTIC, allow_create=True)\n        telemetry_id = get_current_telemetry().telemetry_id\n        msg = SemanticMsg(\n            uri=root_uri,\n            context_type=context_type,\n            recursive=False,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            peer_id=ctx.user.user_id,\n            role=str(ctx.role),\n            skip_vectorization=False,\n            telemetry_id=telemetry_id,\n            coalesce_key=build_semantic_coalesce_key(\n                context_type=context_type,\n                uri=root_uri,\n                account_id=ctx.account_id,\n                user_id=ctx.user.user_id,\n                peer_id=ctx.user.user_id,\n            ),\n            changes={change_kind: [copied_uri]},\n            generation_trigger=\"content_copy\",\n            copy_source_uri=source_uri,\n        )\n        await semantic_queue.enqueue(msg)\n        return \"queued\"\n\n    async def _enqueue_transfer_rebuild(\n        self,\n        *,\n        root_uri: str,\n        target_uri: str,\n        recursive: bool,\n        context_type: str,\n        ctx: RequestContext,\n    ) -> str:\n        \"\"\"Queue fresh semantic processing when the source has no index artifacts.\"\"\"\n        if not recursive:\n            await mark_abstract_overview_pending(\n                viking_fs=self._viking_fs,\n                dir_uri=root_uri,\n                changed_entries=1,\n                ctx=ctx,\n            )\n        try:\n            queue_manager = get_queue_manager()\n        except RuntimeError as exc:\n            logger.warning(\"QueueManager not available, skipping transfer rebuild: %s\", exc)\n            return \"skipped\"\n        semantic_queue = queue_manager.get_queue(queue_manager.SEMANTIC, allow_create=True)\n        telemetry_id = get_current_telemetry().telemetry_id\n        msg = SemanticMsg(\n            uri=root_uri,\n            context_type=context_type,\n            recursive=recursive,\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            group_ids=ctx.group_ids,\n            peer_id=ctx.user.user_id,\n            role=str(ctx.role),\n            skip_vectorization=False,\n            telemetry_id=telemetry_id,\n            coalesce_key=(\n                \"\"\n                if recursive\n                else build_semantic_coalesce_key(\n                    context_type=context_type,\n                    uri=root_uri,\n                    account_id=ctx.account_id,\n                    user_id=ctx.user.user_id,\n                    peer_id=ctx.user.user_id,\n                )\n            ),\n            changes=None if recursive else {\"added\": [target_uri]},\n            generation_trigger=\"content_transfer_rebuild\",\n        )\n        await semantic_queue.enqueue(msg)\n        return \"queued\"\n\n    async def _wait_for_refresh(self) -> Dict[str, Any]:\n        context = get_task_context()\n        if context is None:\n            raise RuntimeError(\"TaskContext is required for request-scoped queue waiting\")\n        work_ids = get_enqueued_work_ids()\n        tracker = get_task_tracker()\n        try:\n            if context.work_id is None:\n                await tracker.wait_for_task_work(context.task_id, timeout=None)\n            elif work_ids:\n                await tracker.wait_for_work(\n                    context.task_id,\n                    work_ids,\n                    timeout=None,\n                )\n        except (TimeoutError, asyncio.TimeoutError) as exc:\n            raise DeadlineExceededError(\"queue processing\", None) from exc\n        return await tracker.build_queue_status(\n            context.task_id, work_ids if context.work_id is not None else None\n        )\n\n    async def cp(\n        self,\n        from_uri: str,\n        to_uri: str,\n        recursive: bool,\n        ctx: RequestContext,\n    ) -> Dict[str, Any]:\n        \"\"\"Copy a resource without exposing a cancellable partial transaction.\"\"\"\n        from_uri = VikingFS._normalize_transfer_uri(from_uri)\n        to_uri = VikingFS._normalize_transfer_uri(to_uri)\n        self._reject_storage_internal_target(to_uri)\n        self._reject_file_only_semantic_sidecar_target(to_uri)\n        validate_account_memory_template_transfer(to_uri)\n        return await self._finish_transfer_after_caller_cancel(\n            self._cp_and_refresh(from_uri, to_uri, recursive=recursive, ctx=ctx),\n            operation=\"copy\",\n        )\n\n    async def _cp_and_refresh(\n        self,\n        from_uri: str,\n        to_uri: str,\n        *,\n        recursive: bool,\n        ctx: RequestContext,\n    ) -> Dict[str, Any]:\n        \"\"\"Copy and refresh as one cancellation-safe unit, leaving Compile metadata intact.\"\"\"\n        viking_fs = self._ensure_initialized()\n        source_policy = namespace_policy_for_uri(from_uri)\n        target_policy = namespace_policy_for_uri(to_uri)\n        source_indexed = source_policy.processing_mode is NamespaceProcessingMode.INDEXED\n        target_indexed = target_policy.processing_mode is NamespaceProcessingMode.INDEXED\n\n        async with self._uri_mutation_coordinator.mutation(ctx.account_id, [from_uri, to_uri]):\n            options = {}\n            if not (source_indexed and target_indexed):\n                options.update(\n                    maintain_vectors=False,\n                    copy_semantic_sidecars=False,\n                )\n            transfer_result = await viking_fs.cp(\n                from_uri,\n                to_uri,\n                recursive=recursive,\n                ctx=ctx,\n                **options,\n            )\n\n        result = dict(transfer_result or {})\n        result.setdefault(\"from\", from_uri)\n        result.setdefault(\"to\", to_uri)\n        result.setdefault(\"recursive\", recursive)\n        context_type = context_type_for_uri(to_uri)\n        if not source_indexed and target_indexed:\n            target_stat = await viking_fs.stat(to_uri, ctx=ctx, skip_count=True)\n            target_is_dir = bool(target_stat.get(\"isDir\"))\n            rebuild_root_uri = (\n                to_uri if target_is_dir else self._semantic_refresh_parent_uri(to_uri, context_type)\n            )\n            if not rebuild_root_uri:\n                result[\"semantic_status\"] = \"skipped\"\n                result[\"vector_status\"] = \"skipped\"\n                return result\n            result[\"semantic_root_uri\"] = rebuild_root_uri\n            try:\n                result[\"semantic_status\"] = await self._enqueue_transfer_rebuild(\n                    root_uri=rebuild_root_uri,\n                    target_uri=to_uri,\n                    recursive=target_is_dir,\n                    context_type=context_type,\n                    ctx=ctx,\n                )\n            except Exception as exc:\n                logger.warning(\n                    \"Copy committed but semantic rebuild failed for %s: %s\",\n                    to_uri,\n                    exc,\n                )\n                result[\"semantic_status\"] = \"failed\"\n                result[\"semantic_error\"] = str(exc)\n            return result\n\n        refresh_parent_uri = self._semantic_refresh_parent_uri(to_uri, context_type)\n        if not refresh_parent_uri:\n            if target_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY:\n                result[\"semantic_status\"] = \"skipped\"\n                result[\"vector_status\"] = \"skipped\"\n            return result\n\n        result[\"semantic_root_uri\"] = refresh_parent_uri\n        try:\n            result[\"semantic_status\"] = await self._enqueue_copy_refresh(\n                root_uri=refresh_parent_uri,\n                source_uri=from_uri,\n                copied_uri=to_uri,\n                context_type=context_type,\n                ctx=ctx,\n            )\n        except Exception as exc:\n            logger.warning(\n                \"Copy committed but parent semantic refresh failed for %s: %s\",\n                to_uri,\n                exc,\n            )\n            result[\"semantic_status\"] = \"failed\"\n            result[\"semantic_error\"] = str(exc)\n        return result\n\n    async def mv(self, from_uri: str, to_uri: str, ctx: RequestContext) -> None:\n        \"\"\"Move a resource without exposing a cancellable partial transaction.\"\"\"\n        from_uri = VikingFS._normalize_transfer_uri(from_uri)\n        to_uri = VikingFS._normalize_transfer_uri(to_uri)\n        self._reject_storage_internal_target(to_uri)\n        self._reject_file_only_semantic_sidecar_target(to_uri)\n        validate_account_memory_template_transfer(to_uri)\n        await self._finish_transfer_after_caller_cancel(\n            self._mv_and_refresh(from_uri, to_uri, ctx=ctx),\n            operation=\"move\",\n        )\n\n    async def _mv_and_refresh(\n        self,\n        from_uri: str,\n        to_uri: str,\n        *,\n        ctx: RequestContext,\n    ) -> None:\n        \"\"\"Move content and Watch state, migrate exact-target Compile settings, and refresh parents.\"\"\"\n        viking_fs = self._ensure_initialized()\n        await viking_fs._ensure_access(from_uri, ctx, action=AclAction.MANAGE)\n        await viking_fs._ensure_destination_access(to_uri, ctx)\n        move_ctx = replace(ctx, bypass_acl=True)\n        watch_manager = self._get_watch_manager()\n        use_watch_transaction = (\n            watch_manager is not None\n            and context_type_for_uri(from_uri) == \"resource\"\n            and context_type_for_uri(to_uri) == \"resource\"\n            and namespace_policy_for_uri(from_uri).processing_mode\n            is NamespaceProcessingMode.INDEXED\n            and namespace_policy_for_uri(to_uri).processing_mode is NamespaceProcessingMode.INDEXED\n            and not is_watch_task_control_uri(from_uri)\n            and not is_watch_task_control_uri(to_uri)\n        )\n        source_policy = namespace_policy_for_uri(from_uri)\n        target_policy = namespace_policy_for_uri(to_uri)\n        source_indexed = source_policy.processing_mode is NamespaceProcessingMode.INDEXED\n        target_indexed = target_policy.processing_mode is NamespaceProcessingMode.INDEXED\n        vector_mode: Literal[\"transfer\", \"delete_source\", \"none\"]\n        if source_indexed and target_indexed:\n            vector_mode = \"transfer\"\n        elif source_indexed:\n            vector_mode = \"delete_source\"\n        else:\n            vector_mode = \"none\"\n\n        async with self._uri_mutation_coordinator.mutation(ctx.account_id, [from_uri, to_uri]):\n            if use_watch_transaction:\n                await watch_manager.validate_target_prefix_rewrite_internal(\n                    from_uri, to_uri, account_id=ctx.account_id\n                )\n            options = {}\n            if vector_mode != \"transfer\":\n                options.update(\n                    vector_mode=vector_mode,\n                    copy_semantic_sidecars=False,\n                )\n            result = await viking_fs.mv(\n                from_uri,\n                to_uri,\n                ctx=move_ctx,\n                **options,\n            )\n            if use_watch_transaction:\n                try:\n                    await watch_manager.rewrite_target_prefix_internal(\n                        from_uri, to_uri, account_id=ctx.account_id\n                    )\n                except Exception as commit_error:\n                    try:\n                        await viking_fs.mv(\n                            to_uri,\n                            from_uri,\n                            ctx=move_ctx,\n                            restore_acl=result.get(\"source_acl\", {}),\n                            **options,\n                        )\n                    except Exception as rollback_error:\n                        logger.exception(\"Move rollback failed: %s -> %s\", to_uri, from_uri)\n                        raise rollback_error from commit_error\n                    raise\n            if self.compile_lifecycle is not None:\n                try:\n                    await self.compile_lifecycle.move_target(from_uri, to_uri, ctx)\n                except Exception as exc:\n                    if isinstance(exc, OpenVikingError) and exc.details.get(\"move_committed\"):\n                        raise\n                    raise OpenVikingError(\n                        f\"Content moved, but Compile configuration migration failed: {exc}\",\n                        code=getattr(exc, \"code\", \"INTERNAL\"),\n                        details={\n                            **(exc.details if isinstance(exc, OpenVikingError) else {}),\n                            \"from\": from_uri,\n                            \"to\": to_uri,\n                            \"move_committed\": True,\n                            \"phase\": \"compile_config\",\n                        },\n                    ) from exc\n        rebuild_target = not source_indexed and target_indexed\n        if rebuild_target:\n            await self._refresh_move_parents(\n                from_uri=from_uri,\n                to_uri=to_uri,\n                ctx=ctx,\n                refresh_target=False,\n            )\n            target_stat = await viking_fs.stat(to_uri, ctx=ctx, skip_count=True)\n            target_is_dir = bool(target_stat.get(\"isDir\"))\n            context_type = context_type_for_uri(to_uri)\n            rebuild_root_uri = (\n                to_uri if target_is_dir else self._semantic_refresh_parent_uri(to_uri, context_type)\n            )\n            if rebuild_root_uri:\n                try:\n                    await self._enqueue_transfer_rebuild(\n                        root_uri=rebuild_root_uri,\n                        target_uri=to_uri,\n                        recursive=target_is_dir,\n                        context_type=context_type,\n                        ctx=ctx,\n                    )\n                except Exception as exc:\n                    logger.warning(\n                        \"Move committed but semantic rebuild failed for %s: %s\",\n                        to_uri,\n                        exc,\n                    )\n        else:\n            await self._refresh_move_parents(from_uri=from_uri, to_uri=to_uri, ctx=ctx)\n\n    async def _finish_transfer_after_caller_cancel(\n        self,\n        transaction: Coroutine[Any, Any, Any],\n        *,\n        operation: str,\n    ) -> Any:\n        \"\"\"Finish an already-started transfer before propagating caller cancellation.\"\"\"\n        transaction_task = asyncio.create_task(transaction)\n        try:\n            return await asyncio.shield(transaction_task)\n        except asyncio.CancelledError:\n            while not transaction_task.done():\n                try:\n                    await asyncio.shield(transaction_task)\n                except asyncio.CancelledError:\n                    continue\n                except Exception:\n                    break\n            try:\n                transaction_task.result()\n            except asyncio.CancelledError:\n                pass\n            except Exception:\n                logger.error(\n                    \"Filesystem %s transaction failed while caller was cancelled\",\n                    operation,\n                    exc_info=True,\n                )\n            raise\n\n    async def _refresh_move_parents(\n        self,\n        *,\n        from_uri: str,\n        to_uri: str,\n        ctx: RequestContext,\n        refresh_target: bool = True,\n    ) -> None:\n        \"\"\"Queue transfer refreshes for both affected parents after mv commits.\"\"\"\n        if is_watch_task_control_uri(from_uri) or is_watch_task_control_uri(to_uri):\n            return\n\n        source_context_type = context_type_for_uri(from_uri)\n        target_context_type = context_type_for_uri(to_uri)\n        source_parent_uri = self._semantic_refresh_parent_uri(from_uri, source_context_type)\n        target_parent_uri = self._semantic_refresh_parent_uri(to_uri, target_context_type)\n\n        refreshes: List[tuple[str, str, Literal[\"added\", \"deleted\"], str]] = []\n        if source_parent_uri and source_parent_uri != target_parent_uri:\n            refreshes.append((source_parent_uri, from_uri, \"deleted\", source_context_type))\n        if target_parent_uri and refresh_target:\n            refreshes.append((target_parent_uri, to_uri, \"added\", target_context_type))\n\n        for parent_uri, changed_uri, change_kind, context_type in refreshes:\n            try:\n                await self._enqueue_copy_refresh(\n                    root_uri=parent_uri,\n                    source_uri=from_uri,\n                    copied_uri=changed_uri,\n                    change_kind=change_kind,\n                    context_type=context_type,\n                    ctx=ctx,\n                )\n            except Exception as exc:\n                logger.warning(\n                    \"Move committed but %s parent semantic refresh failed for %s: %s\",\n                    change_kind,\n                    parent_uri,\n                    exc,\n                )\n\n    async def _sync_watch_after_rm(self, uri: str, *, account_id: str, context_type: str) -> None:\n        if context_type != \"resource\":\n            return\n        if is_watch_task_control_uri(uri):\n            return\n        watch_manager = self._get_watch_manager()\n        if not watch_manager:\n            return\n        deactivated = await watch_manager.deactivate_tasks_under_uri_internal(uri, account_id)\n        if deactivated:\n            logger.info(\n                \"Deactivated %d watch task(s) after deleting %s\",\n                len(deactivated),\n                uri,\n            )\n\n    async def tree(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        output: str = \"original\",\n        abs_limit: int = 128,\n        show_all_hidden: bool = False,\n        node_limit: int = 1000,\n        level_limit: int = 3,\n        extra_fields: Optional[List[str]] = None,\n        tags: Optional[List[str]] = None,\n        include_tags: bool = False,\n        offset: int = 0,\n        directories_only: bool = False,\n        include_abstract: Optional[bool] = None,\n        include_overview: Optional[bool] = None,\n        overview_limit: int = 4000,\n    ) -> ListingPage:\n        \"\"\"Get directory tree.\"\"\"\n        viking_fs = self._ensure_initialized()\n        if namespace_policy_for_uri(uri).processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(uri, ctx)\n            unsupported_fields = {\"id\", \"count\", \"abstract\", \"overview\", \"tags\"}.intersection(\n                extra_fields or []\n            )\n            if tags or include_tags:\n                raise InvalidArgumentError(f\"tags are not supported for namespace: {uri}\")\n            if include_abstract is True or include_overview is True:\n                raise InvalidArgumentError(\n                    f\"semantic listing output is not supported for namespace: {uri}\"\n                )\n            if unsupported_fields:\n                raise InvalidArgumentError(\n                    f\"fields are not supported for namespace {uri}: \"\n                    + \", \".join(sorted(unsupported_fields))\n                )\n            include_abstract = False\n            include_overview = False\n\n        async def fetch_page(page_offset: int, page_limit: Optional[int]) -> List[Dict[str, Any]]:\n            \"\"\"Fetch and return one pre-tag tree page.\"\"\"\n            return await viking_fs.tree(\n                uri,\n                ctx=ctx,\n                output=\"original\" if tags else output,\n                abs_limit=abs_limit,\n                include_abstract=None if tags else include_abstract,\n                include_overview=False if tags else include_overview is True,\n                overview_limit=overview_limit,\n                show_all_hidden=show_all_hidden,\n                directories_only=directories_only,\n                node_limit=page_limit,\n                level_limit=level_limit,\n                extra_fields=None if tags else extra_fields,\n                offset=page_offset,\n            )\n\n        if tags:\n            page = await self._collect_tagged_page(\n                fetch_page,\n                ctx,\n                tags,\n                include_tags or bool(tags) or \"tags\" in (extra_fields or []),\n                offset,\n                node_limit,\n            )\n            if (\n                output != \"original\"\n                or extra_fields\n                or include_abstract is True\n                or include_overview is True\n            ):\n                return ListingPage(\n                    entries=await viking_fs._finalize_listing_entries(\n                        page.entries,\n                        output,\n                        abs_limit,\n                        extra_fields,\n                        True,\n                        ctx=ctx,\n                        include_abstract=include_abstract,\n                        include_overview=include_overview is True,\n                        overview_limit=overview_limit,\n                    ),\n                    has_more=page.has_more,\n                )\n            return page\n\n        fetch_limit = node_limit + 1 if node_limit > 0 else node_limit\n        entries = await fetch_page(offset, fetch_limit)\n        entries = await self._attach_and_filter_tags(\n            entries, ctx, None, include_tags or \"tags\" in (extra_fields or [])\n        )\n        return ListingPage(\n            entries=entries[:node_limit] if node_limit > 0 else entries,\n            has_more=node_limit > 0 and len(entries) > node_limit,\n        )\n\n    async def stat(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        skip_count: bool = False,\n        include_lock_status: bool = False,\n    ) -> Dict[str, Any]:\n        \"\"\"Get resource status.\"\"\"\n        viking_fs = self._ensure_initialized()\n        namespace_policy = namespace_policy_for_uri(uri)\n        kwargs = {\n            \"ctx\": ctx,\n            \"skip_count\": skip_count,\n            \"include_lock_status\": include_lock_status,\n        }\n        if namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            kwargs[\"skip_count\"] = True\n            kwargs[\"include_vector_fields\"] = False\n        return await viking_fs.stat(uri, **kwargs)\n\n    async def ensure_write_access(self, uri: str, ctx: RequestContext) -> None:\n        \"\"\"Validate write access without mutating the target.\"\"\"\n        viking_fs = self._ensure_initialized()\n        await viking_fs._ensure_access(uri, ctx, action=AclAction.WRITE)\n\n    async def _read_content(\n        self, uri: str, ctx: RequestContext, *, max_bytes: int | None = None\n    ) -> tuple[str, str]:\n        \"\"\"Resolve the URI and read stored content without Privacy restoration.\"\"\"\n        viking_fs = self._ensure_initialized()\n        resolved_uri = await self._resolve_uri(uri, ctx)\n        reader = (\n            viking_fs.read_file\n            if max_bytes is None\n            else partial(viking_fs.read_file_bytes, max_bytes=max_bytes)\n        )\n        try:\n            content = await reader(resolved_uri, ctx=ctx)\n        except NotFoundError:\n            if \"%20\" not in resolved_uri:\n                raise\n            legacy_uri = validate_safe_viking_uri_path(resolved_uri.replace(\"%20\", \" \"))\n            content = await reader(legacy_uri, ctx=ctx)\n            resolved_uri = legacy_uri\n        if max_bytes is not None:\n            content = viking_fs._decode_bytes(content)\n        return resolved_uri, content\n\n    async def read(self, uri: str, ctx: RequestContext, offset: int = 0, limit: int = -1) -> str:\n        \"\"\"Read file content, restoring Privacy references for Skills and Sessions.\"\"\"\n        resolved_uri, content = await self._read_content(uri, ctx)\n        if self._privacy_config_service is not None:\n            skill_name = get_skill_name_from_uri(resolved_uri)\n            session_id = get_session_id_from_uri(resolved_uri, canonical_session_root(ctx))\n            if skill_name is not None:\n                content = await restore_skill_content(\n                    self._privacy_config_service,\n                    content,\n                    ctx,\n                    skill_name=skill_name,\n                )\n            elif session_id is not None:\n                content = await restore_session_content(\n                    self._privacy_config_service,\n                    content,\n                    ctx,\n                    session_id=session_id,\n                    jsonl=resolved_uri.endswith(\"/messages.jsonl\"),\n                )\n\n        if offset == 0 and limit == -1:\n            return content\n        lines = content.splitlines(keepends=True)\n        sliced = lines[offset:] if limit == -1 else lines[offset : offset + limit]\n        return \"\".join(sliced)\n\n    async def read_visible(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        offset: int = 0,\n        limit: int = -1,\n    ) -> str:\n        \"\"\"Read public content, hiding reserved metadata from memory files.\n        Accepts a Viking URI or a 32-char hex vector record id.\n        \"\"\"\n        # Resolve id to URI before classify_uri / visible_content which expect\n        # a real viking:// URI.\n        resolved_uri = await self._resolve_uri(uri, ctx)\n        max_bytes = (\n            self._privacy_sanitizer.max_content_bytes\n            if self._privacy_sanitizer is not None\n            else None\n        )\n        try:\n            resolved_uri, content = await self._read_content(resolved_uri, ctx, max_bytes=max_bytes)\n        except ResourceExhaustedError as exc:\n            if not exc.details or exc.details.get(\"reason\") != \"read_limit_exceeded\":\n                raise\n            raise ResourceExhaustedError(\n                \"File exceeds the Privacy visible-read size limit\",\n                details={**exc.details, \"reason\": \"privacy_visible_read_limit_exceeded\"},\n            ) from exc\n        content = await self._make_content_visible(resolved_uri, content, ctx)\n        if offset == 0 and limit == -1:\n            return content\n        lines = content.splitlines(keepends=True)\n        sliced = lines[offset:] if limit == -1 else lines[offset : offset + limit]\n        return \"\".join(sliced)\n\n    async def _make_content_visible(self, uri: str, content: str, ctx: RequestContext) -> str:\n        \"\"\"Hide memory metadata and sanitize private values in already-read text.\"\"\"\n        if classify_uri(uri).is_memory:\n            content = visible_content(content, uri=uri)\n        if self._privacy_sanitizer is not None:\n            content = (\n                await self._privacy_sanitizer.sanitize(\n                    content,\n                    ctx=ctx,\n                    uri=uri,\n                    prefer_credentials=(\n                        get_session_id_from_uri(uri, canonical_session_root(ctx)) is not None\n                    ),\n                )\n            ).content\n        return content\n\n    async def abstract(self, uri: str, ctx: RequestContext) -> str:\n        \"\"\"Read L0 abstract (.abstract.md).\"\"\"\n        viking_fs = self._ensure_initialized()\n        if namespace_policy_for_uri(uri).processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(uri, ctx)\n            raise InvalidArgumentError(f\"abstract is not supported for namespace: {uri}\")\n        return await viking_fs.abstract(uri, ctx=ctx)\n\n    async def overview(self, uri: str, ctx: RequestContext) -> str:\n        \"\"\"Read L1 overview (.overview.md).\"\"\"\n        viking_fs = self._ensure_initialized()\n        if namespace_policy_for_uri(uri).processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(uri, ctx)\n            raise InvalidArgumentError(f\"overview is not supported for namespace: {uri}\")\n        return await viking_fs.overview(uri, ctx=ctx)\n\n    async def grep(\n        self,\n        uri: str,\n        pattern: str,\n        ctx: RequestContext,\n        exclude_uri: Optional[str] = None,\n        case_insensitive: bool = False,\n        node_limit: Optional[int] = None,\n        level_limit: int = 10,\n        tags: Optional[List[str]] = None,\n        include_tags: bool = False,\n        before_context: int = 0,\n        after_context: int = 0,\n    ) -> Dict:\n        \"\"\"Content search.\"\"\"\n        viking_fs = self._ensure_initialized()\n        namespace_policy = namespace_policy_for_uri(uri)\n        if namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(uri, ctx)\n            if tags or include_tags:\n                raise InvalidArgumentError(f\"tags are not supported for namespace: {uri}\")\n        normalized_tags = normalize_search_tags(tags, discard_invalid=True)\n        tag_filter = None\n        if normalized_tags:\n            from openviking.utils.tags import build_search_tags_filter\n\n            tag_filter = build_search_tags_filter(normalized_tags)\n        kwargs = {\n            \"exclude_uri\": exclude_uri,\n            \"case_insensitive\": case_insensitive,\n            \"node_limit\": node_limit,\n            \"level_limit\": level_limit,\n            \"ctx\": ctx,\n            \"tag_filter\": tag_filter,\n            \"include_tags\": include_tags or bool(normalized_tags),\n            \"before_context\": before_context,\n            \"after_context\": after_context,\n            \"force_fs\": namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY,\n        }\n        if _may_include_memory_content(uri):\n            kwargs[\"content_transform\"] = _visible_grep_content\n        result = dict(await viking_fs.grep(uri, pattern, **kwargs))\n        matches = result.get(\"matches\", [])\n        if include_tags and not normalized_tags and any(\"tags\" not in match for match in matches):\n            matches = await self._attach_and_filter_tags(matches, ctx, None, include_tags=True)\n        result[\"matches\"] = matches\n        result[\"count\"] = len(matches)\n        return result\n\n    async def glob(\n        self,\n        pattern: str,\n        ctx: RequestContext,\n        uri: str = \"viking://\",\n        node_limit: Optional[int] = None,\n        extra_fields: Optional[List[str]] = None,\n        tags: Optional[List[str]] = None,\n        include_tags: bool = False,\n    ) -> Dict:\n        \"\"\"File pattern matching.\"\"\"\n        viking_fs = self._ensure_initialized()\n        namespace_policy = namespace_policy_for_uri(uri)\n        if namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY:\n            await viking_fs._ensure_access(uri, ctx)\n            if tags or include_tags:\n                raise InvalidArgumentError(f\"tags are not supported for namespace: {uri}\")\n        unsupported_fields = {\"id\", \"count\", \"abstract\", \"overview\", \"tags\"}.intersection(\n            extra_fields or []\n        )\n        if unsupported_fields and (\n            namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY\n        ):\n            raise InvalidArgumentError(\n                f\"fields are not supported for namespace {uri}: \"\n                + \", \".join(sorted(unsupported_fields))\n            )\n        normalized_tags = normalize_search_tags(tags, discard_invalid=True)\n        project_tags = bool(normalized_tags) or include_tags\n        tag_filter = None\n        if normalized_tags:\n            from openviking.utils.tags import build_search_tags_filter\n\n            tag_filter = build_search_tags_filter(normalized_tags)\n        result = dict(\n            await viking_fs.glob(\n                pattern,\n                uri=uri,\n                node_limit=node_limit,\n                ctx=ctx,\n                extra_fields=extra_fields\n                if extra_fields is not None\n                else ([] if project_tags else None),\n                tag_filter=tag_filter,\n                force_fs=namespace_policy.processing_mode is NamespaceProcessingMode.FILE_ONLY,\n            )\n        )\n        if not project_tags:\n            return result\n\n        matches = await self._attach_and_filter_tags(\n            result.get(\"matches\", []), ctx, normalized_tags, include_tags=True\n        )\n        if node_limit is not None and node_limit > 0:\n            matches = matches[:node_limit]\n        result[\"matches\"] = matches\n        result[\"count\"] = len(matches)\n        return result\n\n    async def read_file_bytes(self, uri: str, ctx: RequestContext) -> bytes:\n        \"\"\"Read file as raw bytes.\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.read_file_bytes(uri, ctx=ctx)\n\n    async def write(\n        self,\n        uri: str,\n        content: str | bytes,\n        ctx: RequestContext,\n        mode: str = \"replace\",\n        wait: bool = False,\n        processing_mode: str = \"semantic_and_vectors\",\n        tags: Optional[List[str]] = None,\n        tag_mode: str = \"replace\",\n        acl: AclSpec | Dict[str, Any] | None = None,\n        edit_source: Literal[\"manual\", \"agent\", \"compile\"] = \"manual\",\n        commit_content: Optional[Callable[..., Awaitable[Any]]] = None,\n        resolve_conflicts: bool = False,\n    ) -> Dict[str, Any]:\n        \"\"\"Write content and refresh it after persisting managed output versions.\n\n        Internal restores supply ``commit_content`` to record their own version.\n        resolve_conflicts enables manual conflict resolution.\n        \"\"\"\n        viking_fs = self._ensure_initialized()\n        if commit_content is None and self.compile_versions is not None:\n            commit_content = partial(\n                self.compile_versions.record_write,\n                ctx=ctx,\n                edit_source=edit_source,\n                record_version=edit_source != \"compile\",\n            )\n        coordinator = ContentWriteCoordinator(\n            viking_fs=viking_fs,\n            vikingdb=self._vikingdb,\n            privacy_sanitizer=self._privacy_sanitizer,\n            commit_content=commit_content,\n        )\n        write = partial(\n            coordinator.write,\n            uri=uri,\n            content=content,\n            ctx=ctx,\n            mode=mode,\n            wait=wait,\n            processing_mode=processing_mode,\n            tags=tags,\n            tag_mode=tag_mode,\n            acl=acl,\n            resolve_conflicts=resolve_conflicts,\n        )\n        if self.compile_versions is None or edit_source == \"compile\":\n            return await write()\n        return await self.compile_versions.record_operation(\n            [uri], ctx, f\"{edit_source}_revise\", {\"mode\": mode}, write\n        )\n\n    async def batch_write(\n        self,\n        *,\n        root_uri: str,\n        operations: list[dict[str, Any]],\n        ctx: RequestContext,\n        wait: bool = True,\n        skip_conflicts: bool = False,\n        defer_processing: bool = False,\n        processing_mode: str = \"semantic_and_vectors\",\n        edit_source: Literal[\"manual\", \"agent\", \"compile\"] = \"manual\",\n    ) -> Dict[str, Any]:\n        \"\"\"Apply multiple file writes and aggregate downstream refresh.\"\"\"\n        viking_fs = self._ensure_initialized()\n        coordinator = ContentWriteCoordinator(\n            viking_fs=viking_fs,\n            vikingdb=self._vikingdb,\n            privacy_sanitizer=self._privacy_sanitizer,\n            commit_batch=(\n                partial(self.compile_versions.finish_batch, ctx=ctx, edit_source=edit_source)\n                if self.compile_versions is not None and edit_source != \"compile\"\n                else None\n            ),\n            commit_content=(\n                partial(\n                    self.compile_versions.record_write,\n                    ctx=ctx,\n                    edit_source=edit_source,\n                    record_version=False,\n                )\n                if self.compile_versions is not None\n                else None\n            ),\n        )\n        write = partial(\n            coordinator.batch_write,\n            root_uri=root_uri,\n            operations=operations,\n            ctx=ctx,\n            wait=wait,\n            skip_conflicts=skip_conflicts,\n            defer_processing=defer_processing,\n            processing_mode=processing_mode,\n        )\n        if self.compile_versions is None or edit_source == \"compile\":\n            return await write()\n        return await self.compile_versions.record_operation(\n            [operation[\"uri\"] for operation in operations],\n            ctx,\n            f\"{edit_source}_revise\",\n            {\"batch\": True},\n            write,\n        )\n\n    async def set_tags(\n        self,\n        uri: str,\n        tags: list[str],\n        mode: str,\n        recursive: bool,\n        ctx: RequestContext,\n    ) -> Dict[str, Any]:\n        \"\"\"Set explicit retrieval tags for a file or directory semantic nodes.\"\"\"\n        viking_fs = self._ensure_initialized()\n        coordinator = ContentWriteCoordinator(\n            viking_fs=viking_fs,\n            privacy_sanitizer=self._privacy_sanitizer,\n        )\n        return await coordinator.set_tags(\n            uri=uri,\n            tags=tags,\n            mode=mode,\n            recursive=recursive,\n            ctx=ctx,\n        )\n\n    async def _directory_index_records(self, uri: str, ctx: RequestContext) -> List[Dict[str, Any]]:\n        \"\"\"Read L0/L1 records and tags; propagate store errors.\"\"\"\n        store = self._ensure_initialized()._get_vector_store()\n        if store is None:\n            raise NotInitializedError(\"Vector store\")\n        records, cursor = await store.scroll(\n            filter=And([Eq(\"uri\", uri), In(\"level\", [0, 1])]),\n            limit=3,\n            output_fields=[\"id\", \"uri\", \"level\", \"search_tags\"],\n            ctx=ctx,\n        )\n        if cursor is not None or len({record[\"level\"] for record in records}) != len(records):\n            raise OpenVikingError(\n                f\"Duplicate directory index records: {uri}\", code=\"FAILED_PRECONDITION\"\n            )\n        return records\n\n    async def ensure_directory_index(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        fallback_abstract: str,\n        wait: bool = True,\n    ) -> Dict[str, Any]:\n        \"\"\"Preserve summaries; create fallback L0 only when both are absent.\n        Return readable levels with wait=True, otherwise queued work; invalid summaries fail.\n        \"\"\"\n        return await self._ensure_directory_index(uri, ctx, fallback_abstract, wait=wait)\n\n    async def _ensure_directory_index(\n        self,\n        uri: str,\n        ctx: RequestContext,\n        fallback_abstract: str,\n        wait: bool = True,\n        *,\n        require_abstract: bool = False,\n    ) -> Dict[str, Any]:\n        \"\"\"Index required summaries, rechecking missing content/indexes under the parent lock.\n        Complete indexes return without a Task; busy locks or invalid summaries raise.\n        ``require_abstract`` ensures Compile's L0 and marks its bookkeeping Task internal.\n        \"\"\"\n        viking_fs = self._ensure_initialized()\n        uri = validate_safe_viking_uri_path(uri)\n        self._reject_storage_internal_target(uri)\n        if (\n            namespace_policy_for_uri(uri).processing_mode is NamespaceProcessingMode.FILE_ONLY\n            or context_type_for_uri(uri) not in {\"resource\", \"memory\", \"skill\"}\n            or is_session_uri(uri)\n        ):\n            raise InvalidArgumentError(f\"directory indexing is not supported for namespace: {uri}\")\n        if not isinstance(fallback_abstract, str) or not fallback_abstract.strip():\n            raise InvalidArgumentError(\"fallback_abstract must not be empty\")\n        await viking_fs._ensure_access(uri, ctx, action=AclAction.WRITE)\n        if not (await viking_fs.stat(uri, ctx=ctx, skip_count=True)).get(\"isDir\"):\n            raise InvalidArgumentError(f\"directory index target must be a directory: {uri}\")\n\n        async def read_summaries() -> Dict[int, str]:\n            \"\"\"Read and validate existing sidecars by level.\"\"\"\n            summaries: Dict[int, str] = {}\n            names = [\".abstract.md\"] if require_abstract else [\".abstract.md\", \".overview.md\"]\n            for level, name in enumerate(names):\n                try:\n                    raw = await viking_fs.read_file(f\"{uri}/{name}\", ctx=ctx)\n                except Exception as exc:\n                    if is_not_found_error(exc):\n                        continue\n                    raise\n                try:\n                    body = body_for_preview(raw)\n                except AbstractOverviewFormatError as exc:\n                    raise InvalidArgumentError(\n                        f\"Invalid directory summary {uri}/{name}: {exc}\"\n                    ) from exc\n                if not body.strip():\n                    raise InvalidArgumentError(f\"Directory summary is empty: {uri}/{name}\")\n                summaries[level] = raw\n            return summaries\n\n        summaries = await read_summaries()\n        records = await self._directory_index_records(uri, ctx)\n        indexed = {record[\"level\"] for record in records}\n        required = {0} if require_abstract else set(summaries)\n        if required and required <= summaries.keys() & indexed:\n            return {\n                \"uri\": uri,\n                \"created_abstract\": False,\n                \"indexed_levels\": sorted(required),\n                \"vector_status\": \"complete\",\n            }\n\n        async def execute() -> Dict[str, Any]:\n            context = get_task_context()\n            assert context is not None\n            with bind_task_context(\n                context.task_id, context.account_id, context.user_id, enqueued_work=[]\n            ):\n                guard = PathLockGuard(viking_fs._async_agfs)\n                try:\n                    # Lock the parent to avoid recreating a deleted target.\n                    parent_uri = VikingURI(uri).parent.uri\n                    try:\n                        lease = await guard.acquire(\n                            lambda: viking_fs._async_agfs.pathlock_acquire_tree(\n                                viking_fs._uri_to_path(parent_uri, ctx=ctx)\n                            )\n                        )\n                    except LockAcquisitionError as exc:\n                        raise ResourceBusyError(\n                            f\"Directory is being processed: {uri}\", uri=uri\n                        ) from exc\n                    stat = await viking_fs.stat(uri, ctx=ctx, skip_count=True)\n                    if not stat.get(\"isDir\"):\n                        raise InvalidArgumentError(\n                            f\"directory index target must be a directory: {uri}\"\n                        )\n                    await viking_fs._ensure_access(uri, ctx, action=AclAction.WRITE)\n                    summaries = await read_summaries()\n                    created_abstract = 0 not in summaries if require_abstract else not summaries\n                    if created_abstract:\n                        summaries[0] = render_abstract_overview(\n                            ContextLevel.ABSTRACT,\n                            uri,\n                            fallback_abstract,\n                            {\n                                \"generated_by\": {\n                                    \"component\": \"FSService\",\n                                    \"trigger\": \"ensure_directory_index\",\n                                }\n                            },\n                        )\n                        await viking_fs.write_file(\n                            f\"{uri}/.abstract.md\", summaries[0], ctx=ctx, lease_ref=lease\n                        )\n                    records = await self._directory_index_records(uri, ctx)\n                    indexed = {record[\"level\"] for record in records}\n                    required = {0} if require_abstract else set(summaries)\n                    missing = required - indexed\n                    if created_abstract:\n                        missing.add(0)\n                        indexed.discard(0)\n                    if missing:\n                        enqueued = await vectorize_directory_meta(\n                            uri=uri,\n                            abstract=summaries.get(0, \"\"),\n                            overview=summaries.get(1, \"\"),\n                            context_type=context_type_for_uri(uri),\n                            ctx=content_owner_context_for_uri(uri, ctx),\n                            include_abstract=0 in missing,\n                            include_overview=1 in missing,\n                            scalar_overrides={\n                                record[\"level\"]: {\"_record_id\": record[\"id\"]}\n                                for record in records\n                                if record[\"level\"] in missing\n                            },\n                        )\n                        if enqueued != missing:\n                            raise OpenVikingError(\n                                f\"Failed to enqueue directory index: {uri}\", code=\"PROCESSING_ERROR\"\n                            )\n                    if missing and wait:\n                        queue_status = await self._wait_for_refresh()\n                        if (queue_status.get(\"Embedding\") or {}).get(\"error_count\", 0):\n                            raise OpenVikingError(\n                                f\"Directory index processing failed: {uri}\", code=\"PROCESSING_ERROR\"\n                            )\n                        indexed = {\n                            record[\"level\"]\n                            for record in await self._directory_index_records(uri, ctx)\n                        }\n                        if required - indexed:\n                            raise OpenVikingError(\n                                f\"Directory index is not readable: {uri}\", code=\"PROCESSING_ERROR\"\n                            )\n                    result = {\n                        \"uri\": uri,\n                        \"created_abstract\": created_abstract,\n                        \"indexed_levels\": sorted(required & indexed),\n                        \"vector_status\": \"queued\" if missing and not wait else \"complete\",\n                    }\n                    if missing and not wait:\n                        queue_manager = get_queue_manager()\n                        handoff = await guard.to_handoff()\n                        msg = ContentWriteMsg(\n                            task_id=context.task_id,\n                            operation=\"ensure_directory_index\",\n                            resource_id=uri,\n                            result=result,\n                            refresh={\n                                \"kind\": \"none\",\n                                \"uri\": parent_uri,\n                                \"indexed_levels\": sorted(summaries),\n                            },\n                            account_id=ctx.account_id,\n                            user_id=ctx.user.user_id,\n                            role=str(ctx.role),\n                            group_ids=list(ctx.group_ids),\n                            actor_peer_id=ctx.actor_peer_id,\n                            bypass_acl=ctx.bypass_acl,\n                            lock_handoff=handoff,\n                        )\n                        await guard.handoff_and_dispatch(\n                            handoff,\n                            lambda: queue_manager.enqueue(\n                                queue_manager.CONTENT_WRITE, msg.to_dict()\n                            ),\n                        )\n                    return result\n                finally:\n                    try:\n                        work_ids = get_enqueued_work_ids(\"Embedding\")\n                        if guard.lease is not None and work_ids:\n                            await run_to_completion(\n                                lambda: get_task_tracker().wait_for_work(context.task_id, work_ids)\n                            )\n                    finally:\n                        await guard.close()\n\n        result, _ = await run_tracked_operation(\n            \"ensure_directory_index\",\n            account_id=ctx.account_id,\n            user_id=ctx.user.user_id,\n            operation=execute,\n            resource_id=uri,\n            meta={\"internal\": True} if require_abstract else None,\n            wait=wait,\n        )\n        return result\n\n    async def finalize_compile_directories(self, uri: str, ctx: RequestContext) -> Dict[str, Any]:\n        \"\"\"Ensure L0 and tag only the target directory ``uri`` using ``ctx`` permissions.\n\n        Return directory_count=1 after required indexes and tags are search-visible.\n        Denied access, store errors, or visibility exceeding the directory deadline raise.\n        \"\"\"\n        viking_fs = self._ensure_initialized()\n        uri = validate_safe_viking_uri_path(uri)\n        await viking_fs._ensure_access(uri, ctx, action=AclAction.WRITE)\n        # The directory job retains its lease; Compile's wait stays cancellable.\n        with detach_task_context():\n            ensured = await run_to_completion(\n                lambda: self._ensure_directory_index(\n                    uri,\n                    ctx,\n                    fallback_abstract=\"This is the compile generated folder\",\n                    wait=False,\n                    require_abstract=True,\n                )\n            )\n        if ensured[\"vector_status\"] == \"queued\":\n            terminal = await get_task_tracker().wait(\n                ensured[\"task_id\"], account_id=ctx.account_id, user_id=ctx.user.user_id\n            )\n            if terminal.status != TaskStatus.COMPLETED:\n                raise OpenVikingError(\n                    terminal.error or f\"Directory index processing failed: {uri}\",\n                    code=\"PROCESSING_ERROR\",\n                )\n            ensured = terminal.result or {}\n            ContentWriteCoordinator._raise_refresh_errors(ensured.get(\"queue_status\", {}))\n        expected_levels = set(ensured[\"indexed_levels\"])\n        applied_levels: set[int] = set()\n        set_tags_result = None\n        loop = asyncio.get_running_loop()\n        deadline = loop.time() + _COMPILE_DIRECTORY_TAG_TIMEOUT_SECONDS\n        while True:\n            records = await self._directory_index_records(uri, ctx)\n            actual_levels = {record[\"level\"] for record in records}\n            # A temporarily invisible summary remains required once observed.\n            expected_levels.update(actual_levels)\n            untagged_levels = {\n                record[\"level\"]\n                for record in records\n                if \"compile_target=true\" not in (record.get(\"search_tags\") or [])\n            }\n            if untagged_levels - applied_levels:\n                set_tags_result = await self.set_tags(\n                    uri, [\"compile_target=true\"], mode=\"append\", recursive=False, ctx=ctx\n                )\n                # Only both updates identify the written levels across different read paths.\n                if set_tags_result.get(\"success_count\", 0) >= 2:\n                    applied_levels.update({0, 1})\n                records = await self._directory_index_records(uri, ctx)\n                actual_levels = {record[\"level\"] for record in records}\n                expected_levels.update(actual_levels)\n            tagged_levels = {\n                record[\"level\"]\n                for record in records\n                if \"compile_target=true\" in (record.get(\"search_tags\") or [])\n            }\n            if expected_levels and not expected_levels - tagged_levels:\n                break\n            remaining = deadline - loop.time()\n            if remaining <= 0:\n                details = {\n                    \"directory\": uri,\n                    \"expected_levels\": sorted(expected_levels),\n                    \"actual_levels\": sorted(actual_levels),\n                    \"tagged_levels\": sorted(tagged_levels),\n                    \"records\": records,\n                    \"set_tags_result\": set_tags_result,\n                }\n                logger.error(\"Compile directory tag validation timed out: %s\", details)\n                raise OpenVikingError(\n                    f\"Compile directory tags are incomplete: {uri}\",\n                    code=\"PROCESSING_ERROR\",\n                    details=details,\n                )\n            await asyncio.sleep(min(_COMPILE_DIRECTORY_TAG_POLL_SECONDS, remaining))\n        return {\"directory_count\": 1}\n\n    async def get_acl(self, uri: str, ctx: RequestContext) -> Dict[str, Any]:\n        return await self._ensure_initialized().get_acl(uri, ctx=ctx)\n\n    async def set_acl(\n        self,\n        uri: str,\n        entries: Optional[List[Dict[str, str]]],\n        ctx: RequestContext,\n        acl_mode: Optional[AclMode] = None,\n    ) -> Dict[str, Any]:\n        return await self._ensure_initialized().set_acl(uri, entries, ctx=ctx, acl_mode=acl_mode)\n\n    async def grant_acl(\n        self, uri: str, principal: str, level: str, ctx: RequestContext\n    ) -> Dict[str, Any]:\n        return await self._ensure_initialized().grant_acl(uri, principal, level, ctx=ctx)\n\n    async def revoke_acl(self, uri: str, principal: str, ctx: RequestContext) -> Dict[str, Any]:\n        return await self._ensure_initialized().revoke_acl(uri, principal, ctx=ctx)\n\n    async def delete_acl(self, uri: str, ctx: RequestContext) -> Dict[str, Any]:\n        return await self._ensure_initialized().delete_acl(uri, ctx=ctx)\n\n    async def commit(\n        self,\n        *,\n        message: str,\n        ctx: RequestContext,\n        paths: Optional[List[str]] = None,\n        branch: str = \"main\",\n        author_name: Optional[str] = None,\n        author_email: Optional[str] = None,\n    ) -> Dict[str, Any]:\n        \"\"\"Forward to VikingFS.commit. See viking_fs.commit for semantics.\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.commit(\n            message=message,\n            paths=paths,\n            branch=branch,\n            author_name=author_name,\n            author_email=author_email,\n            ctx=ctx,\n        )\n\n    async def restore(\n        self,\n        *,\n        project_dir: Optional[str],\n        source_commit: str,\n        ctx: RequestContext,\n        branch: str = \"main\",\n        dry_run: bool = False,\n        message: Optional[str] = None,\n        author_name: Optional[str] = None,\n        author_email: Optional[str] = None,\n    ) -> Dict[str, Any]:\n        \"\"\"Forward to VikingFS.restore. See viking_fs.restore for semantics.\"\"\"\n        viking_fs = self._ensure_initialized()\n        restore = partial(\n            viking_fs.restore,\n            project_dir=project_dir,\n            source_commit=source_commit,\n            branch=branch,\n            dry_run=dry_run,\n            message=message,\n            author_name=author_name,\n            author_email=author_email,\n            ctx=ctx,\n            record_restore=(\n                partial(self.compile_versions.record_restored, ctx=ctx)\n                if self.compile_versions is not None and not dry_run\n                else None\n            ),\n        )\n        if self.compile_versions is None or dry_run:\n            return await restore()\n        return await self.compile_versions.record_operation(\n            [\n                viking_fs._tree_path_to_uri(\n                    viking_fs._uri_to_tree_path(project_dir, ctx=ctx)\n                ).rstrip(\"/\")\n                if project_dir\n                else \"viking://\"\n            ],\n            ctx,\n            \"restore\",\n            {\"source_commit\": source_commit, \"branch\": branch},\n            restore,\n            recursive=True,\n        )\n\n    async def show(\n        self,\n        target_ref: str,\n        ctx: RequestContext,\n        *,\n        path: Optional[str] = None,\n    ) -> Any:\n        \"\"\"Forward to VikingFS.show. Returns dict (metadata) or bytes (blob).\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.show(target_ref, path=path, ctx=ctx)\n\n    async def show_blob_raw(\n        self,\n        target_ref: str,\n        ctx: RequestContext,\n        *,\n        path: str,\n    ) -> Dict[str, Any]:\n        \"\"\"Forward to VikingFS.show_blob_raw. Returns ``{\"oid\", \"size\", \"bytes\"}``.\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.show_blob_raw(target_ref, path=path, ctx=ctx)\n\n    async def diff(\n        self,\n        *,\n        path: str,\n        from_ref: Optional[str],\n        to_ref: str,\n        raw: bool = True,\n        ctx: RequestContext,\n    ) -> Dict[str, Any]:\n        \"\"\"Return a unified text diff for one path between two snapshots.\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.diff(\n            path=path,\n            from_ref=from_ref,\n            to_ref=to_ref,\n            raw=raw,\n            ctx=ctx,\n        )\n\n    async def diff_paths(\n        self,\n        paths: List[str],\n        *,\n        from_ref: Optional[str],\n        to_ref: str,\n        ctx: RequestContext,\n        offset: int = 0,\n        limit: int = 100,\n    ) -> Dict[str, Any]:\n        \"\"\"Page changed source URIs between snapshots; a null base means an empty tree.\n\n        Every changed path requires current read permission, including deleted paths.\n        Any denied descendant rejects the whole query without exposing its URI.\n        \"\"\"\n        viking_fs = self._ensure_initialized()\n        if not paths or not to_ref.strip() or (from_ref is not None and not from_ref.strip()):\n            raise InvalidArgumentError(\"paths and non-empty snapshot refs are required\")\n        if offset < 0 or not 1 <= limit <= 1000:\n            raise InvalidArgumentError(\"offset must be non-negative and limit must be 1..1000\")\n        changes = await viking_fs.diff_paths(\n            dirs=list(dict.fromkeys(paths)), base=from_ref, head=to_ref, ctx=ctx\n        )\n        changes_by_uri = {change[\"uri\"]: change for change in changes}\n        uris = sorted(changes_by_uri)\n        access = await viking_fs._can_access_many(uris, ctx, action=AclAction.READ)\n        if any(not access.get(uri, False) for uri in uris):\n            raise PermissionDeniedError(\"Snapshot changes include inaccessible paths\")\n        page = [changes_by_uri[uri] for uri in uris[offset : offset + limit]]\n        next_offset = offset + len(page)\n        has_more = next_offset < len(uris)\n        return {\n            \"changes\": page,\n            \"offset\": offset,\n            \"limit\": limit,\n            \"total\": len(uris),\n            \"has_more\": has_more,\n            \"next_offset\": next_offset if has_more else None,\n        }\n\n    async def log(\n        self,\n        ctx: RequestContext,\n        *,\n        branch: str = \"main\",\n        limit: int = 20,\n        paths: Optional[List[str]] = None,\n    ) -> List[Dict[str, Any]]:\n        \"\"\"Forward to VikingFS.log. Walks parents[0] up to limit commits.\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.log(branch=branch, limit=limit, paths=paths, ctx=ctx)\n\n    async def get_gitignore(self, *, ctx: RequestContext) -> str:\n        \"\"\"Forward to VikingFS.get_gitignore. Returns the account .ovgitignore\n        content, or an empty string if absent.\"\"\"\n        viking_fs = self._ensure_initialized()\n        return await viking_fs.get_gitignore(ctx=ctx)\n\n    async def set_gitignore(self, *, content: str, ctx: RequestContext) -> None:\n        \"\"\"Forward to VikingFS.set_gitignore. Writes the account .ovgitignore\n        control file (validates the size limit).\"\"\"\n        viking_fs = self._ensure_initialized()\n        await viking_fs.set_gitignore(content, ctx=ctx)\n\n    async def delete_gitignore(self, *, ctx: RequestContext) -> None:\n        \"\"\"Forward to VikingFS.delete_gitignore. Removes the account\n        .ovgitignore; missing is success.\"\"\"\n        viking_fs = self._ensure_initialized()\n        await viking_fs.delete_gitignore(ctx=ctx)\n"
