      "path": "openviking/utils/summarizer.py",
      "content": "# Copyright (c) 2026 Beijing Volcano Engine Technology Co., Ltd.\n# SPDX-License-Identifier: AGPL-3.0\n\"\"\"Summarizer for OpenViking.\n\nHandles summarization and key information extraction.\n\"\"\"\n\nfrom collections import defaultdict\nfrom dataclasses import dataclass, field\nfrom typing import TYPE_CHECKING, Any, Dict, List, Optional, Sequence, Tuple\n\nfrom openviking.core.namespace import context_type_for_uri\nfrom openviking.storage.pathlock_transfer import PathLockGuard\nfrom openviking.storage.queuefs import SemanticMsg, get_queue_manager\nfrom openviking.storage.queuefs.semantic_msg import build_semantic_coalesce_key\nfrom openviking.storage.viking_fs import LS_ALL_NODES, get_viking_fs\nfrom openviking.telemetry import get_current_telemetry\nfrom openviking.utils.ingest_options import IngestOptions\nfrom openviking_cli.utils import get_logger\nfrom openviking_cli.utils.uri import VikingURI\n\nif TYPE_CHECKING:\n    from openviking.parse.vlm import VLMProcessor\n    from openviking.server.identity import RequestContext\n\nlogger = get_logger(__name__)\n\n\n@dataclass(frozen=True)\nclass FileRefreshRequest:\n    \"\"\"One committed flat-file change awaiting parent semantic maintenance.\n\n    This is an execution-time input for the shared summarizer, not a durable\n    RNFV or queue schema.  A batch coordinator collects one request per\n    successfully committed file and lets :meth:`refresh_file_parents` coalesce\n    them by direct parent.\n    \"\"\"\n\n    file_uri: str\n    created: bool = False\n    md5: str | None = None\n    abstract: str = \"\"\n    vector_action: str = \"\"\n    ingest_options: IngestOptions = field(default_factory=IngestOptions)\n\n    def __post_init__(self) -> None:\n        if self.vector_action not in {\"\", \"upsert\", \"merge\"}:\n            raise ValueError(f\"unsupported file vector action: {self.vector_action}\")\n\n\nclass Summarizer:\n    \"\"\"\n    Handles summarization of resources.\n    \"\"\"\n\n    def __init__(self, vlm_processor: \"VLMProcessor\"):\n        self.vlm_processor = vlm_processor\n\n    async def refresh_file_parent(\n        self,\n        *,\n        file_uri: str,\n        ctx: \"RequestContext\",\n        lock_handoff: Dict[str, Any] | None = None,\n        skip_vectorization: bool = False,\n        ingest_options: IngestOptions | None = None,\n        created: bool = False,\n        file_md5: str | None = None,\n        file_abstract: str = \"\",\n        file_vector_action: str = \"\",\n        generation_trigger: str = \"semantic_refresh\",\n        force_refresh: bool | None = None,\n    ) -> Dict[str, Any]:\n        \"\"\"Summarize one flat file and refresh its parent directory semantics.\n\n        ``force_refresh`` controls parent-directory aggregation. ``None`` (the\n        default used by resource ingest) always aggregates immediately. A boolean\n        opts into the freshness gate: the changed file is still summarized and\n        vectorized, but parent L0/L1 aggregation is deferred by the freshness\n        policy unless ``force_refresh`` is ``True``. The returned\n        ``semantic_action`` reports the gate decision so callers can surface a\n        ``deferred``/``skipped`` status.\n        \"\"\"\n        parent = VikingURI(file_uri).parent\n        if parent is None:\n            return {\"status\": \"error\", \"message\": f\"file has no parent URI: {file_uri}\"}\n        result = await self.refresh_file_parents(\n            changes=(\n                FileRefreshRequest(\n                    file_uri=file_uri,\n                    created=created,\n                    md5=file_md5,\n                    abstract=file_abstract,\n                    vector_action=file_vector_action,\n                    ingest_options=IngestOptions.from_value(ingest_options),\n                ),\n            ),\n            ctx=ctx,\n            lock_handoff=lock_handoff,\n            skip_vectorization=skip_vectorization,\n            ingest_options=ingest_options,\n            generation_trigger=generation_trigger,\n            force_refresh=force_refresh,\n        )\n        return {\n            \"status\": \"success\",\n            \"enqueued_count\": result[\"enqueued_count\"],\n            \"semantic_action\": result[\"parent_actions\"][parent.uri.rstrip(\"/\")],\n        }\n\n    async def refresh_file_parents(\n        self,\n        *,\n        changes: Sequence[FileRefreshRequest],\n        ctx: \"RequestContext\",\n        lock_handoff: Dict[str, Any] | None = None,\n        skip_vectorization: bool = False,\n        ingest_options: IngestOptions | None = None,\n        generation_trigger: str = \"semantic_refresh\",\n        force_refresh: bool | None = None,\n    ) -> Dict[str, Any]:\n        \"\"\"Queue flat-file semantic maintenance grouped by each direct parent.\n\n        A file remains the RNFV planning unit, while this execution helper owns\n        the batch-only concern: one freshness decision and at most one\n        ``SemanticMsg`` for every direct parent directory.\n        \"\"\"\n        from openviking.storage.abstract_overview import plan_abstract_overview_refresh\n        from openviking.storage.errors import LockAcquisitionError\n        from openviking.storage.queuefs.semantic_ops.freshness_policy import FreshnessAction\n        from openviking_cli.utils.config import get_openviking_config\n\n        grouped: dict[str, list[FileRefreshRequest]] = defaultdict(list)\n        for change in changes:\n            parent = VikingURI(change.file_uri).parent\n            if parent is None:\n                raise ValueError(f\"file has no parent URI: {change.file_uri}\")\n            grouped[parent.uri.rstrip(\"/\")].append(change)\n\n        if not grouped:\n            return {\"status\": \"success\", \"enqueued_count\": 0, \"parent_actions\": {}}\n        if lock_handoff is not None and len(grouped) != 1:\n            raise ValueError(\"one semantic lock handoff requires exactly one parent refresh\")\n\n        queue_manager = get_queue_manager()\n        semantic_queue = queue_manager.get_queue(queue_manager.SEMANTIC, allow_create=True)\n        telemetry_id = get_current_telemetry().telemetry_id\n        parent_actions: dict[str, str] = {}\n        enqueued_count = 0\n        for parent_uri, parent_changes in sorted(grouped.items()):\n            context_types = {context_type_for_uri(change.file_uri) for change in parent_changes}\n            if len(context_types) != 1:\n                raise ValueError(f\"mixed context types under parent refresh: {parent_uri}\")\n            context_type = context_types.pop()\n            added = sorted(change.file_uri for change in parent_changes if change.created)\n            modified = sorted(change.file_uri for change in parent_changes if not change.created)\n\n            semantic_action = FreshnessAction.REFRESH_NOW\n            if force_refresh is not None:\n                semantic_config = get_openviking_config().semantic\n                try:\n                    decision = await plan_abstract_overview_refresh(\n                        viking_fs=get_viking_fs(),\n                        dir_uri=parent_uri,\n                        changed_entries=len(parent_changes),\n                        ctx=ctx,\n                        overview_sample_limit=getattr(semantic_config, \"overview_sample_limit\", 32),\n                        refresh_ratio=getattr(semantic_config, \"freshness_refresh_ratio\", 0.10),\n                        force_refresh=force_refresh,\n                    )\n                    semantic_action = decision.action\n                except LockAcquisitionError:\n                    # Parent aggregation is best-effort; changed-file work still runs.\n                    logger.info(\"Skipping busy parent semantic refresh: %s\", parent_uri)\n                    semantic_action = FreshnessAction.NOOP\n            parent_actions[parent_uri] = semantic_action.value\n            aggregate_directory = semantic_action is FreshnessAction.REFRESH_NOW\n\n            msg = SemanticMsg(\n                uri=parent_uri,\n                context_type=context_type,\n                recursive=False,\n                account_id=ctx.account_id,\n                user_id=ctx.user.user_id,\n                peer_id=ctx.user.user_id,\n                role=str(ctx.role),\n                lock_handoff=lock_handoff,\n                skip_vectorization=skip_vectorization,\n                telemetry_id=telemetry_id,\n                changes={\n                    change_type: uris\n                    for change_type, uris in ((\"added\", added), (\"modified\", modified))\n                    if uris\n                },\n                coalesce_key=(\n                    build_semantic_coalesce_key(\n                        context_type=context_type,\n                        uri=parent_uri,\n                        account_id=ctx.account_id,\n                        user_id=ctx.user.user_id,\n                        peer_id=ctx.user.user_id,\n                    )\n                    if aggregate_directory and lock_handoff is None\n                    else \"\"\n                ),\n                generation_trigger=generation_trigger,\n                aggregate_directory=aggregate_directory,\n                ingest_options=ingest_options,\n                file_md5s={change.file_uri: change.md5 for change in parent_changes if change.md5}\n                or None,\n                file_abstracts={\n                    change.file_uri: change.abstract for change in parent_changes if change.abstract\n                }\n                or None,\n                file_vector_actions={\n                    change.file_uri: change.vector_action\n                    for change in parent_changes\n                    if change.vector_action\n                },\n                file_ingest_options={\n                    change.file_uri: change.ingest_options\n                    for change in parent_changes\n                    if change.ingest_options != IngestOptions()\n                },\n            )\n            enqueue_id = await semantic_queue.enqueue(msg)\n            if enqueue_id == \"deduplicated\":\n                continue\n            else:\n                enqueued_count += 1\n        return {\n            \"status\": \"success\",\n            \"enqueued_count\": enqueued_count,\n            \"parent_actions\": parent_actions,\n        }\n\n    async def summarize(\n        self,\n        resource_uris: List[str],\n        ctx: \"RequestContext\",\n        skip_vectorization: bool = False,\n        lock: Optional[Dict[str, Any] | PathLockGuard] = None,\n        **kwargs,\n    ) -> Dict[str, Any]:\n        \"\"\"\n        Summarize the given resources.\n        Triggers SemanticQueue to generate .abstract.md and .overview.md.\n        \"\"\"\n        queue_manager = get_queue_manager()\n        semantic_queue = queue_manager.get_queue(queue_manager.SEMANTIC, allow_create=True)\n\n        temp_uris = kwargs.get(\"temp_uris\", [])\n        ingest_options = IngestOptions.from_value(kwargs.get(\"ingest_options\"))\n        source = kwargs.get(\"semantic_source\")\n        generation_trigger = str(kwargs.get(\"generation_trigger\") or \"manual_refresh\")\n        # Pre-computed change set (local incremental import): when present, the\n        # semantic tree restricts re-summarization/vectorization to these files\n        # instead of diffing the whole tree.\n        changes = kwargs.get(\"changes\")\n        # Per-file md5 (target-URI keyed) for those changed files, so the tree executor's\n        # re-vectorization records the fresh fingerprint.\n        file_md5s = kwargs.get(\"file_md5s\") or {}\n        artifact_ref = kwargs.get(\"artifact_ref\")\n        artifact_files = kwargs.get(\"artifact_files\") or []\n        file_abstracts = kwargs.get(\"file_abstracts\") or {}\n        semantic_plan = kwargs.get(\"semantic_plan\")\n        if not temp_uris:\n            temp_uris = resource_uris\n        if len(temp_uris) != len(resource_uris):\n            logger.error(\n                f\"temp_uris length ({len(temp_uris)}) must match resource_uris length ({len(resource_uris)})\"\n            )\n            return {\n                \"status\": \"error\",\n                \"message\": \"temp_uris length must match resource_uris length\",\n            }\n        if lock is not None and len(resource_uris) != 1:\n            raise ValueError(\"one semantic lock handoff requires exactly one resource\")\n        enqueued_count = 0\n\n        telemetry = get_current_telemetry()\n        agfs = get_viking_fs()._async_agfs\n        lock_guard = (\n            lock\n            if isinstance(lock, PathLockGuard)\n            else PathLockGuard(agfs, lock) if lock is not None else None\n        )\n        lock_handoff: Optional[Dict[str, Any]] = None\n        if lock_guard is not None:\n            lock_handoff = await lock_guard.to_handoff()\n\n        def is_resources_root(uri: str) -> bool:\n            return (uri or \"\").rstrip(\"/\") == \"viking://resources\"\n\n        async def list_top_children(temp_uri: str) -> List[Tuple[str, str]]:\n            viking_fs = get_viking_fs()\n            entries = await viking_fs.ls(\n                temp_uri, show_all_hidden=True, node_limit=LS_ALL_NODES, ctx=ctx\n            )\n            children: List[Tuple[str, str]] = []\n            for entry in entries:\n                name = entry.get(\"name\", \"\")\n                if not name or name in {\".\", \"..\"}:\n                    continue\n                child_temp_uri = VikingURI(temp_uri).join(name).uri\n                children.append((name, child_temp_uri))\n            return children\n\n        for uri, temp_uri in zip(resource_uris, temp_uris, strict=True):\n            # Determine context_type based on URI\n            context_type = context_type_for_uri(uri)\n\n            enqueue_units: List[Tuple[str, str]] = []\n            if is_resources_root(uri) and uri != temp_uri and lock_handoff is None:\n                children = await list_top_children(temp_uri)\n                if not children:\n                    return {\n                        \"status\": \"error\",\n                        \"message\": f\"no top-level import items found under temp uri: {temp_uri}\",\n                    }\n                for name, child_temp_uri in children:\n                    child_target_uri = VikingURI(\"viking://resources\").join(name).uri\n                    enqueue_units.append((child_target_uri, child_temp_uri))\n            else:\n                enqueue_units.append((uri, temp_uri))\n\n            for target_uri, source_uri in enqueue_units:\n                msg = SemanticMsg(\n                    uri=source_uri,\n                    context_type=context_type,\n                    account_id=ctx.account_id,\n                    user_id=ctx.user.user_id,\n                    group_ids=ctx.group_ids,\n                    peer_id=ctx.user.user_id,\n                    role=str(ctx.role),\n                    skip_vectorization=skip_vectorization,\n                    telemetry_id=telemetry.telemetry_id,\n                    target_uri=target_uri if target_uri != source_uri else None,\n                    lock_handoff=lock_handoff,\n                    is_code_repo=kwargs.get(\"is_code_repo\", False),\n                    ingest_options=ingest_options,\n                    source=source,\n                    generation_trigger=generation_trigger,\n                    changes=changes,\n                    file_md5s=file_md5s,\n                    artifact_ref=artifact_ref,\n                    artifact_files=artifact_files,\n                    file_abstracts=file_abstracts,\n                    plan=semantic_plan,\n                )\n                try:\n                    if lock_guard is None:\n                        enqueue_id = await semantic_queue.enqueue(msg)\n                    else:\n                        enqueue_id = await lock_guard.handoff_and_dispatch(\n                            lock_handoff,\n                            lambda msg=msg: semantic_queue.enqueue(msg),\n                            accepted=lambda result: result != \"deduplicated\",\n                        )\n                except BaseException:\n                    if (\n                        isinstance(lock, dict)\n                        and lock_guard is not None\n                        and lock_guard.lease is not None\n                        and lock_guard.lease is not lock\n                    ):\n                        lock.clear()\n                        lock.update(lock_guard.lease)\n                    raise\n                if enqueue_id == \"deduplicated\":\n                    logger.info(\"Semantic generation already queued for: %s\", target_uri)\n                    continue\n                enqueued_count += 1\n                logger.info(\n                    f\"Enqueued semantic generation for: {target_uri} (skip_vectorization={skip_vectorization})\"\n                )\n\n        return {\n            \"status\": \"success\",\n            \"enqueued_count\": enqueued_count,\n            \"lock_handed_off\": lock_guard is not None and lock_guard.transferred,\n        }\n"
    }
